'use strict';

import {hasPrimaryModifier} from 'diagram-js/lib/util/Mouse';

/**
 * Changes the default SelectionBehavior to support double-click, and also
 * disable the selection toggle on single-click.
 *
 * @param {EventBus} eventBus the event register with which all handlers are registered.
 * @param {Selection} selection the selection service that maintains the register of selected elements.
 * @param {Canvas} canvas the canvas on which the model is being constructed.
 * @param {ElementRegistry} elementRegistry the register of all model elements.
 * @param {EditorActions} editorActions the register of model editor actions, allowing actions to be triggered.
 */
function ProcessSelectionBehavior(eventBus, selection, canvas, elementRegistry, editorActions) {
    var self = this;

    // used to determine whether a click is part of a dbl-click
    self.dblClickTime = 0;

    // dbl-click selection
    eventBus.on('element.dblclick', function(event) {
        self.dblClickTime = new Date();
        self.onDblClick(event, selection, canvas, elementRegistry, editorActions)
    });

    // click selection
    // use a higher priority to override the default handler
    eventBus.on('element.click', 2000, function(event) {
        // prevent default handler from being called
        event.stopPropagation();

        // wait to see if dbl-click was called
        var delay = 100;
        var now = new Date();
        if (now - self.dblClickTime > delay) {
            setTimeout(function() {
                if (now - self.dblClickTime > delay) {
                    self.onClick(event, selection, canvas, elementRegistry, editorActions);
                }
            }, delay);
        }
    });
}

ProcessSelectionBehavior.$inject = [ 'eventBus', 'selection', 'canvas', 'elementRegistry', 'editorActions' ];


/**
 * Implements the mouse double-click event handler. This is a no-op function.
 *
 * @param {Event} event the click event; wraps the original UI event with the model element.
 * @param {Selection} selection the selection service that maintains the register of selected elements.
 * @param {Canvas} canvas the canvas on which the model is being constructed.
 * @param {ElementRegistry} elementRegistry the register of all model elements.
 * @param {EditorActions} editorActions the register of model editor actions, allowing actions to be triggered.
 */
ProcessSelectionBehavior.prototype.onDblClick = function(event, selection, canvas, elementRegistry, editorActions) {
    editorActions.trigger('openProperties');
};

/**
 * Implements the mouse click event handler. This will select or deselect the target
 * element.
 *
 * @param {Event} event the click event; wraps the original UI event with the model element.
 * @param {Selection} selection the selection service that maintains the register of selected elements.
 * @param {Canvas} canvas the canvas on which the model is being constructed.
 * @param {ElementRegistry} elementRegistry the register of all model elements.
 * @param {EditorActions} editorActions the register of model editor actions, allowing actions to be triggered.
 */
ProcessSelectionBehavior.prototype.onClick = function(event, selection, canvas, elementRegistry, editorActions) {
    var element = event.element;

    var isSelected = selection.isSelected(element),
        isMultiSelect = selection.get().length > 1;

    // mouse-event: SELECTION_KEY
    var add = hasPrimaryModifier(event);

    // select OR deselect element in multi selection
    if (isSelected && isMultiSelect) {
        if (add) {
            // deselect this element (toggle)
            selection.deselect(element);
        } else {
            // select this element - deselecting all others
            selection.select(element);
        }
    } else if (!isSelected) {
        if (add) {
            editorActions.trigger('closeProperties');
        }
        selection.select(element, add);
    }
};

export default ProcessSelectionBehavior;