import inherits from 'inherits';
import SpaceTool from 'diagram-js/lib/features/space-tool/SpaceTool';
import { is } from '../modeling/util/LaneUtil'

export default function DtSpaceTool(injector) {
    injector.invoke(SpaceTool, this);
}

DtSpaceTool.$inject = ['injector'];

inherits(DtSpaceTool, SpaceTool);


/**
 * @param {Shape[]} elements
 * @param {Axis} axis
 * @param {Point} delta
 * @param {number} start
 *
 * @return {Object}
 */
DtSpaceTool.prototype.calculateAdjustments = function(elements, axis, delta, start) {
    var adjustments = SpaceTool.prototype.calculateAdjustments.call(this, elements, axis, delta, start);

    // do not resize: text annotations (horizontally/vertically)
    adjustments.resizingShapes = adjustments.resizingShapes.filter(function(shape) {
        return !is(shape, 'bp:TextAnnotation');
    });

    return adjustments;
};
