'use strict';


import assign from 'lodash/assign';
import isEmpty from 'lodash/isEmpty';
import {instanceOf} from '../modeling/ModelUtil';

/**
 * Context pad provider for tasks inside sub process
 */
function SubProcessContextPadProvider(dtContextPad, modeling, processDiagramRules, selection) {

    dtContextPad.registerProvider(this);
    this._modeling = modeling;
    this._processDiagramRules = processDiagramRules;
    this._selection = selection;
}

SubProcessContextPadProvider.$inject = [
    'dtContextPad',
    'modeling',
    'processDiagramRules',
    'selection'
];


SubProcessContextPadProvider.prototype.getContextPadEntries = function (element) {

    var modeling = this._modeling,
        selection = this._selection;
    var processDiagramRules = this._processDiagramRules;

    var actions = {};

    /*
     * CBPM-15568 :- Chaitanya , to avoid showing process-editor-toolbox on when the element is hidden
     */
    if (element.type === 'label' || element.hidden) {
        return actions;
    }

    var businessObject = element.businessObject;


    /**
     * Return the disable chatbot command if it's already enabled.
     */
    function getDisableChatBotCommand(formTaskShape) {
        var commands = [];
        if(formTaskShape){
            var formTask = formTaskShape.businessObject;
            var updateConfig = formTask.platformConfig ? formTask.platformConfig.chatBotEnabled : false;
            if(updateConfig){
                var cmd1 = modeling.setCommand(formTask,
                    formTaskShape, formTask.platformConfig, 'chatBotEnabled', false);
                commands.push(cmd1);
            }
        }
        return commands;
    }

    function addCalcTaskToSubProcess(event, formTaskShape) {
        modeling.appendTaskToSubProcess(formTaskShape.parent, formTaskShape, ['bp:ScriptTask'], getDisableChatBotCommand(formTaskShape),
            {taskType: 'CalculationTask'});
        selection.select(formTaskShape.parent);
    }

    function addTciTaskToSubProcess(event, formTaskShape) {
        modeling.appendTaskToSubProcess(formTaskShape.parent, formTaskShape, ['bp:TciServiceTask'], getDisableChatBotCommand(formTaskShape),
            {excludeEmptyOptionalInput: true});
        selection.select(formTaskShape.parent);
    }

    function addFormTaskToSubProcess(event, element) {
        modeling.appendTaskToSubProcess(element.parent, element, ['bp:FormTask']);
        selection.select(element.parent);
    }

    function isLastFormTask(businessObject){
        return instanceOf(businessObject, 'bp:FormTask') && isEmpty(businessObject.outgoing);
    }
    // Add - Don't show add to SubProcess icon if the selected object is not a SubProcess */
    if (processDiagramRules.isContainedInInitialTaskSubProcess(businessObject) && isEmpty(businessObject.incoming)) {
        if (isLastFormTask(businessObject)) {
            assign(actions, {
                'addTciToSubProc': {
                    className: 'dt-bpm-icon-ic_add_tci_task dt-hand-pointer',
                    title: 'Insert a data service task before this task',
                    group: 'tci',
                    action: {
                        click: addTciTaskToSubProcess
                    }
                }
            });

            assign(actions, {
                'addCalcToSubProc': {
                    className: 'dt-bpm-icon-ic_add_calc_task dt-hand-pointer',
                    title: 'Insert a calculation task before this task',
                    group: 'calc',
                    action: {
                        click: addCalcTaskToSubProcess
                    }
                }
            });
        } else if (instanceOf(businessObject, ['bp:TciServiceTask', 'bp:EmptyTask']) ||
            (instanceOf(businessObject, 'bp:ScriptTask') && businessObject.taskType === 'CalculationTask')) {
            assign(actions, {
                'addFormTaskToSubProc': {
                    className: 'dt-bpm-icon-ic_add_form_task dt-hand-pointer',
                    title: 'Insert a creation task before this task',
                    group: 'form',
                    action: {
                        click: addFormTaskToSubProcess
                    }
                }
            });
        }

        return actions;
    }
};

export default SubProcessContextPadProvider;