'use strict';

import inherits from "inherits";
import MoveEvents from "diagram-js/lib/features/move/Move";

var HIGH_PRIORITY = 1500;


export default function ProcessMoveEvents(
    injector) {

    var eventBus = injector.get('eventBus');
    var modeling = injector.get('modeling');
    var processDiagramRules = injector.get('processDiagramRules');

    // override the 'shape.move.end' event
    eventBus.on('shape.move.end', HIGH_PRIORITY, function (event) {

        var context = event.context;

        var canExecute = context.canExecute,
            target = context.target,
            shapeBeingMoved = context.shape;

        if (canExecute === false) {
            return false;
        }
        if (processDiagramRules.isParallelLane(target) && processDiagramRules.isParallelLane(shapeBeingMoved)) {
            var parent = context.shape.parent;
            var destIndex = parent.children.indexOf(target);
            var srcIndex = parent.children.indexOf(shapeBeingMoved);
            event.stopPropagation();
            modeling.moveParallelFlowLane(shapeBeingMoved, destIndex, srcIndex);
        }
    });
}

ProcessMoveEvents.$inject = ['injector'];

inherits(ProcessMoveEvents, MoveEvents);
