'use strict';

import { getLanesRoot, LANE_INDENTATION } from "../util/LaneUtil";


/**
 * A handler that allows us to add a new lane above or below an existing one.
 *
 * @class
 * @constructor
 */
function AddLaneHandler(modeling, rules, elementFactory, spaceTool) {
    this._modeling = modeling;
    this._rules = rules;
    this._elementFactory = elementFactory;
    this._spaceTool = spaceTool;
}

AddLaneHandler.$inject = ['modeling', 'rules', 'elementFactory', 'spaceTool'];


AddLaneHandler.prototype.preExecute = function (context) {

    var spaceTool = this._spaceTool,
        elementFactory = this._elementFactory,
        modeling = this._modeling;

    var shape = context.shape,
        location = context.location;

    var lanesRoot = getLanesRoot(shape);

    var isRoot = lanesRoot === shape,
        laneParent = isRoot ? shape : shape.parent;

    var lanePosition = location === 'top' ? shape.y + LANE_INDENTATION : shape.y + shape.height;


    var newLane = {
        type: 'bp:SubProcess',
        subProcessType: 'ParallelLane',
        parent: laneParent,
    };
    // (1) create new lane at open space
    context.newLane = modeling.createShape(newLane, {
        x: shape.x,
        y: lanePosition - (location === 'top' ? 180 : 0),
        width: shape.width,
        height: 180
    }, laneParent);

    var emptyTask1 =  {
        type: 'bp:EmptyTask',
    };
    var heightOfTask = 120;

    // (2) add empty task in the lane.
    modeling.createShape(emptyTask1, {
        x: shape.x + heightOfTask,
        y:  lanePosition + 90
    }, context.newLane);


};

export default AddLaneHandler;