'use strict';

import BaseLayouter from 'diagram-js/lib/layout/BaseLayouter';
import * as ManhattanLayout from 'diagram-js/lib/layout/ManhattanLayout';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';
import assign from 'lodash/assign';
import inherits from 'inherits';
import {isOfType} from '../ModelUtil';

/**
 * An implementation of a base connection layouter for process
 * that uses manhattan strategy for laying out connections.
 */
function ProcessLayouter() {
    BaseLayouter.call(this);
}

inherits(ProcessLayouter, BaseLayouter);



/**
 * Return the new layouted waypoints for the given connection.
 *
 * @param {djs.model.Connection} connection
 * @param {djs.model.Connection} connection.waypoints
 * @param {djs.model.Connection} connection.source
 * @param {djs.model.Connection} connection.target
 * @param {Object} hints
 * @param {Boolean} [hints.connectionStart=false]
 * @param {Boolean} [hints.connectionEnd=false]
 * @param {Boolean} [hints.movedStart=false]
 * @param {Boolean} [hints.movedEnd=false]
 *
 * @return {Array<Point>} the layouted connection waypoints
 */
ProcessLayouter.prototype.layoutConnection = function(connection, hints) {
    if (!hints) {
        hints = {};
    }

    var manhattanHints;
    var waypoints = connection.waypoints;
    var source = hints.source || connection.source;
    var target = hints.target || connection.target;
    var firstPoint = hints && hints.connectionStart;
    var lastPoint = hints && hints.connectionEnd;

    if (isOfType(source, 'bp:ExclusiveGateway')) {
        manhattanHints = {
            preferredLayouts: [ 'v:h' ]
        };
    } else if (isOfType(target, 'bp:ExclusiveGateway')) {
        manhattanHints = {
            preferredLayouts: [ 'h:v' ]
        };
    } else {
        // default
        manhattanHints = {
            preferredLayouts: [ 'h:h' ]
        };
    }

    if (!firstPoint) {
        firstPoint = getConnectionDocking(waypoints && waypoints[0], source);
    }
    if (!lastPoint) {
        lastPoint = getConnectionDocking(waypoints && waypoints[waypoints.length - 1], target);
    }

    manhattanHints = assign(manhattanHints, hints);

    var newWaypoints =
        ManhattanLayout.repairConnection(
            source, target,
            firstPoint, lastPoint,
            waypoints,
            manhattanHints);

    if (!newWaypoints || newWaypoints.length < 2) {
        newWaypoints = BaseLayouter.prototype.layoutConnection(connection, hints);
    }

   return newWaypoints;


};

/**
 * Get the docking point for first or for the last waypoint.
 *
 * @param connection - the shape (either connection source or target)
 * @param isSource - true if it's the source side of connection (otherwise target).
 * @return {Point} the docking point for start or end of connection.
 */
function getDockingPoint(connection, isSource, source) {
    var point;
    var waypoints = connection.waypoints;

    if (waypoints && waypoints.length > 0) {
        point = isSource ? waypoints[0]: waypoints[waypoints.length - 1];
        if (point) {
            return point.original || point;
        }
    }
    return getMid(isSource? connection.source: connection.target);
}

export default ProcessLayouter;


function getConnectionDocking(point, shape) {
    return point ? (point.original || point) : getMid(shape);
}