'use strict';

import assign from 'lodash/assign';
import inherits from 'inherits';


import * as LabelUtil from './LabelUtil';
import {instanceOf} from '../modeling/ModelUtil';
import {getBusinessObject} from '../modeling/ModelUtil';

var hasExternalLabel = LabelUtil.hasExternalLabel,
    getExternalLabelMid = LabelUtil.getExternalLabelMid,
    getLabelProperty = LabelUtil.getLabelProperty,
    getExternalLabelBounds = LabelUtil.getExternalLabelBounds,
    getMidpointsDelta = LabelUtil.getMidpointsDelta,
    DEFAULT_LABEL_SIZE = LabelUtil.DEFAULT_LABEL_SIZE;

import TextUtil from 'diagram-js/lib/util/Text';

import CommandInterceptor from 'diagram-js/lib/command/CommandInterceptor';
import tsvgClasses from 'tiny-svg/lib/classes';

function LabelSupport(eventBus, modeling, elementFactory, dtDiagram, elementRegistry) {

    CommandInterceptor.call(this, eventBus);

    var textUtil = new TextUtil({
        style: {
            //fontFamily: '"Source Sans Pro", Arial, sans-serif',
            //fontSize: '12px'
        },
        size: {width: DEFAULT_LABEL_SIZE.width}
    });

    // create external labels on shape creation

    this.postExecute(['shape.create', 'connection.create'], function (e) {
        var context = e.context;

        var element = context.shape || context.connection,
            businessObject = element.businessObject;

        var position;

        if (hasExternalLabel(businessObject)) {
            position = getExternalLabelMid(element);
            modeling.createLabel(element, position, {
                id: businessObject.id + '_label',
                hidden: false,
                businessObject: businessObject
            });
        }
    });

    /** Updates label's bounding box (hight) to match the text size. */
    this.postExecute(['tibextProcessCommand'], function (e) {
        var context = e.context;

        if (context && context.commands && context.commands.length) {
            context.commands.forEach(function (cmd) {
                if (cmd && cmd.type === 'tibext.set' && hasExternalLabel(cmd.element) &&
                     getLabelProperty(cmd.element).includes(cmd.attribute)) {

                    var diElement = cmd.element.diElement;
                    if (diElement && diElement.label) {
                        var djsObject = dtDiagram.getDiagramObject(cmd.element);
                        if (djsObject && djsObject.label) {
                            var label = djsObject.label;
                            var newValue = cmd.value;
                            var gfx = elementRegistry.getGraphics(label);

                            //A trick to pre-create text to estimate label height.
                            var textGfx = textUtil.createText(newValue, {
                                box: label,
                                style: {}
                            });
                            tsvgClasses(textGfx).add('djs-label').add('process-label');
                            //JA: getBbox no longer work after djs changes. Throws 'NS_ERROR_FAILURE' exception on FF and returns
                            // object with 0s in Chrome.
                            // var bounds = textGfx.getBBox();

                            // elementRegistry.remove(textGfx);
                            // textGfx.remove();
                            var height = Math.max(DEFAULT_LABEL_SIZE.height, label.height);

                            var newBounds = {x: label.x, y: label.y, width: label.width, height: height};

                            //Reset to default bounds if label is being shown (set from en empty string).
                            if ((!cmd.oldValue || cmd.oldValue === '') && cmd.newValue !== '') {
                                newBounds = getExternalLabelBounds(cmd.element, djsObject, true);
                            }

                            modeling.resizeShape(label, newBounds);
                        }
                    }
                }
            });
        }
    });

    // move labels after the other shapes are done moving
    this.postExecuted(['connection.layout'], function (e) {
        var connection = e.context.connection;
        var oldWaypoints = e.context.oldWaypoints;
        if (connection.label) {
            var delta = getMidpointsDelta(oldWaypoints, connection.waypoints);
            modeling.moveShape(connection.label, delta, connection.label.parent);
        }
    });

    // update di information on label movement and creation
    this.executed(['label.create', 'shape.moved'], function (e) {
        var element = e.context.shape,
            businessObject,
            diElement;

        // we want to trigger on real labels only
        if (!element.labelTarget) {
            return;
        }


        if (!instanceOf(getBusinessObject(element.labelTarget || element), 'bp:BaseElement')) {
            return;
        }

        businessObject = element.businessObject;
        diElement = businessObject.diElement;


        if (!diElement.label) {
            diElement.label = elementFactory.createDiLabel();
        }

        assign(diElement.label.bounds, {
            x: element.x,
            y: element.y,
            width: element.width,
            height: element.height
        });
    });
}

inherits(LabelSupport, CommandInterceptor);

LabelSupport.$inject = ['eventBus', 'modeling', 'elementFactory', 'dtDiagram', 'elementRegistry'];

export default LabelSupport;
