import DjsResize from 'diagram-js/lib/features/resize/Resize';

import inherits from 'inherits';
import {getMinResizeBounds} from "diagram-js/lib/features/resize/ResizeUtil";
import {getChildren} from "../modeling/ModelUtil";
import {getDefaultPaddingForLane, getDefaultPaddingForLaneContainer, getMinDimensionsForLane} from "../modeling/util/LaneUtil";
import {roundBounds} from "diagram-js/lib/layout/LayoutUtil";

/**
 * Sub class of the Resize module which implements a Process Diagram specific resize function
 */
function ProcessDiagramResize(eventBus, rules, modeling, dragging, processDiagramRules) {
    var _self = this;

    DjsResize.call(this, eventBus, rules, modeling, dragging);
    this._processDiagramRules = processDiagramRules;
    this._modeling = modeling;

    // listen with custom priority (default=1000, higher is called first)
    eventBus.on('resize.start', 1500, function(event) {
        event.context.oldBounds = roundBounds(event.context.shape);
    });

    // Called with lower priority to ensure that the default listener on resize.end has already fired

    // We handle resizeChildren here and not in ResizeProcessShapeHandler because this event fires after a 'manual' resize
    // It will not be executed after modeling.resizeShape is called, therefore preventing an infinite loop ,
    // i.e. [parent --> resizeChildren --> each child resizes parent --> resizeChildren...] and so on
    // It will only be fired ONCE after a shape has been manually resized
    eventBus.on('resize.end', 900, function(event) {
        _self.resizeChildren.call(_self, event);
    });

}
ProcessDiagramResize.$inject = [
    'eventBus',
    'rules',
    'modeling',
    'dragging',
    'processDiagramRules'
];

inherits(ProcessDiagramResize, DjsResize);

/**
 * Computes the minimum resize box (bounds) for the shape being resized
 *
 * @param context
 * @returns {Bounds}
 */
ProcessDiagramResize.prototype.computeMinResizeBox = function(context) {
    var shape = context.shape;

    // CBPM-26117 For a parallel lane, the min bounds must be calculated
    // considering the min bounds of other lanes in the same container
    if (this._processDiagramRules.isParallelLane(shape)) {
        var shapeParent = shape.parent || shape;

        // Set Padding and minDimensions for a parallel lane
        context.childrenBoxPadding = getDefaultPaddingForLane();
        context.minDimensions = getMinDimensionsForLane();

        // Get all siblings of the lane, i.e. all lanes that have the same parent as the resized lane
        var allAffectedLanes = getChildren(shapeParent, shape);

        allAffectedLanes.forEach(function(lane) {
            // get bounds for a lane
            var laneBounds = DjsResize.prototype.computeMinResizeBox({
                direction: context.direction,
                shape: lane,
                childrenBoxPadding: context.childrenBoxPadding,
                minDimensions: context.minDimensions
            });

            // Update minDimensions width, height is not affected
            if (laneBounds.width > context.minDimensions.width) {
                context.minDimensions.width = laneBounds.width;
            }
        });
    } else if (this._processDiagramRules.isParallelLaneContainer(shape)) {
        // Set Padding for a parallel lane container
        context.childrenBoxPadding = getDefaultPaddingForLaneContainer();

        // Get all lanes in the parallel lane container
        var allChildLanes = getChildren(shape);

        // minDimensions for a parallel lane
        var laneMinDimensions = getMinDimensionsForLane();
        var minHeightForLaneContainer = context.childrenBoxPadding.top + context.childrenBoxPadding.bottom;

        allChildLanes.forEach(function(lane) {
            // get bounds for a lane
            var laneBounds = DjsResize.prototype.computeMinResizeBox({
                direction: context.direction,
                shape: lane,
                childrenBoxPadding: getDefaultPaddingForLane(),
                minDimensions: laneMinDimensions
            });

            if (laneBounds.width > laneMinDimensions.width) {
                laneMinDimensions.width = laneBounds.width;
            }
            minHeightForLaneContainer += laneBounds.height;
        });

        context.minDimensions = {
            width: laneMinDimensions.width,
            height: minHeightForLaneContainer
        };

        // get correct minimum bounds from given resize direction
        return getMinResizeBounds(context.direction, shape, context.minDimensions);
    }
    return DjsResize.prototype.computeMinResizeBox.call(this, context);
};

/**
 * Resizes all the children shapes for the shape that was resized, i.e. it calculates new width/height for children according to the parent
 *
 * @param event
 */
ProcessDiagramResize.prototype.resizeChildren = function(event){
    var _self = this;
    var context = event.context;
    var shape = context.shape;
    var oldBounds = context.oldBounds;
    var newBounds = context.newBounds;

    // Currently we are only concerned with adjusting parallel lanes when a parallel lane container was resized
    // All other shapes can be ignored
    if (this._processDiagramRules.isParallelLaneContainer(shape)) {
        var allChildLanes = getChildren(shape);
        var defaultHeightPadding = getDefaultPaddingForLaneContainer().top + getDefaultPaddingForLaneContainer().bottom;
        var newHeightRatio = (newBounds.height - defaultHeightPadding) / (oldBounds.height - defaultHeightPadding);

        allChildLanes.forEach(function(lane){
            // Calculate height resize ratio
            var newChildHeight = lane.height * newHeightRatio;

            // get bounds for a lane
            var laneBounds = DjsResize.prototype.computeMinResizeBox({
                direction: context.direction,
                shape: lane,
                childrenBoxPadding: getDefaultPaddingForLane(),
                minDimensions: getMinDimensionsForLane()
            });

            // Check if child height goes below minimum constraint
            // If yes, reset to min height
            if (newChildHeight < laneBounds.height) {
                newChildHeight = laneBounds.height;
            }

            //Resize the lane
            _self._modeling.resizeShape(lane, {
                x: lane.x,
                y: lane.y,
                width: newBounds.width, // the width is same as the resized parent
                height: Math.round(newChildHeight)
            }, null, {resizeStack: allChildLanes});
        });
    }
}
export default ProcessDiagramResize;