'use strict';

var _CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-';
import d64Fun from 'd64';

var d64 = d64Fun(_CHARS);
import uuid from 'uuid';

/**
 * Manages Ids for diagram objects.
 * @constructor
 */
function Ids() {
    this._idsHash = {};
}

/**
 * Gets UUID in a form of: ID_PATTERN = /^Z[A-Za-z0-9_-]{22}$/
 *
 * @returns {string}
 * @private
 */
Ids.prototype._next = function() {
    return 'Z' + d64.encode(uuid.v1(null, new Array(16), 0));
};

Ids.prototype.nextForElement = function(element) {
    var id;
    do {
        id = this._next();
    } while (this.assigned(id));

    this.claim(id, element);

    return id;
};

Ids.prototype.claim = function(id, element) {
    this._idsHash[id] = element || true;
};

Ids.prototype.assigned = function(id) {
    return this._idsHash[id] || false;
};

Ids.prototype.unclaim = function(id) {
    delete this._idsHash[id];
};

Ids.prototype._getHash = function() {
    return this._idsHash;
};

export default Ids;
