import RulesModule from 'diagram-js/lib/features/rules';
import DraggingModule from 'diagram-js/lib/features/dragging';
import PreviewSupportModule from 'diagram-js/lib/features/preview-support';

import ProcessDiagramResize from './ProcessDiagramResize';
import ResizePreview from 'diagram-js/lib/features/resize/ResizePreview';
import ResizeHandles from 'diagram-js/lib/features/resize/ResizeHandles';
import Resize from 'diagram-js/lib/features/resize/Resize'

export default {
    __depends__: [
        RulesModule,
        DraggingModule,
        PreviewSupportModule
    ],
    __init__: [
        'processDiagramResize',
        'resize',
        'resizePreview',
        'resizeHandles'
    ],
    processDiagramResize: [ 'type', ProcessDiagramResize ],
    resize: [ 'type', Resize ],
    resizePreview: [ 'type', ResizePreview ],
    resizeHandles: [ 'type', ResizeHandles ]
};
