'use strict';

import forEach from 'lodash/forEach';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';
import {roundPoint} from 'diagram-js/lib/layout/LayoutUtil';
var round = Math.round;
/**
 * A handler that implements reversible changes needed to set the process to form start.
 * Internally the first form task shape will be removed and its outgoing connections reattached to the start event.
 *
 *
 * @class
 * @constructor
 */
function SetProcessAutoFormHandler(modeling, rules, elementFactory) {
    this._modeling = modeling;
    this._rules = rules;
    this._elementFactory = elementFactory;
}

SetProcessAutoFormHandler.$inject = ['modeling', 'rules', 'elementFactory'];


/**
 * Adds formShape and reconnects startEvent's outgoing connections to formShape.
 *
 * @param {Object} context
 * @param {Object} context.startEventShape the process start event shape
 * @param {Object} context.modelCommands the the model commands to be executed to set process to form task
 */
SetProcessAutoFormHandler.prototype.postExecute = function (context) {
    var modeling = this._modeling;
    var elementFactory = this._elementFactory;
    var startEventShape = context.startEventShape;
    var modelCommands = context.modelCommands;

    var outgoing = startEventShape.outgoing.slice();
    var parent = startEventShape.parent;

    var subProcessShape = elementFactory.createShape({type: 'bp:SubProcess', subProcessType: 'InitialTasks'});
    var formTaskShape = elementFactory.createShape({type: 'bp:FormTask'});
    var startEventShapeMid = getMid(startEventShape);
    var subProcessShapeObj = modeling.createShape(subProcessShape, startEventShapeMid, parent);
    var formTaskMid = {x: subProcessShapeObj.x + 25 + round(formTaskShape.width / 2), y:startEventShapeMid.y};
    modeling.createShape(formTaskShape, formTaskMid, subProcessShape);
    var subProcessShapeMid = getMid(subProcessShapeObj);
    var subProcessOutgoingWayPoint = { x : (subProcessShapeMid.x) , y : subProcessShapeMid.y};
    forEach(outgoing, function (connection) {
        var waypoints = connection.waypoints;
        modeling.reconnectStart(connection, subProcessShape, waypoints);
    });

    //Move startEventShape to the left.
    var delta = {x: -180, y: 0};
    modeling.moveShape(startEventShape, delta, startEventShape.parent);

    modeling.createConnection(startEventShape, subProcessShape, {
        type: 'bp:SequenceFlow',
        "flowMarker": "A"
    }, startEventShape.parent);

    forEach(subProcessShape.outgoing, function (c) {
        modeling.layoutConnection(c, {connectionStart: subProcessOutgoingWayPoint});
    });

    if (modelCommands && modelCommands.length >= 0) {
        modeling.runProcessModelCommand(modelCommands)
    }
};


SetProcessAutoFormHandler.prototype.execute = function (context) {
};

SetProcessAutoFormHandler.prototype.revert = function (context) {
};

export default SetProcessAutoFormHandler;
