import ProcessKeyBoardBindings from "./ProcessKeyBoardBindings";

export default {
    __depends__: [
        keyboardModule
    ],

    /* Name of var and the name on __init__ HAVE to match the diagram-js 'context' name for keyboard features. 'keybaord' */
    keyboard: ['type', ProcessKeyboard],
    keyboardBindings: [ 'type', ProcessKeyBoardBindings ],
    __init__: ['keyboard', 'keyboardBindings']

};