import AutoResize from 'diagram-js/lib/features/auto-resize/AutoResize';

import inherits from 'inherits';
import {getDefaultPaddingForLane, getDefaultPaddingForLaneContainer} from "../modeling/util/LaneUtil";

/**
 * Sub class of the AutoResize module which implements a Process Diagram specific resize function
 */
function ProcessDiagramAutoResize(eventBus, elementRegistry, modeling, rules, processDiagramRules) {
  AutoResize.call(this, eventBus, elementRegistry, modeling, rules);
  this._processDiagramRules = processDiagramRules;
  
}
ProcessDiagramAutoResize.$inject = [
  'eventBus',
  'elementRegistry',
  'modeling',
  'rules',
  'processDiagramRules'
];

inherits(ProcessDiagramAutoResize, AutoResize);


/**
 * Expand the target shape respecting rules, offset and padding
 *
 * @param {Array<djs.model.Shape>} elements
 * @param {djs.model.Shape|string} target|targetId
 */
ProcessDiagramAutoResize.prototype._expand = function(elements, target) {
  // CBPM-26070 When a parallel lane container is being expanded (auto-resized),
  // pass all the children of the container to calculate correct bounds
  if (this._processDiagramRules.isParallelLaneContainer(target)) {
    elements = target.children;
  }
  AutoResize.prototype._expand.call(this, elements, target);
};

/**
 * Get the amount to expand the given shape in each direction.
 *
 * @param {djs.model.Shape} shape
 *
 * @return {top: number, left: number, bottom: number, right: number}
 */
ProcessDiagramAutoResize.prototype.getOffset = function(shape) {
  if (this._processDiagramRules.isParallelLane(shape)) {
    return getDefaultPaddingForLane();
  } else if (this._processDiagramRules.isParallelLaneContainer(shape)) {
    return getDefaultPaddingForLaneContainer();
  }

  return AutoResize.prototype.getOffset.call(this, shape);
};


/**
 * Get the activation threshold for each side for which
 * resize triggers.
 *
 * @param {djs.model.Shape} shape
 *
 * @return {top: number, left: number, bottom: number, right: number}
 */
ProcessDiagramAutoResize.prototype.getPadding = function(shape) {
  if (this._processDiagramRules.isParallelLane(shape)) {
    return getDefaultPaddingForLane();
  } else if (this._processDiagramRules.isParallelLaneContainer(shape)) {
    return getDefaultPaddingForLaneContainer();
  }

  return AutoResize.prototype.getPadding.call(this, shape);
};


export default ProcessDiagramAutoResize;