'use strict';

import ResizeShapeHandler from 'diagram-js/lib/features/modeling/cmd/ResizeShapeHandler';
import inherits from 'inherits';
import {asTRBL} from "diagram-js/lib/layout/LayoutUtil";
import {computeChildrenBBox, substractTRBL} from "diagram-js/lib/features/resize/ResizeUtil";
import {getChildren, isOfType} from "../ModelUtil";
import {boundsChanged, getDefaultPaddingForLaneContainer} from "../util/LaneUtil";

/**
 * A handler that extends diagram js ResizeShapeHandler to resize shapes.
 * Once the base ResizeShapeHandler resizes the passed shape, this handler moves and resizes its sibling shapes
 *
 * @param modeling
 * @constructor
 */
function ResizeProcessShapeHandler(modeling, spaceTool, processDiagramRules) {

    /* Super CONSTRUCTOR */
    ResizeShapeHandler.call(this, modeling);

    this._modeling = modeling;
    this._spaceTool = spaceTool;
    this._processDiagramRules = processDiagramRules;
}

ResizeProcessShapeHandler.$inject = ['modeling', 'spaceTool', 'processDiagramRules'];

inherits(ResizeProcessShapeHandler, ResizeShapeHandler);

/**
 * Overrides ResizeShapeHandler of diagram js.
 *
 * @param context
 */
ResizeProcessShapeHandler.prototype.preExecute = function (context) {
    /* call the default implementation of preExecute */
    if (ResizeShapeHandler.prototype.preExecute) {
        ResizeShapeHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Overrides ResizeShapeHandler of diagram js.
 *
 * @param context
 */
ResizeProcessShapeHandler.prototype.postExecute = function (context) {
    // call the default implementation of postExecute
    if (ResizeShapeHandler.prototype.postExecute) {
        ResizeShapeHandler.prototype.postExecute.call(this, context);
    }

    // CBPM-26070 After a shape is resized, make space(move and resize) for its siblings,
    // i.e., sibling are all other shapes that have the same parent as the shape that was resized
    this.makeSpaceForSiblings(context);

    // CBPM-26117 After a shape is resized, adjust the parent size to contain all children within its bounds
    this.resizeParentShape(context);
};

ResizeProcessShapeHandler.prototype.resizeParentShape = function(context) {
    var shape = context.shape;
    var parent = shape.parent;

    // Do not trigger resize for a 'Process'
    if (parent && !isOfType(parent, 'bp:Process')) {

        // CBPM-26117 We have specific padding defined for parallel lane and parallel lane container,
        // for all others we use the default by passing undefined
        var defaultPadding;
        if (this._processDiagramRules.isParallelLaneContainer(parent)) {
            defaultPadding = getDefaultPaddingForLaneContainer()
        } else if (this._processDiagramRules.isParallelLane(parent)) {
            defaultPadding = getDefaultPaddingForLaneContainer()
        } else {
            defaultPadding = undefined;
        }

        // Calculate new bounds for the parent
        var newBounds = computeChildrenBBox(parent, defaultPadding);

        if (!boundsChanged(parent, newBounds)) {
            // no resize necessary
            return;
        }
        // perform the actual resize
        this._modeling.resizeShape(parent, newBounds);
    }
}
ResizeProcessShapeHandler.prototype.makeSpaceForSiblings = function(context) {
    var shape = context.shape;
    var oldBounds = context.oldBounds;
    var spaceTool = this._spaceTool;
    var shapeTrbl = asTRBL(shape);
    var oldTrbl = asTRBL(oldBounds);
    var trblDiff = substractTRBL(shapeTrbl, oldTrbl);

    // CBPM-26070 context.hints.resizeStack is an array of elements currently being resized
    var resizeStack = (context.hints && context.hints.resizeStack) || [];

    var shapeParent = shape.parent || shape;

    // Get all siblings of the shape, i.e. all shapes that have the same parent as the resized shape
    var allAffectedSiblings = getChildren(shapeParent, shape);

    var change,
        spacePos,
        direction,
        offset,
        adjustments;

    // If a shape was resized vertically, i.e. the height increased either on the top or bottom
    if (trblDiff.bottom || trblDiff.top) {

        change = trblDiff.bottom || trblDiff.top;
        spacePos = oldBounds.y + (trblDiff.bottom ? oldBounds.height : 0) + (trblDiff.bottom ? -1 : 1);
        direction = trblDiff.bottom ? 's' : 'n';
        offset = trblDiff.top > 0 || trblDiff.bottom < 0 ? -change : change;
        adjustments = spaceTool.calculateAdjustments(allAffectedSiblings, 'y', offset, spacePos);

        // We don't want to resize any other element when a shape is resized vertically; only move elements as required
        // Explicitly pass resizingShapes=[]
        spaceTool.makeSpace(adjustments.movingShapes, [], { x: 0, y: change }, direction, spacePos);
    }

    // If a shape was resized horizontally, i.e. the width increased either on the left or right
    if (trblDiff.left || trblDiff.right) {

        change = trblDiff.right || trblDiff.left;
        spacePos = oldBounds.x + (trblDiff.right ? oldBounds.width : 0) + (trblDiff.right ? -1 : 1);
        direction = trblDiff.right ? 'e' : 'w';
        offset = trblDiff.left > 0 || trblDiff.right < 0 ? -change : change;
        adjustments = spaceTool.calculateAdjustments(allAffectedSiblings, 'x', offset, spacePos);

        // We do not want to trigger resize for elements already in the resizeStack
        // or if the element already has the same width as the shape
        adjustments.resizingShapes = adjustments.resizingShapes.filter(function(aShape){
            return (aShape.width !== shape.width) && (resizeStack.indexOf(aShape) === -1);
        });
        spaceTool.makeSpace(adjustments.movingShapes, adjustments.resizingShapes, { x: change, y: 0 }, direction, spacePos);
    }
}
export default ResizeProcessShapeHandler;
