"use strict";

import {instanceOf} from './ModelUtil';
import map from 'lodash/map';
var round = Math.round;
import * as LabelUtil from './LabelUtil';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';

function DiagramLoader (canvas, eventBus, elementFactory, elementRegistry, processModdle, modelUpgrader) {
    this._canvas = canvas;
    this._eventBus = eventBus;
    this._elementFactory = elementFactory;
    this._elementRegistry = elementRegistry;
    this._processModdle = processModdle;
    this._modelUpgrader = modelUpgrader;
}

DiagramLoader.$inject = ['canvas', 'eventBus', 'elementFactory', 'elementRegistry', 'processModdle', 'modelUpgrader'];


DiagramLoader.prototype.loadDiagram = function (definitions, cb) {

    var canvas = this._canvas;
    var elementFactory = this._elementFactory;
    var elementRegistry = this._elementRegistry;
    var eventBus = this._eventBus;
    var processModdle = this._processModdle;
    var modelUpgrader = this._modelUpgrader;


    var handler = function () {
        var errors = [];
        var visitedElems = {};

        function addError(err) {
            errors.push(err);
        }
        function hasErrors() {
            return errors.length !== 0;
        }
        function visit(element) {
          visitedElems[element.id] = element;
          return this;
        }
        function visited(element) {
            return visitedElems[element.id];
        }

        return {
            errors: errors,
            addError: addError,
            hasErrors: hasErrors,
            visit: visit,
            visited: visited
        }
    }();


    function visitModel(root) {
        if (!root || !root.$instanceOf('bp:Definitions')) {
            handler.addError('Root element must be bp:Definitions');
            return;
        }
        var definitions = root;
        if (!definitions.diagrams || !definitions.diagrams[0].$instanceOf('bpdi:BPDiagram')) {
            handler.addError('BPDiagram is not present in definitions.');
            return;
        }

        //Links di part of the model with semantic eleents.
        visitPlane(definitions.diagrams[0].plane);
        if (handler.hasErrors()) {
            return;
        }

        definitions = modelUpgrader.upgradeModel(definitions);

        if (!definitions.rootElements || !definitions.rootElements[0].$instanceOf('bp:Process')) {
            handler.addError('BPDiagram is not present in definitions.');
            return;
        }

        var rootProcess = definitions.rootElements[0];
        visitProcess(rootProcess);
    }

    function visitProcess(process) {
        addRootElement(process);

        // flow nodes
        visitFlowNodes(process);

        // artifact nodes
        process.get('artifacts').forEach(function visitArtifacts(artifact) {
            if (artifact.$instanceOf('bp:Artifact')) {
                visitNode(artifact, process);
            }
        });

        // sequence flows
        visitSequenceFlowOfFlowElements(process);
    }

    function visitFlowNodes(container) {
        // flow nodes
        container.get('flowElements').forEach(function visitFlowElements(flowElement) {
            if (instanceOf(flowElement, 'bp:FlowNode')) {
                visitNode(flowElement, container);
                if (instanceOf(flowElement, 'bp:FlowElementsContainer')) {
                    visitFlowNodes(flowElement);
                }
            }
        });
    }

    function visitSequenceFlowOfFlowElements(container) {
        // flow nodes
        if (container.hasOwnProperty('flowElements')) {
            container.get('flowElements').forEach(function visitFlowElements(flowElement) {
                if (flowElement.$instanceOf('bp:SequenceFlow')) {
                    visitSequenceFlow(flowElement, container);
                }
                if (flowElement.$instanceOf('bp:FlowElementsContainer')) {
                    visitSequenceFlowOfFlowElements(flowElement);
                }
            });
        }
    }
    function visitSequenceFlow(flow, parent) {
        //assume that nodes has been processed already so we can find source and target.
        var shapeModel = elementRegistry.get(parent.id);
        addConnection(flow, shapeModel);
        setParent(flow, parent);
    }

    function visitNode(node, parent){
        var shapeModel = elementRegistry.get(parent.id);
        addShape(node, shapeModel);
        setParent(node, parent);
    }

    function setParent(element, parent) {
        if ((element.$instanceOf('bp:FlowElement') && parent.$instanceOf('bp:FlowElementsContainer')) ||
            (element.$instanceOf('bp:Artifact') && parent.$instanceOf('bp:Process'))) {
            element.$parent = parent;

            var di = element.diElement;
            var diParent = parent.diElement;
            if ( di && diParent) {
               di.$parent = diParent;
            }
        }
    }

    function visitPlane(plane) {
        linkWithSemantic(plane);
        plane.get('planeElement').forEach(visitPlaneElement);
    }

    function visitPlaneElement(planeElement) {
        linkWithSemantic(planeElement);
    }

    function linkWithSemantic(diElement) {
        var bpElement = diElement.bpElement;
        if (bpElement) {
            if (bpElement.diElement) {
                handler.addError('bplement ' + bpElement + 'already has diElement assigned.');
            } else {
                processModdle.bindSemanticDiRef(bpElement);
                bpElement.diElement = diElement;
            }
        } else {
            handler.addError('Invalid di -> diElement referece - diElement: ' + diElement);
        }
    }

    /////////////// Add elements to the diagram ////////////
    function addRootElement (process) {
        var diElement = process.diElement;
        if (diElement.$instanceOf('bpdi:BPPlane')) {
            var rootElement = elementFactory.createRoot({
                id: process.id,
                type: process.$type,
                businessObject: process
            });
            canvas.setRootElement(rootElement);
        } else {
            handler.addError('Process must be connected to diagram\'s <bpmndi:BPMNPlane> element.');
        }
    }

    function addShape(node, parent) {
        var diElem = node.diElement;
        if (instanceOf(diElem, 'bpdi:BPShape')) {
            var element = elementFactory.createShape({
                id: node.id,
                type: node.$type,
                businessObject: node,
                x: round(diElem.bounds.x),
                y: round(diElem.bounds.y),
                width: round(diElem.bounds.width),
                height: round(diElem.bounds.height)
            });
            canvas.addShape(element, parent);
            if (LabelUtil.hasExternalLabel(node)) {
                addLabel(node, element);
            }
        } else {
            handler.addError('Flow node must be connected to diagram\'s "bpdi:BPShape" element.');
        }
    }

    function addConnection(sequenceFlow,parent) {
        var diElem = sequenceFlow.diElement;
        var connectionSource = geteDjsEndElement(sequenceFlow, 'sourceRef');
        var connectionTarget = geteDjsEndElement(sequenceFlow, 'targetRef');
        if (instanceOf(sequenceFlow.diElement, 'bpdi:BPEdge')) {
            var element = elementFactory.createConnection({
                id: sequenceFlow.id,
                type: sequenceFlow.$type,
                businessObject: sequenceFlow,
                waypoints: _createDjsWaypoints(diElem, connectionSource, connectionTarget),
                source: connectionSource,
                target: connectionTarget
            });
            canvas.addConnection(element,parent);
            if (LabelUtil.hasExternalLabel(sequenceFlow)) {
                addLabel(sequenceFlow, element);
            }
        } else {
            handler.addError('Sequence flow must be connected to diagram\'s "bpdi:BPPEdge" element.');
        }
    }

    function addLabel(semantic, element) {
        var bounds = LabelUtil.getExternalLabelBounds(semantic, element);
        var diElement = semantic.diElement;

        // Create a diagram element label if it doesn't exist.
        if (!diElement.label) {
            diElement.label = elementFactory.createDiLabel(bounds);
        }
        var label = elementFactory.create('label', {
            type: 'label',
            labelTarget: element,
            businessObject: semantic,
            id: semantic.id + '_label',
            hidden: element.hidden || !semantic.name,
            x: round(bounds.x),
            y: round(bounds.y),
            width: round(bounds.width),
            height: round(bounds.height)
        });

        return canvas.addShape(label, element.parent);
    }


    /**
     * Creates diagram waypoints from the serialized diagram's connection information.
     *
     * @param {Object} diElement - Serialized model of diagram's connection.
     * @param {Object[]} diElement.waypoint - Serialized model of connection's waypoints.
     * @param {Shape} sourceShape - Source shape.
     * @param {Shape} targetShape - Target shape.
     * @return {Array}
     * @private
     */
    function _createDjsWaypoints (diElement, sourceShape, targetShape) {
        if (!diElement.waypoint) return [];
        var waypoints = map(diElement.waypoint, function (point) {
            return {x: point.x, y: point.y};
        });
        //Set the original point for the start and the end of connection to the middle of source and target.
        waypoints[0].original = getMid(sourceShape);
        waypoints[waypoints.length - 1].original = getMid(targetShape);
        return waypoints;
    }

    function geteDjsEndElement (sequenceFlow, refName) {
        var canvasElement = elementRegistry.get(sequenceFlow[refName].id);
        if (canvasElement) {
            return canvasElement;
        }
        handler.addError('Sequence flow must alredy have existing source element. sequenceFlow.id = '+ sequenceFlow.id);
    }

    visitModel(definitions);
    if (handler.hasErrors()) {
        cb(JSON.stringify(handler.errors));
    } else {
        cb();
    }
};

export default DiagramLoader;

