'use strict';

import findIndex from 'lodash/findIndex';

import OrderingProvider from 'diagram-js/lib/features/ordering/OrderingProvider';
import inherits from 'inherits';
import {isOfType} from '../modeling/ModelUtil';

/**
 * A handler that provides ordering of elements in process-diagram-js.
 *
 * @param eventBus
 * @constructor
 */
function ProcessOrderingProvider(eventBus) {
    OrderingProvider.call(this, eventBus);
}

ProcessOrderingProvider.$inject = [ 'eventBus' ];

inherits(ProcessOrderingProvider, OrderingProvider);


/** Gets element order depending on type.
 *
 * @param {djs.model.Base} element
 */
function getElementOrder(element) {
    if (isOfType(element, 'bp:SequenceFlow')) {
        return 10;
    } else if (isOfType(element, 'bp:FlowNode')) {
        return 1;
    }
    return 1; //default order
}

/**
 * Return a custom ordering of the element, both in terms
 * of parent element and index in the new parent.
 *
 * Implementors of this method must return an object with
 * `parent` _and_ `index` in it.
 *
 * @param {djs.model.Base} element
 * @param {djs.model.Shape} newParent
 *
 * @return {Object} ordering descriptor with 'parent' and 'index' properties.
 */
ProcessOrderingProvider.prototype.getOrdering = function(element, newParent) {

    var elementOrder = getElementOrder(element);

    // If the newParent is not a container.
    if (!newParent.children) {
        return null;
    }

    var index = newParent.children.indexOf(element);

    // Find index where we need to place element. It will be on top of elements
    // with the same order number.
    var insertIndex = findIndex(newParent.children, function(child) {
        if (!element.labelTarget && child.labelTarget) {
            return false;
        }
        return elementOrder < getElementOrder(child);
    });


    // Adjust index for the situation when element is already in the list before insertIndex.
    if (insertIndex !== -1) {
        if (index !== -1 && index < insertIndex) {
            insertIndex--;
        }
    }

    return {
        index: insertIndex,
        parent: newParent
    };
};


export default ProcessOrderingProvider;