"use strict";

import {instanceOf} from './ModelUtil';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';
import assign from 'lodash/assign';
import forEach from 'lodash/forEach';
import isArray from 'lodash/isArray';
var round = Math.round;

function ModelUpgrader (elementFactory) {
    this._elementFactory = elementFactory;
}

ModelUpgrader.$inject = ['elementFactory'];


/**
 *  Upgrade the model to the newer version to support following :
 *     1. SubProcess Element
 *     2. Convert bp:TempVariableRef elements to bp:DataPath elements.
 *
 *  Sid CBPM-20853 Now added formatVersion to definitions model so that we
 *    do not continually upgrade models that have already been upgraded.
 *
 *    Each time a new upgrade is added, increment the LATEST_FORMAT_VERSION value
 *    and ONLY perform the upgrade if definitions.formatVersion is missing OR it is less than
 *    the new value for LATEST_FORMAT_VERSION (use the number value NOT the variable itself as that will
 *    defeat the object).
 *
 * @param definitions upgraded model
 */
ModelUpgrader.prototype.upgradeModel = function upgradeModel(definitions) {

    /**
     * LATEST_FORMAT_VERSION to
     *
     * 1. Keep track of model upgrades
     * 2. Also acts identifier for definitions model so that we do not continually
     *    upgrade models that have already been upgraded.
     *
     * <ul>
     *     <li><strong>2 :-</strong> Added during the upgrade of process model for addition of "bp:SubProcess" objects.</li>
     *     <li><strong>3 :-</strong> Added during the upgrade of process model for addition of attribute "subProcessType" in "bp:SubProcess" objects.</li>
     * </ul>
     *
     * @type {number}
     */
    var LATEST_FORMAT_VERSION = 3;

    var elementFactory = this._elementFactory;

    if (definitions && isArray(definitions.rootElements)
        && definitions.rootElements[0] && isArray(definitions.rootElements[0].flowElements)) {

        /* Sid CBPM 20853 only upgrade parts of process model that might be  out of date. */
        if (definitions.formatVersion == null || definitions.formatVersion < LATEST_FORMAT_VERSION) {

            if(definitions.formatVersion == null || definitions.formatVersion < 2){
                addMissingInitialTasksSubprocess(definitions, elementFactory);

                /* Sid CBPM-20853 replace all bp:TempVariableRef objects with equivalent bp:DataPath object. */
                recursiveReplaceTempVariableRefs(definitions, elementFactory);
                console.log("Replaced temporary variable references with data-paths");
            }

            if(definitions.formatVersion == null || definitions.formatVersion < 3){
                var flowElements = definitions.rootElements[0].flowElements;
                addMissingSubProcessType(flowElements);
            }

        }
        definitions.formatVersion = LATEST_FORMAT_VERSION;
    }

    return definitions;


    /**
     * Function to add the missing 'subProcessType' for object of type "bp:SubProcess".
     *
     * @param flowElements
     */
    function addMissingSubProcessType(flowElements){
        /**
         * Here, we get the first object of type "bp:SubProcess" which do not have "subProcessType" already set.
         *
         * Since "bp:SubProcess" object for Parallel Flow/Container already have "subProcessType" set.
         * So it should be ideally always represent the "bp:SubProcess" object for Initial Tasks.
         */
        var subProcess = flowElements.find(function (flowElement) {
            return instanceOf(flowElement, 'bp:SubProcess') && !flowElement.subProcessType;
        });

        if (subProcess) {
            // Set 'subProcessType'.
            subProcess.set('subProcessType', 'InitialTasks');
        }
    }


    function addMissingInitialTasksSubprocess(definitions, elementFactory) {
        var FIXED_WIDTH_DELTA = 140;
        var FIXED_HEIGHT_DELTA = 60;
        var FORM_TASK_X_DELTA = round(FIXED_WIDTH_DELTA / 4);
        var FORM_TASK_Y_DELTA = round(FIXED_HEIGHT_DELTA / 2);
        var FIXED_Y_DELTA = FORM_TASK_Y_DELTA + 2; // 2 Pixels added to accommodate the border. This constant is used to
                                                  // move down tasks other than SubProcessTask
        var flowElements = definitions.rootElements[0].flowElements;
        var newSubProcesses = [];
        var toBeRemoved = [];
        var hasFormTask = flowElements.some(function (flowElement) {
            return instanceOf(flowElement, 'bp:FormTask');
        });

        //If 'FormTask' is present in the top level flow elements, that means we need to upgrade the model.
        if(hasFormTask) {
            flowElements.forEach(function (flowElement, index) {
                /**
                 *  Move all the Form Tasks inside the 'SubProcess' by creating the new SubProcess model.
                 *  SubProcess will be placed at the location of original Form Task.
                 *  All the outgoing connections of the FormTask will now become outgoing connections of the SubProcess.
                 *  All the incoming connections of the FormTask will now become incoming connections of the SubProcess.
                 */
                if (instanceOf(flowElement, 'bp:FormTask')) {

                    var formTaskDiElem = flowElement.diElement;
                    var subProcessShape = elementFactory.createShape({
                        type: 'bp:SubProcess',
                        subProcessType: 'InitialTasks'
                    });
                    subProcessShape.businessObject.set('flowElements', [flowElement]);
                    //Copy patterntSets (i.e Separation of Duties) to subProcess
                    if(flowElement.patternSets) {
                        subProcessShape.businessObject.set('patternSets', flowElement.patternSets);
                        flowElement.patternSets = [];
                    }
                    // Set the di model coordinates of the SubProcess
                    assign(subProcessShape.businessObject.diElement.bounds, {
                        x: formTaskDiElem.bounds.x,
                        y: formTaskDiElem.bounds.y,
                        width: formTaskDiElem.bounds.width + FIXED_WIDTH_DELTA,
                        height: formTaskDiElem.bounds.height + FIXED_HEIGHT_DELTA
                    });

                    // Update the x and y coordinates of existing Form Task
                    assign(formTaskDiElem.bounds, {
                        x: formTaskDiElem.bounds.x + FORM_TASK_X_DELTA,
                        y: formTaskDiElem.bounds.y + FORM_TASK_Y_DELTA
                    });

                    var subProcessMid = getMid(subProcessShape.businessObject.diElement.bounds);

                    // connect the outgoing flows of the Form task to SubProcess
                    if (flowElement.outgoing) {
                        var outgoing = flowElement.outgoing.slice();

                        forEach(outgoing, function (connection) {
                            connection.sourceRef = subProcessShape.businessObject;
                            assign(connection.diElement.waypoint[0], {
                                x : subProcessMid.x + round(subProcessShape.businessObject.diElement.bounds.width / 2),
                                y : subProcessMid.y
                            });

                            if(connection.diElement.label) {
                                assign(connection.diElement.label.bounds, {
                                    x: connection.diElement.label.bounds.x + FIXED_WIDTH_DELTA,
                                    y: connection.diElement.label.bounds.y + FIXED_Y_DELTA
                                });
                            }

                            // except the starting waypoint, move all other waypoints by specific distance. (as first
                            // waypoint is already updated above)
                            forEach(connection.diElement.waypoint, function (point, outIndex) {
                                if (outIndex > 0) {
                                    assign(point, {
                                        x: point.x + FIXED_WIDTH_DELTA,
                                        y: point.y + FIXED_Y_DELTA
                                    });
                                }
                            });

                            subProcessShape.businessObject.get('outgoing').push(connection);
                        });

                        // Set existing outing flows of the Form Task to empty
                        flowElement.set('outgoing', []);
                    }

                    // Connect incoming flows of the FormTask to the Form Task
                    if (flowElement.incoming) {
                        var incoming = flowElement.incoming.slice();

                        forEach(incoming, function (connection) {
                            connection.targetRef = subProcessShape.businessObject;
                            var targetWayPoints = connection.diElement.waypoint;

                            assign(connection.diElement.waypoint[targetWayPoints.length - 1], {
                                x : subProcessMid.x - round(subProcessShape.businessObject.diElement.bounds.width / 2),
                                y : subProcessMid.y
                            });

                            if(connection.diElement.label) {
                                assign(connection.diElement.label.bounds, {
                                    x: connection.diElement.label.bounds.x + FIXED_WIDTH_DELTA,
                                    y: connection.diElement.label.bounds.y + FIXED_Y_DELTA
                                });
                            }
                            // except the last(end) waypoint, move all other waypoints by specific distance.(as last
                            // waypoint is already updated above)
                            var changedIndex = targetWayPoints.length - 1;
                            forEach(connection.diElement.waypoint, function (point, inIndex) {
                                if (inIndex !== changedIndex) {
                                    assign(point, {
                                        x: point.x + FIXED_WIDTH_DELTA,
                                        y: point.y + FIXED_Y_DELTA
                                    });
                                }
                            });

                            subProcessShape.businessObject.get('incoming').push(connection);
                        });

                        // Set existing incoming flows of the Form Task to empty
                        flowElement.set('incoming', []);
                    }

                    newSubProcesses.push(subProcessShape.businessObject);
                    toBeRemoved.push(index);

                } else if (instanceOf(flowElement, 'bp:FlowNode')) {
                    // move all other elements ahead by fixed width to accommodate the newly created SubProcess
                    assign(flowElement.diElement.bounds, {
                        x: flowElement.diElement.bounds.x + FIXED_WIDTH_DELTA,
                        y: flowElement.diElement.bounds.y + FIXED_Y_DELTA
                    });
                } else if (instanceOf(flowElement, 'bp:SequenceFlow')) {
                    // move all other edges (which are not connecting SubProcess) by fixed width to accommodate the
                    // newly created SubProcess
                    // CBPM-26114 :- This is used for adding missing 'bp:SubProcess' to the process model.
                    // So related to "InitialTasks" subProcessType.
                    if (!((instanceOf(flowElement.sourceRef, 'bp:SubProcess') && flowElement.sourceRef.subProcessType === 'InitialTasks') ||
                        (instanceOf(flowElement.targetRef, 'bp:SubProcess') && flowElement.sourceRef.subProcessType === 'InitialTasks'))) {

                        if(flowElement.diElement.label) {
                            assign(flowElement.diElement.label.bounds, {
                                x: flowElement.diElement.label.bounds.x + FIXED_WIDTH_DELTA,
                                y: flowElement.diElement.label.bounds.y + FIXED_Y_DELTA
                            });
                        }

                        forEach(flowElement.diElement.waypoint, function (point) {
                            assign(point, {
                                x: point.x + FIXED_WIDTH_DELTA,
                                y: point.y + FIXED_Y_DELTA
                            });
                        })
                    }
                }
            });

            // Update the x position of the TextAnnotation
            if(definitions.rootElements[0].artifacts){
                definitions.rootElements[0].artifacts.forEach(function (artifact) {
                    if (instanceOf(artifact, 'bp:TextAnnotation')) {
                        artifact.diElement.bounds.x = artifact.diElement.bounds.x + FIXED_WIDTH_DELTA;
                    }
                });
            }
            
            if (newSubProcesses.length > 0) {

                // add newly created SubProcess to the plane
                newSubProcesses.forEach(function (subProcess) {
                    definitions.diagrams[0].plane.planeElement.push(subProcess.diElement);
                });

                // Remove 'FormTask' from the top level flowElements and add SubProcess
                var i;
                for (i = 0; i < newSubProcesses.length; i++) {
                    flowElements.splice(toBeRemoved[i], 1, newSubProcesses[i]);
                }
                definitions.rootElements[0].flowElements = flowElements;

                console.log("Upgraded model to include the SubProcess");
            }
        }
    }

    /**
     * Sid CBPM-20853 Recursively Switch any bp:TempVariableRef to bp:DataPath
     *
     * Now that we generated actual temporary bp:DataField objects for assigned temporary fields
     * we can refer to temp fields using bp:DataPath and treat assigned temp fields and data fields the same
     * in calculation tasks.
     *
     * Converting to them here means we don't have to deal with older TempVariableRef and newer DataPath model.
     *
     * @param anyObject any object (can be null or undefined)
     */
    function recursiveReplaceTempVariableRefs(anyObject, elementFactory, parentObject, propertyNameInParent) {
        if (anyObject && typeof anyObject === "object") {

            if (anyObject.$type == "bp:TempVariableRef") {
                /*
                 * Convert TempVariableRef to DataPath.  We can't just set the anyObject.$type as it's readonly
                 * so best to create a brand new object and replace the existing one in the parent.
                 *
                 * THIS should even work with bp:TempVariableRef in an ARRAY (the propertyNameInParent will
                 * be the array index and I think just setting parent.0 = newDataPath replaces old one.
                 */
                var bpModdle = elementFactory.getBpModdle();
                var dataPath = bpModdle.create("bp:DataPath");

                /*
                 * For normal bp:DataPath, the dataItem is already resolved  from string to an actual field
                 * definition in the process.data (this is done in bp-model/index.js :: customizer())
                 *
                 * For DataPath to $TEMPn fields, we don't initially HAVE a real field during load, so instead
                 * we maintain a property that reflects the original dataItem.id so that the calculation task
                 * handling code can create and assign an appropriate bp:DataField to the dataPath.dataItem
                 * once it has figured out what type the temp field was assigned from. Then it can set dataItem
                 * according to appropriate temporary bp:DataField using the __Original_dataItem id.
                 */
                dataPath['__Original_dataItem'] = anyObject.name; // Set 'original data item' property to $TEMPn from TempVariableRef
                dataPath.cachedName = anyObject.name; // Best we can do at this level!

                // Replace this bp:TempVariableRef property in the parent with this new one
                // I've checkd that this also works for arrays basically  parentObject["0"] = xxx will set first element.
                parentObject[propertyNameInParent] = dataPath;

            } else {
                /* Recurs into child properties. */
                for (var propName in anyObject) {
                    if (anyObject.hasOwnProperty(propName)) {
                        recursiveReplaceTempVariableRefs(anyObject[propName], elementFactory, anyObject, propName);
                    }
                }
            }
        }

    }


};

export default ModelUpgrader;