import inherits from 'inherits';
import assign from 'lodash/assign';
import {instanceOf} from '../modeling/ModelUtil';
import {orientation} from '../modeling/ModelUtil';
import {elementsBelow} from '../modeling/ModelUtil';
import {elementsRightOf} from '../modeling/ModelUtil';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';
import partition from 'lodash/partition';
import isEmpty from 'lodash/isEmpty';


import EditFlowNodeHandler from './cmd/EditFlowNodeHandler';
import ExternalCommandHandler from './cmd/ExternalCommandHandler';
import DeleteProcessShapeHandler from './cmd/DeleteProcessShapeHandler';
import CreateProcessShapeHandler from './cmd/CreateProcessShapeHandler';
import MoveProcessShapeHandler from './cmd/MoveProcessShapeHandler';
import AppendProcessShapeHandler from './cmd/AppendProcessShapeHandler';
import SetProcessAutoStartHandler from './cmd/SetProcessAutoStartHandler';
import SetProcessFormStartHandler from './cmd/SetProcessFormStartHandler';
import AppendTaskToSubProcessHandler from './cmd/AppendTaskToSubProcessHandler';
import ReconnectSequenceFlowHandler from './cmd/ReconnectSequenceFlowHandler';
import RemoveTaskFromSubProcessHandler from './cmd/RemoveTaskFromSubProcessHandler';
import DtSpaceToolHandler from './cmd/DtSpaceToolHandler';
import DeleteProcessElementsHandler from './cmd/DeleteProcessElementsHandler';
import CreateProcessElementsHandler from "./cmd/CreateProcessElementsHandler";
import AddLaneHandler from './cmd/AddLaneHandler';
import ResizeProcessShapeHandler from "./cmd/ResizeProcessShapeHandler";
import MoveParallelFlowLaneHandler from "./cmd/MoveParallelFlowLaneHandler";
import ProcessMoveEvents from "../move/ProcessMove";

/**
 * Process modeling entry point.
 *
 * @constructor
 * @extends DjsModeling
 *
 * @param {EventBus} eventBus
 * @param {ElementFactory} elementFactory
 * @param {CommandStack} commandStack
 */
function Modeling(eventBus, elementFactory, commandStack, processDiagramRules, elementRegistry) {
    DjsModeling.call(this, eventBus, elementFactory, commandStack);
    this._processDiagramRules = processDiagramRules;
    this._elementRegistry = elementRegistry;
    this._elementFactory = elementFactory;
}

Modeling.$inject = ['eventBus', 'elementFactory', 'commandStack', 'processDiagramRules', 'elementRegistry'];

inherits(Modeling, DjsModeling);

Modeling.prototype.connect = function (source, target, attrs, hints) {
    var rules = this._processDiagramRules;
    if (!attrs) {
        //canConnect(...) returns object with type property with semantic connection type.
        attrs = rules.canConnect(source, target);
    }
    if (attrs && attrs.type === 'bp:SequenceFlow') {
        var flowMarker = getNextFlowMarker(source);
        attrs = assign(attrs, {flowMarker: flowMarker});
    }
    //Always connect to the centres of figures (don't pass hints).
    return this.createConnection(source, target, attrs, source.parent, /*hints*/{});
};

Modeling.prototype.reconnectStart = function (connection, newSource, dockingOrPoints) {
    var flowMarker = getNextFlowMarker(newSource);
    var context = {
        connection: connection,
        newSource: newSource,
        dockingOrPoints: dockingOrPoints,
        flowMarker : flowMarker
    };
    this._commandStack.execute('connection.reconnectStart', context);
};

//TODO Make this function more robust and (loop on overflow) and move to utils.
function getNextFlowMarker(source) {
    var availableMarkers = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var sourceBo = getBusinessObject(source);
    if (sourceBo && instanceOf(sourceBo, 'bp:FlowNode')) {
        var flowMarkers = sourceBo.get('outgoing').map(
            function (flow) {
                return flow.get('flowMarker');
            });
        for (var i = 0; i < availableMarkers.length; i++) {
            var c = availableMarkers.charAt(i);
            if (flowMarkers.indexOf(c) === -1) {
                return c;
            }
        }
    }
    return "A";
}

function getBusinessObject(djsObject) {
    return djsObject && djsObject.businessObject || djsObject;
}

/**
 * Declare all the command handlers
 */
Modeling.prototype.getHandlers = function () {
    var handlers = DjsModeling.prototype.getHandlers.call(this);
    return assign(handlers, {
        'flownode.edit': EditFlowNodeHandler,
        /* Sid CBPM-3666 Changed from runExternalCommand to tibextProcessCommand - receivers of notifications need to know what model is being affected. */
        'tibextProcessCommand': ExternalCommandHandler,

        // override shape.delete with our own implementation
        'shape.delete': DeleteProcessShapeHandler,

        // override shape.create with our own implementation
        'shape.create': CreateProcessShapeHandler,

        // override shape.move with our own implementation
        'shape.move': MoveProcessShapeHandler,

        /* override shape.append with our own implementation */
        'shape.append': AppendProcessShapeHandler,

        'elements.create': CreateProcessElementsHandler,

        'processAutoStart.set': SetProcessAutoStartHandler,

        'processFormStart.set': SetProcessFormStartHandler,

        'lane.add': AddLaneHandler,

        'parallelFlowLane.move': MoveParallelFlowLaneHandler,

        'append.single.sub.process': AppendTaskToSubProcessHandler,
        'connection.reconnectStart': ReconnectSequenceFlowHandler,

        'remove.task.sub.process': RemoveTaskFromSubProcessHandler,

        /* override spaceTool with our own implementation */
        'spaceTool': DtSpaceToolHandler,
        /* override elements.delete with our own implementation */
        'elements.delete': DeleteProcessElementsHandler,

        /* override shape.resize with our own implementation*/
        'shape.resize': ResizeProcessShapeHandler,

        /* override Move event with our own implementation*/
        'move': ProcessMoveEvents
    });
};

/**
 * Updates a flow node for the given context to execute on the command stack
 *
 * @param node  - the flow node that is being edited
 * @param process - process whose data field is being edited
 * @returns {*}
 */
Modeling.prototype.editFlowNode = function (flownode, diagramElement, process, bpModdle) {

    var context = {
        flownode: flownode,
        diagramElement: diagramElement,
        process: process,
        bpModdle: bpModdle
    };

    this._commandStack.execute('flownode.edit', context);

    return context.flownode;
};

/**
 * Addes single task to the SubProcess
 *
 * @returns {*}
 */
Modeling.prototype.appendTaskToSubProcess = function (target, source, shape, modelCommands, attrs) {


    var context = {
        target: target,
        source: source,
        shape: shape,
        modelCommands: modelCommands,
        attrs : attrs
    };
    this._commandStack.execute('append.single.sub.process', context);
};

/**
 * Removed the tasks from the SubProcess.
 *
 * @param target target i.e. element in which elements to be removed is present
 * @param elements
 */
Modeling.prototype.removeTaskFromSubProcess = function (target, elements) {
    var context = {
        target: target,
        elements: elements
    };
    this._commandStack.execute('remove.task.sub.process', context);
};
/**
 * Changes process to auto start.
 *
 * @param startEventShape  - the didgram shape representing start event.
 * @param formTaskShape  - the didgram shape representing initial form task.
 * @param modelCommands - additional model commands to setup process to autostart.
 * @returns {*}
 */
Modeling.prototype.setProcessToAutoStart = function (startEventShape, formTaskShape, modelCommands) {
    var context = {
        startEventShape: startEventShape,
        formTaskShape: formTaskShape,
        modelCommands: modelCommands
    };
    this._commandStack.execute('processAutoStart.set', context);
};
/**
 * Changes process to form start.
 *
 * @param startEventShape  - the didgram shape representing start event.
 * @param modelCommands - additional model commands to setup process to form start.
 * @returns {*}
 */
Modeling.prototype.setProcessToFormStart = function (startEventShape, modelCommands) {
    var context = {
        startEventShape: startEventShape,
        modelCommands: modelCommands
    };
    this._commandStack.execute('processFormStart.set', context);
};

/**
 * Add a lane.
 *
 * @param {Shape} targetLaneShape The shape to add the lane to.
 * @param {string} location The location.
 *
 * @return {Shape} The added lane.
 */
Modeling.prototype.addLane = function (targetLaneShape, location) {
    var context = {
        shape: targetLaneShape,
        location: location
    };

    this._commandStack.execute('lane.add', context);

    return context.newLane;
};

/**
 * Move a lane to new position.
 *
 * @param {Shape} aTargetLaneShape The shape to add the lane to.
 * @param {string} aDestIndex New position.
 * @param {string} aSrcIndex Old position.
 *
 * @return {Shape} The added lane.
 */
Modeling.prototype.moveParallelFlowLane = function (aTargetLaneShape, aDestIndex, aSrcIndex) {
    var context = {
        shape: aTargetLaneShape,
        destIndex: aDestIndex,
        srcIndex: aSrcIndex
    };

    this._commandStack.execute('parallelFlowLane.move', context);
};

/**
 * Runs a command against the command stack. The command must have "execute" and "undo" functions.
 * The command is tagged as a 'tibextProcessCommand' which will tell even listeners that the command is
 * process model related.
 * Sid CBPM-3666 Changed from runExternalCommand to runProcessModelCommand and type=tibextProcessCommand- receivers of
 * notifications need to know what model is being affected.
 * @param command The command to execute.
 * @returns {*}
 */
Modeling.prototype.runProcessModelCommand = function (commands) {
    var context = {
        commands: commands
    };
    this._commandStack.execute('tibextProcessCommand', context);
    return commands.scope;
};
/**
 * Determines the given element can be deleted from the diagram or not.
 *
 * @param elements :- The elements which are needed to be removed.
 * @param calledManually Parameter to decide whether call is made directly through the UI or call from another function
 *
 */
Modeling.prototype.removeElements = function (elements, calledManually) {
    var rules = this._processDiagramRules;
    if (rules.canDelete(elements, calledManually)) {
        DjsModeling.prototype.removeElements.call(this, elements);
    } else {
        console.warn('Cannot delete locked elements.');
    }
};
/**
 * Creates and execute command(s) to remove a connection.
 * @param connection connection to remove.
 * @param hints
 */
Modeling.prototype.removeConnection = function (connection, hints) {
    var connectionBo = getBusinessObject(connection);
    var sourceBo = getBusinessObject(connection.source);
    if (instanceOf(sourceBo, 'bp:ExclusiveGateway') && sourceBo.default === connectionBo) {
        //Remove default reference from exclusive gateway.
        var removeDefaultCmd = this.setCommand(sourceBo, connection, sourceBo, 'default', undefined);
        this.runProcessModelCommand([removeDefaultCmd]);
    }
    DjsModeling.prototype.removeConnection.call(this, connection, hints);
};


/**
 *  CBPM-6417: Jan: This is a copy of setCommand from moddle-service which is ok for now, but if any other command is
 * needed then moddle-service.js should be refactored down into pcoess-diagram-js.
 */

/**
 * Creates a Set Command for execution by the CommandHandler.
 * @param mainAffectedElement The main top level selectable element (process, activity, flow, field) affected
 *     by the change.
 * @param diagramScope The diagram element corresponding to the element.
 * @param element The sub-element containing the attribute to change.
 * @param attribute The name of the attribute being changed.
 * @param value The new value.
 */
Modeling.prototype.setCommand = function (mainAffectedElement, diagramScope, element, attribute, value) {
    return {
        type: 'tibext.set', /* Sid CBPM-3666 - added command type for notifications. Do not change - ref'd elsewhere. */
        mainAffectedElement: mainAffectedElement,
        diagramScope: diagramScope,
        element: element,
        attribute: attribute,
        value: value,
        oldValue: null,
        execute: function () {
            this.oldValue = this.element[this.attribute];

            if (this.value === undefined) {
                delete this.element[this.attribute];
            } else {
                // CBPM-3777: We need to use model set function (if possible) as it correctly sets the property
                // descriptor. ('enumerable' feature needs to be set to false for reference properties.)
                if (angular.isFunction(this.element.set)) {
                    this.element.set(this.attribute, this.value);
                } else {
                    this.element[this.attribute] = this.value;
                }
            }

        },
        undo: function () {
            if (this.oldValue === undefined) {
                delete this.element[this.attribute];
            } else {
                if (angular.isFunction(this.element.set)) {
                    this.element.set(this.attribute, this.oldValue);
                } else {
                    this.element[this.attribute] = this.oldValue;
                }
            }
        }
    };
};

/**
 * Intersects the given connection with the given shape. This will place the
 * given shape between the given connection and a newly created connection,
 * with the shape as the connection's target. The new connection will then
 * be connected to the original connection's target.
 *
 * @param aConnection the connection to be intersected.
 * @param aShape the shape to intersect the connection.
 */
Modeling.prototype.intersectConnection = function (aConnection, aShape) {
    var source = aConnection.source;
    var oldTarget = aConnection.target;

    var direction = orientation(aConnection, 20);
    if (direction <= 0) {
        this.clearSpace(source, aShape, oldTarget, 'x', 'width');
    }
    if (direction >= 0) {
        this.clearSpace(source, aShape, oldTarget, 'y', 'height');
    }

    // calculate the centre of the new shape
    // to be used to dock the end of connection
    var dockingPoints = [aConnection.waypoints[0], getMid(aShape)];

    // set the connection's target as the new shape
    // this will adjust the business object references of the connection
    this.reconnectEnd(aConnection, aShape, dockingPoints);

    // re-position the line-ends of the adjusted connection
    var hints =  {connectionStart: dockingPoints[0], connectionEnd: dockingPoints[1]};
    this.layoutConnection(aConnection, hints);

    // create connection from new shape to connection's original target
    this.connect(aShape, oldTarget);

    /* CBPM-11614: Fix for IE/EDGE - 'element.out' is not fired on intersected connection. */
    var context = {
        element: aConnection,
        gfx: this._elementRegistry.getGraphics(aConnection)
    };
    this._eventBus.fire("element.out", context);
};

/**
 * Create clear space between the two shapes.
 *
 * @param aShapeA
 * @param aShapeB
 * @param aVertical
 */
Modeling.prototype.clearSpace = function (aShapeA, aShapeB, aShapeC, aAxis, aDim) {
    var buffer = Math.floor(aShapeB[aDim] / 2);

    // determine left-most / top-most element
    var overlappedElement = (aShapeA[aAxis] < aShapeC[aAxis]) ? aShapeA : aShapeC;

    // calculate dimension - with a buffer
    var p1 = overlappedElement[aAxis] - buffer;
    var p2 = overlappedElement[aAxis] + overlappedElement[aDim] + buffer;

    // if shape overlaps on the given axis
    if ((p1 < aShapeB[aAxis] + aShapeB[aDim]) && (p2 > aShapeB[aAxis])) {
        // move middle element to avoid overlap - with buffer
        var delta = {x: 0, y: 0};
        delta[aAxis] = overlappedElement[aAxis] + overlappedElement[aDim] + buffer - aShapeB[aAxis];
        this.moveElements([aShapeB], delta, undefined, false, {autoResize: false});
    }

    // determine right-most / bottom-most element
    var overlappedElement = (aShapeA[aAxis] >= aShapeC[aAxis]) ? aShapeA : aShapeC;

    // calculate dimension - with a buffer
    p1 = overlappedElement[aAxis] - buffer;
    p2 = overlappedElement[aAxis] + overlappedElement[aDim] + buffer;

    // if shape overlaps on the given axis
    if ((p1 < aShapeB[aAxis] + aShapeB[aDim]) && (p2 > aShapeB[aAxis])) {
        // move all right-most / bottom-most elements to avoid overlap - with buffer
        var delta = {x: 0, y: 0};
        delta[aAxis] = aShapeB[aAxis] + aShapeB[aDim] + buffer - overlappedElement[aAxis];

        var elements = (aAxis === 'x') ? elementsRightOf(aShapeB) : elementsBelow(aShapeB);
        this.moveElements(elements, delta, undefined, false, {autoResize: false});
    }
};

/**
 * Return the array of Shapes belongs to initial Parallel flow container.
 * Returned array will have ParallelLaneContainer as a first element followed by containing shapes.
 * This function is used to create default ParallelFlowContainer (e.g. from palette or context pad)
 * @returns Array of Shapes object containing initial parallel flow container and it's children.
 */
Modeling.prototype.createInitialParallelFlowContainerShapes = function () {
    var elementFactory = this._elementFactory;

    var parallelLaneContainer = elementFactory.createShape({
        type: 'bp:SubProcess',
        subProcessType: 'ParallelLaneContainer'
    });

    var parallelLane1 = elementFactory.createShape({
        type: 'bp:SubProcess',
        subProcessType: 'ParallelLane',
        parent: parallelLaneContainer,
        parentFlowContainer: parallelLaneContainer, //Associate the top-most 'parallel flow container' as the parentFlowContainer
        y: 30
    });

    var emptyTask1 = elementFactory.createShape({
        type: 'bp:EmptyTask',
        parent: parallelLane1,
        parentFlowContainer: parallelLaneContainer, //Associate the top-most 'parallel flow container' as the parentFlowContainer
        x: 50,
        y: 60
    });

    var parallelLane2 = elementFactory.createShape({
        type: 'bp:SubProcess',
        subProcessType: 'ParallelLane',
        parent: parallelLaneContainer,
        parentFlowContainer: parallelLaneContainer, //Associate the top-most 'parallel flow container' as the parentFlowContainer
        y: 210
    });

    var emptyTask2 = elementFactory.createShape({
        type: 'bp:EmptyTask',
        parent: parallelLane2,
        parentFlowContainer: parallelLaneContainer, //Associate the top-most 'parallel flow container' as the parentFlowContainer
        x: 50,
        y: 240
    });

    return [parallelLaneContainer, parallelLane1, emptyTask1, parallelLane2, emptyTask2];
}
export default Modeling;