import inherits from 'inherits';
import KeyboardBindings from 'diagram-js/lib/features/keyboard/KeyboardBindings';

/**
 *
 * @constructor
 * @extends diagram-js/lib/features/keyboard/KeyboardBindings'
 *
 * @param {Injector} injector
 */
export default function ProcessKeyBoardBindings(injector) {
    injector.invoke(KeyboardBindings, this);
}

inherits(ProcessKeyBoardBindings, KeyboardBindings);

ProcessKeyBoardBindings.$inject = [
    'injector'
];


ProcessKeyBoardBindings.prototype.registerBindings = function(keyboard, editorActions) {

    // inherit default bindings
    KeyboardBindings.prototype.registerBindings.call(this, keyboard, editorActions);

    /**
     * Add keyboard binding if respective editor action
     * is registered.
     *
     * @param {String} action name
     * @param {Function} fn that implements the key binding
     */
    function addListener(action, fn) {

        if (editorActions.isRegistered(action)) {
            keyboard.addListener(fn);
        }
    }
}