'use strict';

import forEach from 'lodash/forEach';
import inherits from 'inherits';
import DeleteElementsHandler from 'diagram-js/lib/features/modeling/cmd/DeleteElementsHandler';

function RemoveTaskFromSubProcessHandler(modeling, elementFactory, elementRegistry, selection) {
    // Super CONSTRUCTOR
    DeleteElementsHandler.call(this, modeling, elementRegistry);

    this._modeling = modeling;
    this._elementFactory = elementFactory;
    this._selection = selection;
}

RemoveTaskFromSubProcessHandler.$inject = ['modeling', 'elementFactory', 'elementRegistry', 'selection'];

inherits(RemoveTaskFromSubProcessHandler, DeleteElementsHandler);


RemoveTaskFromSubProcessHandler.prototype.preExecute = function (context) {
    var modeling = this._modeling,
        selection = this._selection;
    var deltaWidthOfConnection = 60;
    var deltaForWidth = 0;
    var newWidthOfTarget = 0;
    var newXCordinateOfTarget = 0;

    RemoveTaskFromSubProcessHandler.super_.prototype.postExecute.call(this, context);

    forEach(context.elements, function (element) {
        //Updating the Width & X-Cordinate of the target i.e. Shape Object in which other shapes are created.
        deltaForWidth = element.width + deltaWidthOfConnection + deltaForWidth;
        newWidthOfTarget = context.target.width - deltaForWidth;
        newXCordinateOfTarget = context.target.x + deltaForWidth;
    });

    var newBoundsOfSubProcess = {
        x: newXCordinateOfTarget,
        y: context.target.y,
        height: context.target.height,
        width: newWidthOfTarget
    };
    // Resizing the subProcess.
    modeling.resizeShape(context.target, newBoundsOfSubProcess);
    selection.select(context.target);
    context.xDisplacement = deltaForWidth;
};

RemoveTaskFromSubProcessHandler.prototype.postExecute = function (context) {
    var elementFactory = this._elementFactory;
    var modeling = this._modeling;

    var deltaForMovingDiagram = {
        x: -(context.xDisplacement),
        y: 0
    };
    var movingElements = [];
    var diagramElements = elementFactory.dtDiagram.model.diagrams[0].plane.planeElement;
    forEach(diagramElements, function (diElement) {
        movingElements.push(elementFactory.dtDiagram.getDiagramObject(diElement.bpElement));
    });



    /**
     * Chaitanya CBPM-22665 :- Adoption of Diagram.js 7.3.0
     *
     * Point 1 :- Added start attribute to 'createSpace' method
     * Point 2 :- Added resizingElements to blank array  to 'createSpace' method
     *
     * as result of below commit
     * "fix(space-tool): add/remove space without side effects" over github.
     *
     * https://github.com/bpmn-io/diagram-js/commit/4a02597dd613e026b564cc88300a934df5f833c1
     */
    var start = 0;
    var resizingElements = [];
    //Moving all the diagram Elements to their new position.
    modeling.createSpace(movingElements,  resizingElements , deltaForMovingDiagram , 'e', start)
};
export default RemoveTaskFromSubProcessHandler;