'use strict';

import some from 'lodash/some';
import forEach from 'lodash/forEach';
var round = Math.round;
import assign from 'lodash/assign';

function AppendTaskToSubProcessHandler(modeling, elementFactory) {
    this._modeling = modeling;
    this._elementFactory = elementFactory;
}

AppendTaskToSubProcessHandler.$inject = ['modeling', 'elementFactory'];


AppendTaskToSubProcessHandler.prototype.preExecute = function (context) {
    var elementFactory = this._elementFactory;
    var modeling = this._modeling;
    var deltaWidthOfConnection = 60;
    var delta = 0;
    var deltaForWidth = 0;

    var createdSvgShapes = [];
    var newWidthOfTarget = 0;
    var newXCordinateOfTarget = 0;
    var newXCordinateofSource = 0;
    var shapeAttrs = {
        taskCounter: 3
    };

    forEach(context.shape, function (shapeToAdd) {
        var attrs = context.attrs ? context.attrs : {};
        // Passing the task counter as task names are incremented
        var svgShapeCreated = elementFactory.createShape(assign(attrs, {
            type: shapeToAdd,
            shapeAttrs: shapeAttrs
        }));

        //Updating the Width & X-Cordinate of the target i.e. Shape Object in which other shapes are created.
        deltaForWidth = svgShapeCreated.width + deltaWidthOfConnection + deltaForWidth;
        newWidthOfTarget = context.target.width + deltaForWidth;
        newXCordinateOfTarget = context.target.x - deltaForWidth;

        //Calculations done depending upon the current source to calculate the position of target element.
        delta = (context.source.width + deltaWidthOfConnection) + delta;
        newXCordinateofSource = context.source.x - delta + round(context.source.width / 2);
        var position = {
            "x": newXCordinateofSource,
            "y": context.source.y + round(context.source.height / 2)
        };

        createdSvgShapes.push({"shape": svgShapeCreated, "position": position});
    });

    var newBoundsOfSubProcess = {
        x: newXCordinateOfTarget,
        y: context.target.y,
        height: context.target.height,
        width: newWidthOfTarget
    };

    modeling.resizeShape(context.target, newBoundsOfSubProcess);

    var shapes = [];
    forEach(createdSvgShapes, function (createdSvgShape) {
        var shape = modeling.createShape(
            createdSvgShape.shape,
            createdSvgShape.position,
            context.target, {attach: context.attach});
        shapes.push(shape);
    });

    context.shapes = shapes;
    context.xDisplacement = deltaForWidth;
}

AppendTaskToSubProcessHandler.prototype.postExecute = function (context) {
    var modeling = this._modeling;
    var elementFactory = this._elementFactory;
    var parent = context.connectionParent || context.shape.parent;

    var connection = {
        type: 'bp:SequenceFlow',
        "flowMarker": "A"
    };

    var deltaForMovingDiagram = {
        x: context.xDisplacement,
        y: 0
    };
    var movingElements = [];
    var diagramElements = elementFactory.dtDiagram.model.diagrams[0].plane.planeElement;

    var isFirstConnectionCreated = false;
    var updatedSource = '';
    forEach(context.shapes, function (shape) {
        parent = shape.parent;
        if (!isFirstConnectionCreated && !existsConnection(shape, context.source)) {
            modeling.connect(shape, context.source, connection, shape.parent);
            updatedSource = shape;
            isFirstConnectionCreated = true;
        } else if (isFirstConnectionCreated && !existsConnection(shape, updatedSource)) {
            modeling.connect(shape, updatedSource, connection, shape.parent);
            updatedSource = shape;
        }
    });

    forEach(diagramElements, function (diElement) {
        movingElements.push(elementFactory.dtDiagram.getDiagramObject(diElement.bpElement));
    });



    /**
     * Chaitanya CBPM-22665 :- Adoption of Diagram.js 7.3.0
     *
     * Point 1 :- Added start attribute to 'createSpace' method
     * Point 2 :- Added resizingElements to blank array  to 'createSpace' method
     *
     * as result of below commit
     * "fix(space-tool): add/remove space without side effects" over github.
     *
     * https://github.com/bpmn-io/diagram-js/commit/4a02597dd613e026b564cc88300a934df5f833c1
     */
    var start = -deltaForMovingDiagram.x;
    var resizingElements = [];
    //Moving all the diagram Elements to their new position.
    modeling.createSpace(movingElements, resizingElements ,  deltaForMovingDiagram ,'e', start);

    var modelCommands = context.modelCommands;
    //Unsetting the conversational Interface if already set
    if (modelCommands && modelCommands.length >= 0) {
        modeling.runProcessModelCommand(modelCommands)
    }
};


AppendTaskToSubProcessHandler.prototype.execute = function (context) {
};

AppendTaskToSubProcessHandler.prototype.revert = function (context) {
};

function existsConnection(source, target) {
    return some(source.outgoing, function (c) {
        return c.target === target;
    });
}

export default AppendTaskToSubProcessHandler;