'use strict';
import assign from 'lodash/assign';


/**
 * Palette provider for process-editor.
 */
function PaletteProvider(palette, create, elementFactory, spaceTool, lassoTool, modeling) {

    this._create = create;
    this._elementFactory = elementFactory;
    this._spaceTool = spaceTool;
    this._lassoTool = lassoTool;
    this._modeling = modeling;

    palette.registerProvider(this);
}
PaletteProvider.$inject = ['palette', 'create', 'elementFactory', 'spaceTool', 'lassoTool', 'modeling'];



PaletteProvider.prototype.getPaletteEntries = function (element) {

    var create = this._create,
        elementFactory = this._elementFactory,
        spaceTool = this._spaceTool,
        lassoTool = this._lassoTool,
        modeling = this._modeling;

    function startCreateShape(event, initObjWithType) {
        var shape = elementFactory.createShape(initObjWithType);
        create.start(event, shape);
    }

    /**
     * CBPM-26115 Creates a 'Parallel Flow Container'
     * with 2 "Parallel flow lanes" - each containing an Empty Task
     * @param event
     */
    function startCreateParallelFlowContainer(event) {
        var shapes = modeling.createInitialParallelFlowContainerShapes(element) || [];

        var parallelLaneContainer = shapes[0];
        create.start(event, shapes, {
            hints: {
                autoSelect: [parallelLaneContainer]
            }
        });
    }

    return {
        'lasso-tool': {
            group: 'tools',
            className: 'dt-bpm-icon-ic_lasso',
            title: 'Activate the lasso selection tool',
            action: {
                click: function (event) {
                    lassoTool.activateSelection(event);
                }
            }
        },
        'space-tool': {
            group: 'tools',
            className: 'dt-bpm-icon-ic_seperator',
            title: 'Activate the create/remove space tool',
            action: {
                click: function (event) {
                    spaceTool.activateSelection(event);
                }
            }
        },
        'tool-separator': {
            group: 'tools',
            separator: true
        },
        'task-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-ic_task',
            title: 'Create task',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:EmptyTask'});},
                click:function (event) {startCreateShape(event, {type: 'bp:EmptyTask'});}
            }
        },
        'parallel-flow-container-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-ic_parallel_flows',
            title: 'Create parallel flows',
            action: {
                dragstart: function (event) {startCreateParallelFlowContainer(event);},
                click:function (event) {startCreateParallelFlowContainer(event);}
            }
        },
        /* Start event removed from palete as it will now always be in the template.
        'start-event-tool': {
            group: 'activities',
            className: 'dt-icon-tool-start-event',
            title: 'Create task',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:StartEvent'});},
                click: function (event) {startCreateShape(event, {type: 'bp:StartEvent'});}
            }
        },*/
        'exclusive-gateway-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-ic_decision_point',
            title: 'Create decision point',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:ExclusiveGateway'});},
                click: function (event) {startCreateShape(event, {type: 'bp:ExclusiveGateway'});}
            }
        },
        //JA: CBPM-4227 End event should be disabled from palette.
        /*
        'parallel-gateway-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-ic_parallel',
            title: 'Create parallel gateway',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:ParallelGateway'});},
                click: function (event) {startCreateShape(event, {type: 'bp:ParallelGateway'});}
            }
        }
        */
        'end-event-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-ic_endpoint',
            title: 'Create end event',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:EndEvent'});},
                click: function (event) {startCreateShape(event, {type: 'bp:EndEvent'});}
            }
        },

        'nodes-separator': {
            group: 'nodes',
            separator: true
        },
        //JA: Disabled text annotations as it is not possible at the moment to wet text or resize them.

        /*'artifact-separator': {
            group: 'artifacts',
            separator: true
        },*/
        'text-annotation-tool': {
            group: 'nodes',
            className: 'dt-bpm-icon-text-annotation',
            title: 'Create text annotation',
            action: {
                dragstart: function (event) {startCreateShape(event, {type: 'bp:TextAnnotation'});},
                click: function (event) {startCreateShape(event, {type: 'bp:TextAnnotation'});}
            }
        }

    };
};

export default PaletteProvider;
