'use strict';

import inherits from 'inherits';

import CreateElementsHandler from "diagram-js/lib/features/modeling/cmd/CreateElementsHandler";
import {some} from "lodash";


/**
 * A handler that extends diagram js CreateElementsHandler to append (create) shapes from quick icons provided on the
 * shapes. Once the base CreateElementsHandler creates the passed shape, this handler connect the passed connectionSource
 * and connectionTarget from 'context.hints' object.
 *
 * @param modeling
 * @constructor
 */
function CreateProcessElementsHandler(modeling) {

    /* Super CONSTRUCTOR */
    CreateElementsHandler.call(this, modeling);

    this._modeling = modeling;
}

CreateProcessElementsHandler.$inject = ['modeling'];

inherits(CreateProcessElementsHandler, CreateElementsHandler);


/**
 * Overrides CreateElementsHandler of diagram js.
 *
 * @param context
 */
CreateProcessElementsHandler.prototype.preExecute = function (context) {
    var modeling = this._modeling,
        hints = context.hints || {};
    /* call the default implementation of preExecute */
    if (CreateElementsHandler.prototype.preExecute) {

        CreateElementsHandler.prototype.preExecute.call(this, context);

        // If it's operation and connectionSource & connectionTarget are passed then create new connection between them.
        if(hints.isAppend && hints.connectionSource && hints.connectionTarget) {
            if(!existsConnection(hints.connectionSource, hints.connectionTarget)) {
                modeling.connect(hints.connectionSource, hints.connectionTarget, {type: "bp:SequenceFlow"});
            }
        }
    }
}

/**
 *  Returns true if connection exists between passed source and target otherwise return false.
 * @param source
 * @param target
 * @returns {boolean}
 */
function existsConnection(source, target) {
    return some(source.outgoing, function (c) {
        return c.target === target;
    });
}

export default CreateProcessElementsHandler;
