'use strict';

import { Moddle } from 'moddle';
import assign from 'lodash/assign';
import cloneDeepWith from 'lodash/cloneDeepWith';
import inherits from 'inherits';
import omitBy from 'lodash/omitBy';
import pick from 'lodash/pick';
import pickBy from 'lodash/pickBy';
import forOwn from 'lodash/forOwn';
import isObject from 'lodash/isObject';
import isArray from 'lodash/isArray';
import map from 'lodash/map';
import isFunction from 'lodash/isFunction';
import * as Collections from 'diagram-js/lib/util/Collections';

import IdSupport from './id-support';
import Ids from './Ids';

import Refs from 'object-refs';
var semanticDiRefs = new Refs({name: 'bpElement', enumerable: true}, {name: 'diElement'});

import bp from './json/bp.json';
import bpdi from './json/bpdi.json';
import dc from './json/dc.json';
import di from './json/di.json';

var packages = {
    bp: bp,
    bpdi: bpdi,
    dc: dc,
    di: di
};

/* Sid CBPM-20853 prefix for preserved original id reference properties that we want to preserve if reference unresolved. */
var BPMODDLE_ORIGINAL_REF_PREFIX = '__Original_';


/**
 * A sub class of {@link Moddle} with support for import and export of ABPM json files.
 *
 * @class BpModdle
 * @extends Moddle
 *
 * @param {Object|Array} packages to use for instantiating the model
 * @param {Object} [options] additional options to pass to moddle.
 */
function BpModdle(packages, options) {
    Moddle.call(this, packages, options);
    IdSupport(this, new Ids());
    this.ids = new Ids();
}

inherits(BpModdle, Moddle);

Moddle.prototype._baseCreate = Moddle.prototype.create;

BpModdle.prototype.create = function (descriptor, attrs){
   var bo =  this._baseCreate(descriptor, attrs);
   if(bo.$instanceOf('bp:SubProcess')){
       /**
        * CBPM-26114 : Chaitanya.
        * Creating the getter for subProcessType.
        * Returns the subProcessType for given object or else returns 'InitialTasks' if not set.
        *
        * @returns {*|string}
        */
        bo.__proto__.getSubProcessType = function (){
            if(this.subProcessType){
                return this.subProcessType;
            }
            return 'InitialTasks';
        }
    }
   return bo;
};


BpModdle.prototype._withId = function (element) {
    return element.$instanceOf('bp:BaseElement') ||
        element.$instanceOf('bpdi:BPShape') ||
        element.$instanceOf('bpdi:BPEdge') ||
        element.$instanceOf('bpdi:BPDiagram') ||
        element.$instanceOf('bpdi:BPPlane');
};

//TODO Refactor _ensureId().
BpModdle.prototype._addGeneratedId = function (moddleElement) {
    if (!moddleElement.id && this._withId(moddleElement)) {
        moddleElement.id = this.ids.nextForElement(moddleElement);
    }
};

/**
 * Crete an object
 * @param type
 * @param attrs
 * @returns {type}
 */
BpModdle.prototype.createWithId = function (type, attrs) {
    var mObject = this.create(type, attrs);
    if (mObject) {
        this._addGeneratedId(mObject);
    }
    return mObject;

};

/**
 * Fids model element by id.
 * @param id The id of the object to find.
 * @returns {object| undefined} returns moddle element if exists (or existed). It will also return elements which were
 *     in the model before but were removed.
 */
BpModdle.prototype.findElementById = function (id) {
    return this.ids._idsHash[id];
};

/**
 * Binds a 2-way reference for a semantic element: semantic.diElement <-> di.bpElement.
 * Then if you set semantic.diElement to di then it also sets di.bpElement to semantic (but it does not work in the
 * other direction).
 *
 * @param {object} semantic Smantic object instance (the one that should contain 'diElement' ref. property)
 */
BpModdle.prototype.bindSemanticDiRef = function (semantic) {
    if (semantic) {
        var diDesc = Object.getOwnPropertyDescriptor(semantic, 'diElement');
        if (!diDesc || (diDesc && diDesc.configurable)) {
            semanticDiRefs.bind(semantic, 'diElement');
        }
    }
};


/**
 * Creates initial (empty) model for a new artifact.
 */
BpModdle.prototype.createInitialProcessModel = function () {
    var definitions = this.createWithId('bp:Definitions');
    var process = this.createWithId('bp:Process');
    definitions.get('rootElements').push(process);
    var bpDiagram = this.createWithId('bpdi:BPDiagram');
    definitions.get('diagrams').push(bpDiagram);
    var bpPlane = this.createWithId('bpdi:BPPlane', {
        id: process.id + '_di',
        bpElement: process
    });
    bpDiagram.set('plane', bpPlane);
    return definitions;
};

/**
 * Creates an instance of BP model from a JSON string.
 *
 * @param {String|Object} json JSON string or object.
 * @param {Object} [options] object with options.
 * @param {object} [options] Additional options for diagram.
 * @param {boolean} [options.skipCleanse] is truthy then cleaning of model is skipped.
 * @param {function} [options.translate] translate function (string -> string).
 */
BpModdle.prototype.fromJson = function (json, options) {
    var _options = options || {};
    var translate = isFunction(_options.translate) ? options.translate : function (key) {return key};
    var simpleRefPropertyNames = ['bpElement', 'sourceRef', 'targetRef', 'caseField', 'dataItem', 'default'];
    var arrayRefPropertyNames = ['outgoing'];
    var refPropertyNames = simpleRefPropertyNames.concat(arrayRefPropertyNames);

    /*
     * Sid CBPM-20853 object defining the properties that are id references that are nominally resolved
     *  to actual objects THAT MUST BE preserved on re-serialise if they 'go missing' during de-serialisation (because
     * that are unresovled at that time). This is for things like bp:DataPath.dataItem which may have dataItem
     * references to temporary fields that are loaded DYNAMICALLY during expression edit and therefore can't be resolved
     * on model load (therefore the dataItem property is not put in loaded DataPath model).
     *
     * Any property mentioned in this map object therefore will on load have the property value backed up as '__Original_<ref property name>'
     * and if the original 'ref property name>' property is not set when the model is serialised, it will be written
     * as the original value saved in teh '__Original_<ref property name>' property
     *
     * This is a map of object type name to array of propery names to treat in this way (so that preservation of
     * original value is restricted and won't happen for objects that we actually may want to unset ref's on.
     */
    var preserveOriginalRefPropertiesMap = {
        'bp:DataPath' : ["dataItem"]
    };

    var bpModel = (typeof json === 'string') ? JSON.parse(json) : json;

    function createModdle(bpModdle, object, refs) {
        if (isObject(object) && object.$type) {
            var type = object.$type;

            // Sid CBPM-24454 lodash 4.17.21 has separate pick(obj, propertyNames) and pickBy(obj, predicateFunc)
            var basicProps = omitBy(object, function (value, key) {
                return (key === '$type')
                    || isObject(value)
                    || isArray(value)
                    || refPropertyNames.indexOf(key) !== -1;
            });

            var refProps = pick(object, refPropertyNames);
            var mObject = bpModdle.create(type, basicProps);

            // Store ids and mObjects in context.ids {id -> mObject}
            if (object.id) {
                refs.ids = refs.ids || {};
                if (refs.ids[object.id]) {
                    console.log('Duplicate id: [' + object.id + ']');
                } else {
                    refs.ids[object.id] = mObject;
                }
            }

            // Store reference properties in: context.refs [[{mObject}, referenceProperies]...]
            if (Object.getOwnPropertyNames(refProps).length > 0) {
                refs.refs = refs.refs || [];
                refs.refs.push([mObject, refProps]);

            }

            //handle complex properites
            // Sid CBPM-24454 lodash 4.17.21 has separate pick(obj, propertyNames) and pickBy(obj, predicateFunc)
            var objectsOrArraysProps = pickBy(object, function (value, key) {
                return isObject(value) || (isArray(value) && arrayRefPropertyNames.indexOf(key) === -1);
            });
            forOwn(objectsOrArraysProps, function (value, key) {
                mObject.set(key, createModdle(bpModdle, value, refs));
            });
            return mObject;
        } else if (isArray(object)) {
            return map(object, function (value) {
                return createModdle(bpModdle, value, refs);
            });
        }
        return object;
    }

    function resolveRefs(context) {
        if (context && context.ids && context.refs) {
            var ids = context.ids;

            context.refs.forEach(function (reference) {
                var mObject = reference[0], //this is the owner of the reference property.
                    oRefs = reference[1]; //object containing copied unresolved reference properties.

                forOwn(oRefs, function (value, key) {
                        var refTarget;
                        if (isArray(value)) {
                            var mObjectArray = mObject.get(key);
                            value.map(function (id, index) {
                                var refTargetObject = ids[id];
                                if (refTargetObject) {
                                    mObjectArray[index] = refTargetObject;
                                } else {
                                    console.log('bpModdle.load.resolveRefs() Unresolved ref (in an array): [' + id + '] for property [' + key + ']');
                                }
                            });
                        } else {
                            refTarget = ids[value];

                            /*
                             * Sid CBPM-20853 If this is a reference property tagged for preservation if
                             *  unresolved on load, then preserve the original ref value as '__Original_<ref property name>'
                             */
                            var refPropertyValuePreserved = false;
                            if (mObject.$type) {
                                var preserveRefPropertiesForType = preserveOriginalRefPropertiesMap[mObject.$type];

                                if (preserveRefPropertiesForType && preserveRefPropertiesForType.includes(key)) {
                                    refPropertyValuePreserved = true;

                                    mObject[BPMODDLE_ORIGINAL_REF_PREFIX+key] = value;

                                    // Sid CBPM-20853 handy debugging...
                                    // console.log("bpModdle.load.resolveRefs(): Preserving reference '"+value+"' for property '" +
                                    //     key + "' in object: " + JSON.stringify(mObject));
                                }
                            }

                            if (refTarget) {
                                mObject.set(key, refTarget);

                                // Sid CBPM-20853 handy debugging...
                                // console.log("bpModdle.load.resolveRefs(): Reference resolved successfully for property '" +
                                //    key + "'='"+value+"' in object: " + JSON.stringify(mObject));

                            } else {
                                /* Only complain about unresolved properties if we're not dealing with it in other ways. */
                                if (!refPropertyValuePreserved) {
                                    console.log('bpModdle.load.resolveRefs() Unresolved ref: [' + value + '] for property [' + key + ']');
                                }
                            }
                        }
                    }
                );
            });

            // Fallback to create back references SequenceFlow.targetRef and SequenceFlow.sourceRef
            // if incomming or outgoing were not provided.
            context.refs.forEach(function (value) {
                var mObject = value[0],
                    oRefs = value[1];
                forOwn(oRefs, function (value, key) {
                        var refTarget = ids[value];
                        if (refTarget) {
                            if (key === 'sourceRef') {
                                var outgoing = refTarget.get('outgoing');
                                if (outgoing && outgoing.indexOf(mObject) < 0) {
                                    outgoing.push(mObject);
                                }
                            }
                            if (key === 'targetRef') {
                                var incoming = refTarget.get('incoming');
                                if (incoming && incoming.indexOf(mObject) < 0) {
                                    incoming.push(mObject);
                                }
                            }

                        }
                    }
                )
            });
        }
    }

    /**
     * Creates system data fields and returns the array of system data fields
     *
     * @returns {Array}
     */
    function createSystemFields() {

        var procStarterField = {
            $type: 'bp:DataField',
            id: '$LA_PROCESS_STARTER',
            internalName: '$LA_PROCESS_STARTER',
            name: translate('dtapp.processDefinitionProperties.PROCESS_STARTER'),
            type: {$type: 'bp:BaseType', name: 'User'},
            isSystem: true
        };
        var caseStarterField = {
            $type: 'bp:DataField',
            id: '$LA_CASE_STARTER',
            internalName: '$LA_CASE_STARTER',
            name: translate('dtapp.processDefinitionProperties.CASE_STARTER'),
            type:  {$type: 'bp:BaseType', name: 'User'},
            isSystem: true
        };

        var appConfigType = {
            $type: 'bp:DataField',
            id: '$CONFIGURATION',
            internalName: '$CONFIGURATION',
            name: translate('dtapp.processDefinitionProperties.APP_CONFIGURATION'),
            type:  {$type: 'bp:StructuredType', typeId : '-1'},
            isSystem: true
        }

        return [procStarterField, caseStarterField, appConfigType];
    }

    var refs = {};

    /* Add system data fields */
    var process = bpModel.rootElements[0];
    process.systemData = createSystemFields();

    var definitions = createModdle(this, bpModel, refs);
    resolveRefs(refs);
    if (!_options.skipCleanse) {
        var cleanseStatus = this.cleanseModel(definitions);
        if (cleanseStatus.severity === 'ERROR') {
            console.error('Process was cleansed during load.');
            console.error(cleanseStatus.message);
        }
    }
    return definitions;
};

/**
 * Cleanse the process model.
 * WARNING:  This method potentially modifies model. Only the semantic and diagram model is cleaned (not associated
 * diagram.js model) so if error is discovered and rectified then the diagram MUST be reloaded from the updated model
 * before proceeding with editing.
 *
 * Attempts to clean some problems with the model.
 *  - removes invalid flows (ones which have invalid sourceRef or targetRef) also removes the diagram element.
 *  - removes invalid outgoing elements (if the outgoing is null, undefined, unresolved id.
 *  - removes default element invalid reference (or it is not in the one of the element's outgoing flows)
 *  - removes diagram flow elements that have invalid semantic model reference.
 *
 *
 * @param {Object} definitions Model to clean.
 * @param {Object} [options] Additional options. Use options.rectify = false to stop changing model ("validate only"
 *     case).
 *
 * @returns {Object} cleanse status object (for example: {severity:'OK'|'ERROR', message: 'Message explaining
 *     problem.'}).
 */
BpModdle.prototype.cleanseModel = function cleanseModel(definitions, options) {
    /* CBPM-5490: Cleanse process model broken references. */

    var self = this;
    var cleanseOptions = assign({rectify: true}, options || {});
    var diagnostics = [];
    var removedFlows = {};
    if (definitions && isArray(definitions.rootElements)
        && definitions.rootElements[0] && isArray(definitions.rootElements[0].flowElements)) {

        //clean invalid flows.
        var flowElements = getAllFlowElements(definitions.rootElements[0]);
        flowElements.forEach(function (flowElement, index) {
            if (flowElement.$instanceOf && flowElement.$instanceOf('bp:SequenceFlow')) {
                var sequenceFlow = flowElement;
                var sourceRef = sequenceFlow.sourceRef;
                var targetRef = sequenceFlow.targetRef;
                var sourceInFlow = flowElements.indexOf(sourceRef) !== -1;
                var targetInFlow = flowElements.indexOf(targetRef) !== -1;

                if (!isObject(sourceRef) || !isObject(targetRef) || !sourceInFlow || !targetInFlow) {
                    if (cleanseOptions.rectify) {
                        flowElements.splice(index, 1);
                        removeFlowElement(definitions.rootElements[0], flowElement);
                        //save removed flow.
                        removedFlows[sequenceFlow.id] = sequenceFlow;
                    }

                    //Diagnostic
                    var sourceRefDesc = isObject(sourceRef) ?
                    'valid (' + sourceRef.id + ')' :
                    'invalid (' + sourceRef + ')';
                    var targetRefDesc = isObject(targetRef) ?
                    'valid (' + targetRef.id + ')' :
                    'invalid (' + targetRef + ')';
                    var operationMessage = 'Flow ' + sequenceFlow.id + ' is invalid. Source ref: ' + sourceRefDesc +
                        ', target ref: ' + targetRefDesc + '.';
                    if (!sourceInFlow) {
                        operationMessage += ' Source not in flow.';
                    }
                    if (!targetInFlow) {
                        operationMessage += ' Target not in flow.';
                    }
                    diagnostics.push(
                        {operation: 'FLOW_INVALID', contextObjectId: sequenceFlow.id, message: operationMessage})
                }
            }
        });

        var process = definitions.rootElements[0];

        /* add system data fields only if they don't already exist */
        var systemFields = process.get('systemData');
        var isProcessStarterExists = false;
        var isCaseStarterExists = false;
        systemFields.forEach(function (field) {
            if (field.id === '$LA_PROCESS_STARTER') {

                isProcessStarterExists = true;
            }
            if (field.id === '$LA_CASE_STARTER') {

                isCaseStarterExists = true;
            }
        });
        if (!isProcessStarterExists) {

            var userDataType = self.createWithId('bp:BaseType', {name: 'User'});
            var procStarterField = self.create('bp:DataField', {
                id: '$LA_PROCESS_STARTER',
                internalName: '$LA_PROCESS_STARTER',
                name: "Process Starter",  //TODO: localise this
            });
            procStarterField.set('type', userDataType);
            procStarterField.set('isSystem', true);
            process.get('systemData').push(procStarterField);
        }

        if (!isCaseStarterExists) {

            var userDataType = self.createWithId('bp:BaseType', {name: 'User'});
            var caseStarterField = self.create('bp:CaseField', {
                id: '$LA_CASE_STARTER',
                internalName: '$LA_CASE_STARTER',
                name: "Case Starter",  //TODO: localise this
            });
            caseStarterField.set('type', userDataType);
            caseStarterField.set('isSystem', true);
            process.get('systemData').push(caseStarterField);
        }

        //clean outgoing
        flowElements.forEach(function (flowElement, index) {
            if (flowElement.$instanceOf && flowElement.$instanceOf('bp:FlowNode')) {
                var node = flowElement;
                if (node.outgoing) {
                    node.outgoing.forEach(function (outgoingElement, index) {
                        if (!isObject(outgoingElement) || removedFlows[outgoingElement.id]) {
                            if (cleanseOptions.rectify) {
                                node.outgoing.splice(index, 1);

                            }

                            //Diagnostic
                            var outgoingDesc = isObject(outgoingElement) ?
                            'value (' + outgoingElement.id + ')' :
                            'invalid value (' + outgoingElement + ')';
                            var operationMessage = 'Outgoing flow of: ' + node.id +
                                ' is invalid. Outgoing index: ' + index + ', outgoing desc.: ' + outgoingDesc + '.';
                            diagnostics.push({
                                operation: 'OUTGOING_INVALID',
                                contextObjectId: node.id,
                                message: operationMessage
                            })
                        }
                    });
                    // Delete default if it is not one of the outgoing flow.
                    if (node.default && node.outgoing.indexOf(node.default) === -1) {
                        if (cleanseOptions.rectify) {
                            delete node.default;
                        }

                        //Diagnostic
                        var defaultDesc = isObject(node.default) ?
                        'value (' + node.default.id + ')' :
                        'invalid value (' + node.default + ')';
                        var operationMessage = 'Default flow of: ' + node.id +
                            ' is invalid. Default desc: ' + defaultDesc + '.';
                        diagnostics.push(
                            {operation: 'DEFAULT_INVALID', contextObjectId: node.id, message: operationMessage})
                    }
                }
            }
        });

        /* CBPM-14573: Assign ids to data associations */
        flowElements.forEach(function (flowElement) {

            if (flowElement.$instanceOf && (flowElement.$instanceOf('bp:FormTask') || flowElement.$instanceOf('bp:UserTask'))) {

                var formOrUserTask = flowElement;
                if (formOrUserTask.dataAssociations && formOrUserTask.dataAssociations.length > 0) {

                    formOrUserTask.dataAssociations.forEach(function (dataAssociation) {

                        /* assign id only if there is no id */
                        if (!dataAssociation.id && self.ids) {

                            var uuid = self.ids._next();
                            dataAssociation.id = uuid;
                        }
                    });
                }
            }
        });
    }

    if (definitions && isArray(definitions.diagrams) && definitions.diagrams[0]
        && definitions.diagrams[0].plane && isArray(definitions.diagrams[0].plane.planeElement)) {
        //Remove plane elements that don't have bpElements
        var planeElements = definitions.diagrams[0].plane.planeElement;
        planeElements.forEach(function (diElement, index) {
            //bpElement wasn't resolved (probably the semantic element doesnt exist) or semantic element was just
            // removed.
            if (!isObject(diElement.bpElement) || removedFlows[diElement.bpElement.id]) {
                if (cleanseOptions.rectify) {
                    planeElements.splice(index, 1);
                }

                //Diagnostic
                var semanticDesc = isObject(diElement.bpElement) ?
                'bpElement (' + diElement.bpElement.id + ')' :
                'bpElement invalid value (' + diElement.bpElement + ')';
                var operationMessage = 'Diagram element : ' + diElement.id +
                    ' is invalid. Semantic element: ' + semanticDesc + '.';
                diagnostics.push(
                    {operation: 'DI_ELEMENT_INVALID', contextObjectId: diElement.id, message: operationMessage})
            }
        });
    }

    if (diagnostics.length > 0) {
        return {
            severity: 'ERROR', message: diagnostics.map(function (d) {
                return d.message
            }).join('\n')
        };
    } else {
        return {severity: 'OK'}
    }
};

/**
 *  Recursively return all the containing flow elements.
 * @param container instance of 'FlowElementsContainer' of which containing flow elements need to be returned.
 * @returns {Array}
 */
function getAllFlowElements(container) {
    var result = [];
    if (container) {
        result = result.concat(container.flowElements);
        container.flowElements.forEach(function (flowElement) {
            if (flowElement.$instanceOf && flowElement.$instanceOf('bp:FlowElementsContainer')) {
                result = result.concat(getAllFlowElements(flowElement));
            }
        });
    }
    return result;
}

/**
 *  Removed the FlowElement 'element' from the 'container' passed recursively.
 * @param container container of type FlowElementsContainer
 * @param element FlowElement to be removed
 * @returns {Number} index of element which got removed. If element not found then returns -1.
 */
function removeFlowElement(container, element){
    if (container && element) {
        var index = Collections.remove(container.flowElements, element);
        if(index !== -1) {
            container.flowElements.forEach(function (flowElement) {
                if (flowElement.$instanceOf && flowElement.$instanceOf('bp:FlowElementsContainer')) {
                    index = removeFlowElement(flowElement, element);
                    if(index !== -1) {
                        return index;
                    }
                }
            });
        }
        return index;
    }
}
/**
 * Creates an instance of ABPM model from a JSON string.
 *
 * @param {object} definitions object of the BP model.
 * @param {string} [formatPrefix] format prefix string (for example '    ' will use 4 spaces to indent).
 * @returns {string} JSON representation of the model.
 */
BpModdle.prototype.toJson = function (definitions, formatPrefix) {
    return JSON.stringify(this._getSaveReadyClone(definitions), null, formatPrefix);
};

/**
 * Creates ready to save clone changing actual references to reference target id.
 *
 * @param definition [object] definition moddle object.
 * @param skipLogging [boolean] if set to truthy then the problem logging will be skipped (logged by default/)
 * @returns {*}
 */
BpModdle.prototype._getSaveReadyClone = function (definition, skipLogging) {

    var INTERNAL_PROP_NAME_PATTERN = /^\$\$.*$/;

    /**
     * Determines if property should be serialized. (Properties starting with '$$' will be excluded from serialization.)
     * @param {object} object The context object.
     * @param {string} propertyName The name of the property.
     * @returns {boolean} true if the property should be serialized.
     */
    function isSerializableProperty(object, propertyName) {
        return typeof propertyName === 'string' && !propertyName.match(INTERNAL_PROP_NAME_PATTERN);
    }

    /**
     * Returns property descriptor.
     * @param {object} object The context object.
     * @param {string} propertyName The name of the property.
     * @returns {object} property descriptor or undefined if the property is not a model property.
     */
    function getPropertyDescriptor(object, propertyName) {
        if (object && object.$instanceOf && object.$descriptor && object.$descriptor.propertiesByName) {
            return object.$descriptor.propertiesByName[propertyName];
        }
    }

    /**
     * Customizer is responsible for serializing references.
     *
     * <p>
     *  NOTE:
     * '$type' is a special non-model property that needs to be serialized to determine object's type during read.
     *  If property descriptor has 'isTransient' set to true then this property will be ignored.
     * </p>
     * @param value
     * @returns {*} if undefined is returned then exact clone will be made.
     */
    function customizer(value) {
        var clonedValue;

        //Outgoing flows will now be serialized in the model.
        if (value && value.$instanceOf) {
            // The value needs to be called recursively with this customizer as some descendant elements can
            // potentially have references to de-resolve (for example UserTask.dataAssociations[0]).
            clonedValue = {};
            Object.getOwnPropertyNames(value).forEach(function (pName) {
                /*
                * Sid CBPM-20853 Some references might be transient (for instance, bp:DataPath.dataItem
                * might refer to a $TEMP field and the temp field will not exist in the process but will
                * be created and associated dynamcially with the DataPath.dataItem.
                *
                * The problem with that is that IF that transient reference isn't set up whilst editing
                * (which it won't if you haven't viewed the calculation task for instance)
                * then when the model is saved again, the dataItem won't be set back t an ID string and
                * therefore we got from having DataPath.dataItem="$TEMP1" to DataPath.dataPath=undefined.
                *
                * To counter this, we now preserve some original reference id values as a "__Original_<ref property name>" property
                * in the resolveRefs() function. THEN when re-serializing here we can say 'if we find an '__Original_XXXX'
                * property then we can check whether the original property is present and has a value and if not
                * then write out the original property with this preserved reference value
                *
                * For now we'll just do this for all single instance refs (as not sure of the implications
                * for multi-instance at this point)
                */
                if (pName && pName.startsWith(BPMODDLE_ORIGINAL_REF_PREFIX)) {
                    var realRefPropertyName = pName.substring(BPMODDLE_ORIGINAL_REF_PREFIX.length);

                    // If the reference property hasn't been reset during this session then reinstate it from this __Original_<ref property Nname>
                    if (!value[realRefPropertyName]) {
                        // Sid CBPM-20853 handy debugging...
                        // console.log("bpModdle.save.customizer(): Reverting unresolved reference back original id for property '" +
                        //     realRefPropertyName + "'='" + value[pName] +
                        //     "' in object: " + JSON.stringify(value));

                        Object.defineProperty(clonedValue, realRefPropertyName, {
                            enumerable: true,
                            value: value[pName]
                        });
                    }

                } else if (isSerializableProperty(value, pName)) {
                    var pDescriptor = getPropertyDescriptor(value, pName);
                    if (pName === '$type' || (pDescriptor && !pDescriptor.isReference && !pDescriptor.isTransient)) {

                        if (value[pName] === undefined) {
                            /* Sid CBPM-20853 make it easier to track the actual property being complained about in warnings below. */
                            console.warn("Process model property '"+pName+"' is undefined");
                        }
                        clonedValue[pName] = cloneDeepWith(value[pName], customizer);

                    } else if (value[pName] && pDescriptor && pDescriptor.isReference && !pDescriptor.isTransient) {
                        // It is a reference and it must have a value.
                        if (pDescriptor.isMany) {
                            if (value[pName]) {
                                // Sid CBPM-20853 handy debugging...
                                // console.log("bpModdle.save.customizer(): Converting MANY reference back to id for property '" +
                                //     pName +
                                //     "' in object: " + JSON.stringify(clonedValue));

                                Object.defineProperty(clonedValue, pName, {
                                    enumerable: true,
                                    value: value[pName].map(function (referencedObject) {
                                        return referencedObject && referencedObject.id;
                                    })
                                });
                            }
                        } else {
                            // Sid CBPM-20853 handy debugging...
                            // console.log("bpModdle.save.customizer(): Converting reference back to id for property '" +
                            //     pName + "'=" + value[pName].id +
                            //     " in object: " + JSON.stringify(value));

                            Object.defineProperty(clonedValue, pName, {
                                enumerable: true,
                                value: value[pName].id
                            });
                        }
                    }
                }
            });
        }
        if (value === null) {
            clonedValue = null;
            if (!skipLogging) {
                console.warn('One of serialized objects has a "null" (property or an array has a "null" element).\n' +
                    'This will most likely cause a problem at runtime.');
            }
        }

        if (value === undefined) {
            clonedValue = null;
            if (!skipLogging) {
                console.error(
                    'One of serialized objects has a "undefined" property (or an array has a "undefined" element).\n' +
                    'Undefined will be changed to null. This will most likely cause a problem at runtime.');
            }
        }
        return clonedValue;
    }

    return cloneDeepWith(definition, customizer);
};

export default function (additionalPackages, options) {
    additionalPackages = additionalPackages || {};
    return new BpModdle(assign({}, packages, additionalPackages), options);
};
