'use strict';

import assign from 'lodash/assign';
import omit from 'lodash/omit';
import isString from 'lodash/isString';
import isNumber from 'lodash/isNumber';
import isArray from 'lodash/isArray';
import isFunction from 'lodash/isFunction';
import isPlainObject from 'lodash/isPlainObject';

import domify from 'min-dom/lib/domify';
import domQuery from 'min-dom/lib/query';
import domRemove from 'min-dom/lib/remove';

import BpModel from './bp-model';
import Diagram from 'diagram-js';
//DiagramLoader = require('./features/modeling/DiagramLoader');


import selectionModule from './features/selection';
import DrawModule from './draw';
import zoomScrollModule from 'diagram-js/lib/navigation/zoomscroll';
import moveCanvasModule from 'diagram-js/lib/navigation/movecanvas';
import spaceToolPreviewModule from 'diagram-js/lib/features/space-tool';
import lassoToolModule from 'diagram-js/lib/features/lasso-tool';
import commandModule from './features/command';
import ModelingModuleModule from './features/modeling';
import RulesModule from './features/rules';
import contextPadModule from './features/context-pad';
import keyboardModule from './features/keyboard';
import editorActionsModule from './features/editor-actions';
import annotationOverlaysModule from './features/annotations';
import AutoResizeModule from './features/auto-resize';
import ResizeModule from './features/resize';

import MoveModule from 'diagram-js/lib/features/move';
import BendPointsModule from 'diagram-js/lib/features/bendpoints';
import SnappingModule from './features/snapping';
import PalatteModule from './features/palette';
import OrderingModule from './features/ordering';


/*
 * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
 * So these modules are required to be added explicitly
 * */
import ConnectModule from "diagram-js/lib/features/connect";
import ConnectionPreviewModule from "diagram-js/lib/features/connection-preview";


function DtDiagram(options) {

    this.options = options = assign({}, DEFAULT_OPTIONS, options || {});

    var parent = options.container;

    // support jquery element
    // unwrap it if passed
    if (parent.get) {
        parent = parent.get(0);
    }

    // support selector
    if (isString(parent)) {
        parent = domQuery(parent);
    }

    var container = this.container = domify('<div class="process-diagram-container"></div>');
    parent.appendChild(container);

//    assign(container.style, {
//        width: ensureUnit(options.width),
//        height: ensureUnit(options.height),
//        position: options.position
//    });
}

var DEFAULT_OPTIONS = {
    container: 'body'
};

/**
 * Create diagram using moddle process model.
 *
 * @param {string} [jsonModel] JSON representation of the model (containing semantic and diagram parts).
 * @param {function (errors, warnings)} finishedCb Callback carrying potential errors or warnings.
 * @param {function(context)} [onChange] Callback to be called when a diagram change occurs.
 *        The 'context' object contains:
 *        - 'event' - on change event containing modified elements.
 *        - 'diagram' - diagram reference. (Use: diagram.getModelJson([format]) - to getserialized json.)
 * @param [that] object to be use as 'this' for onChange.
 * @param {object} [options] Additional options for diagram.
 * @param {boolean} [options.readOnly] if the diagram should be created in a read-only mode (false - default).
 * @param {function} [options.translate] translate function (string -> string).
 *
 */
DtDiagram.prototype.createDiagram = function (jsonModel, finishedCb, onChange, that, options) {

    if (this.diagram) {
        this.clear();
    }

    this.readOnly = options && options.readOnly;

    var processModdle = this._processModdle = BpModel();
    var definitions;

    if (isString(jsonModel) || isPlainObject(jsonModel)) {
        definitions = this._processModdle.fromJson(jsonModel, options);
    } else {
        definitions = this._processModdle.createInitialProcessModel();
    }
    this.model = definitions;

    var diagram = this.diagram = this._bootstrapDiagram(this.options);

    this._init(diagram);

    try {
        var DiagramLoader = diagram.get('diagramLoader');
        var errors = null;
        DiagramLoader.loadDiagram(definitions, function (err) {
            errors = err;
        });

        if (errors) {
            finishedCb(errors);

            //Fallback to create initial diagram. fallbackForInvalidModel is to ensure it doesn't go into infinite loop.
            if (!this.fallbackForInvalidModel) {
                this.fallbackForInvalidModel = true;
                this.createDiagram(undefined, finishedCb, onChange, that, options);
            }
        } else {
            //Installing onChange handler.
            var _self = this;
            if (isFunction(onChange)) {
                var changeListener = this.changeListener = function (event) {
                    onChange.call(that, {diagram: _self, event: event});
                };
                diagram.get('eventBus').on('elements.changed', changeListener);
            }
            finishedCb();
        }
    } catch (e) {
        finishedCb(e);
    }
};

/**
 * Returns true if diagram was created in a read only mode.
 *
 * @returns {Definitions} model.
 */
DtDiagram.prototype.isReadOnly = function () {
    return this.readOnly;
};

/**
 * Gets current process model.
 *
 * @returns {Definitions} model.
 */
DtDiagram.prototype.getModel = function () {
    return this.model;
};

/**
 * Gets current process meta-model/factory.
 *
 * @returns {BPModel} model.
 */
DtDiagram.prototype.getBpModdle = function () {
    return this._processModdle;
};

/**
 * Gets current process model serialized to JSON.
 *
 * @param {string|number} [space] Object that's used to insert white space into the output JSON string for readability
 *     purposes.
 * @returns {string} model serialized to JSON.
 */
DtDiagram.prototype.getModelJson = function (space) {
    return this._processModdle.toJson(this.getModel(), space);
};

DtDiagram.prototype._bootstrapDiagram = function (options) {

    var diagramModule = {
        dtDiagram: ['value', this],
        processModdle: ['value', this._processModdle]
    };

    var modules = [diagramModule].concat(this.getModules(), options.additionalModules || []);

    options = omit(options, 'additionalModules');

    /*
     CBPM-4353 To get the process editor to render on safari we have to set the canvas height to 100vh rather than
     100%. Unfortunately this causes rendering issues on Chrome. As a result we need to detect if Safari is being
     used and set the height accordingly, hencce the browser checks below.
     */
    // Opera 8.0+
    var isOpera = (!!window.opr && !!opr.addons) || !!window.opera || navigator.userAgent.indexOf(' OPR/') >= 0;
    // Chrome 1+
    var isChrome = !!window.chrome && !!window.chrome.webstore;
    // Safari 3 - 10
    var isSafari = Object.prototype.toString.call(window.HTMLElement).indexOf('Constructor') > 0 ||
        !isChrome && !isOpera && window.webkitAudioContext !== undefined;
    var height = isSafari ? '100vh' : '100%';
    // Setting the canvas container. The list of bootstrap modules and
    //adding default keyboard bindings (see: features/keyboard).

    options = assign(options, {
        canvas: {container: this.container, height: height},
        modules: modules,
        keyboard: {bindTo: document}
    });

    return new Diagram(options);
};

/**
 * Ensure the passed argument is a proper unit (defaulting to px)
 */
function ensureUnit(val) {
    return val + (isNumber(val) ? 'px' : '');
}

function initListeners(diagram, listeners) {
    var events = diagram.get('eventBus');

    listeners.forEach(function (l) {
        events.on(l.event, l.priority, l.handler, l.that);
    });
}


DtDiagram.prototype.get = function (name, strict) {

    if (!this.diagram) {
        throw new Error('no diagram loaded');
    }

    return this.diagram.get(name, strict);
};

DtDiagram.prototype.invoke = function (fn) {

    if (!this.diagram) {
        throw new Error('no diagram loaded');
    }

    return this.diagram.invoke(fn);
};

/**
 * Register an event listener on the DtDiagram
 *
 * @param {String} event
 * @param {Function} handler
 */
DtDiagram.prototype.on = function (event, priority, handler, that) {
    var diagram = this.diagram,
        listeners = this.__listeners || [];

    listeners.push({event: event, priority: priority, handler: handler, that: that});

    if (diagram) {
        diagram.get('eventBus').on(event, priority, handler, that);
    }
};


DtDiagram.prototype._init = function (diagram) {
    initListeners(diagram, this.__listeners || []);

    // Configure dragging to 'keepSelection' (by default selection is cleared and
    // restored which generates deselection and selection events).
    diagram.invoke(['dragging', function (dragging) {
        dragging.setOptions({keepSelection: true});
    }]);
    /*
    * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
    *
    * 1. Firing the attach event which takes care of binding
    *    the keyBoard events to the DOM in "process-diagram-js/node_modules/diagram-js/lib/features/keyboard/Keyboard.js"
    * */
    diagram.get('eventBus').fire('attach', {});
};

/**
 * Remove all drawn elements from the DtDiagram.
 *
 * After calling this method the DtDiagram can still
 * be reused for opening another diagram.D
 */
DtDiagram.prototype.clear = function () {
    var diagram = this.diagram;

    if (diagram) {
        if (this.changeListener) {
            diagram.get('eventBus').off('elements.changed', this.changeListener);
        }
        diagram.destroy();
    }
};

/**
 * Destroy the DtDiagram instance and remove all its remainders
 * from the document tree.
 */
DtDiagram.prototype.destroy = function () {
    // clear underlying diagram
    this.clear();

    // remove container
    domRemove(this.container);
};

/**
 * Gets semantic selection from the diagram.
 * @returns {Array} An array of selected semantic (moddle) elements.
 */
DtDiagram.prototype.getSemanticSelection = function () {
    return this.invoke(['selection', function (selectionService) {
        return selectionService.get().reduce(function (acc, djsElement) {
            var semantic = djsElement.businessObject || djsElement;
            if (semantic) {
                acc.push(semantic);
            }
            return acc;
        }, []);
    }]);
};

/**
 * Selects semantic elements on the diagram.
 *
 * @param elements {Array | ModdleElement | null} An array of semantic elements (or a single semantic element) to be
 *     selected on the diagram.
 * @param add {boolean} If the current selection should be expanded (true) or replaced (false).
 */
DtDiagram.prototype.setSemanticSelection = function (elements, add) {
    this.invoke(['selection', 'elementRegistry', function (selectionService, elementRegistry) {
        var semanticSelection = isArray(elements) ? elements : [elements];
        var djsElements = semanticSelection.reduce(function (acc, semanticElement) {
            if (semanticElement) {
                var djsElement = elementRegistry.get(semanticElement.id);
                if (djsElement) {
                    acc.push(djsElement);
                }
            }
            return acc;
        }, []);
        selectionService.select(djsElements, add);
    }]);
};

/**
 * Find and return the DJS object (the Diagram visual object) for the given semantic model object.
 *
 * @param semanticModelElement
 */
DtDiagram.prototype.getDiagramObject = function (semanticModelElement) {
    return this.invoke(['elementRegistry', function (elementRegistry) {
        return elementRegistry.get(semanticModelElement.id);
    }]);
};

// modules the DtDiagram is composed of
DtDiagram.prototype.getModules = function () {
    var result = [
        selectionModule,
        DrawModule,
        zoomScrollModule,
        moveCanvasModule,
        spaceToolPreviewModule,
        lassoToolModule,
        commandModule,
        ModelingModuleModule,
        RulesModule,
        contextPadModule,
        keyboardModule,
        editorActionsModule,
        annotationOverlaysModule,
        ConnectModule,
        ConnectionPreviewModule
    ];

    if (! this.readOnly) {
        result.push(
            MoveModule,
            BendPointsModule,
            SnappingModule,
            PalatteModule,
            OrderingModule,
            ResizeModule,
            AutoResizeModule
        );
    }

    return result;
};


export default DtDiagram;
