'use strict';

import assign from 'lodash/assign';

import {instanceOf} from '../modeling/ModelUtil';
import TextUtil from 'diagram-js/lib/util/Text';

export var DEFAULT_LABEL_SIZE = {
    width: 110,
    height: 20
};

var DEFAULT_CONDITIONAL_FLOW_SIZE = {
    width: 26,
    height: 26
};

var textUtil = new TextUtil({
    style: {
        fontFamily: '"Source Sans Pro"'
    },
    size: {width: 1000}
});

/**
 * Returns true if the given semantic has an external label
 */
export function hasExternalLabel(semantic) {
    return instanceOf(semantic, ['bp:Event', 'bp:Gateway', 'bp:SequenceFlow']);
};

/**
 * Returns true if the given semantic has an external label
 */
export function getLabelProperty(semantic) {
    if (instanceOf(semantic, ['bp:Event', 'bp:Gateway', 'bp:SequenceFlow'])) {
        return ['name', 'flowMarker'];
    }
};


/**
 * Get the middle of a number of waypoints
 *
 * @param  {Array<Point>} waypoints
 * @return {Point} the mid point
 */
export function getWaypointsMid(waypoints) {

    var mid = waypoints.length / 2 - 1;

    var first = waypoints[Math.floor(mid)];
    var second = waypoints[Math.ceil(mid + 0.01)];

    return {
        x: first.x + (second.x - first.x) / 2,
        y: first.y + (second.y - first.y) / 2
    };
}


/**
 * Get the delta of the two connection mid points.
 *
 * @param  {Array<Point>} startWaypoints,
 * @param  {Array<Point>} endWaypoints,
 * @return {Point} the mid points delta.
 */
export function getMidpointsDelta(startWaypoints, endWaypoints) {

    var startMid = getWaypointsMid(startWaypoints);
    var endMid = getWaypointsMid(endWaypoints);

    return {
        x: endMid.x - startMid.x,
        y: endMid.y - startMid.y
    };
}


export function getExternalLabelMid(element) {

    if (element.waypoints) {
        return getWaypointsMid(element.waypoints);
    } else {
        return {
            x: element.x + element.width / 2,
            y: element.y + element.height + DEFAULT_LABEL_SIZE.height / 2
        };
    }
}



/**
 * Returns the bounds of an elements label, parsed from the elements DI or
 * generated from its bounds.
 *
 * @param {BpmnElement} semantic
 * @param {djs.model.Base} element
 * @param reset resets if set to 'true' then the bounds will be reset.
 */
export function getExternalLabelBounds(semantic, element, reset) {

    var mid,
        size,
        bounds,
        diElement = semantic.diElement,
        label = diElement.label;
    if (label && label.bounds && !reset) {
        bounds = label.bounds;
        size = {
            width: Math.max(DEFAULT_LABEL_SIZE.width, bounds.width),
            height: bounds.height
        };

        if(instanceOf(semantic, 'bp:SequenceFlow')) {
            if (instanceOf(semantic.sourceRef, 'bp:ExclusiveGateway')) {
                var fullText = (semantic.flowMarker ? semantic.flowMarker : '').concat(semantic.name ? semantic.name : '');
                var dim = textUtil.getDimensions(fullText, {
                    box: {},
                    align: 'center',
                    style: {},
                    fitBox: false
                });
                var widthDelta = isDefaultFlow(semantic) ? 46 : 0;
                size.width = Math.max(DEFAULT_CONDITIONAL_FLOW_SIZE.width, dim.width + (semantic.name ?  21 : 12) + widthDelta);
                size.height = Math.max(DEFAULT_CONDITIONAL_FLOW_SIZE.height, bounds.height);
            }else{
                if(semantic.name) {
                    var dim = textUtil.getDimensions(semantic.name, {
                        box: {},
                        align: 'center',
                        style: {},
                        fitBox: false
                    });
                    size.width = Math.max(DEFAULT_CONDITIONAL_FLOW_SIZE.width, dim.width + 10);
                    size.height = Math.max(DEFAULT_CONDITIONAL_FLOW_SIZE.height, bounds.height);
                }
            }
        }

        mid = {
            x: bounds.x + bounds.width / 2,
            y: bounds.y + bounds.height / 2
        };
    } else {
        size = DEFAULT_LABEL_SIZE;
        mid = getExternalLabelMid(element);
        if(instanceOf(semantic, 'bp:SequenceFlow') && element.type && element.type === 'label') {
            if(instanceOf(semantic.sourceRef, 'bp:ExclusiveGateway')){
                // move to label on the sequence flow
                mid.y = mid.y - size.height;
            }
        }
    }

    return assign({
        x: mid.x - size.width / 2,
        y: mid.y - size.height / 2
    }, size);
};

/**
 *  Returns 'true' if current flow is default flow, otherwise returns 'false'.
 * Implementation is simillar to ProcessDiagramRules.isDefaultFlow.
 * @param element
 * @returns {*}
 */
function isDefaultFlow(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:SequenceFlow')) {
        var source = bo.sourceRef;
        return instanceOf(source, 'bp:ExclusiveGateway') && bo === source.default;
    }
    return false;
}