'use strict';

import DeleteShapeHandler from 'diagram-js/lib/features/modeling/cmd/DeleteShapeHandler';
import inherits from 'inherits';

import Collections from 'diagram-js/lib/util/Collections';
import {instanceOf} from '../ModelUtil';
import {getBusinessObject} from '../ModelUtil';
/**
 * A handler that implements reversible deletion of activity tasks. Delegates
 * to the standard DeleteShapeHandler for all other shapes.
 */
function DeleteProcessShapeHandler(canvas, modeling) {
    // Super CONSTRUCTOR
    DeleteShapeHandler.call(this, canvas, modeling);

    this._modeling = modeling;
}

DeleteProcessShapeHandler.$inject = [ 'canvas', 'modeling' ];

inherits(DeleteProcessShapeHandler, DeleteShapeHandler);


/**
 * Overrides DeleteShapeHandler. If the given shape is a FlowNode and
 * it has one of both incoming and outgoing connections, this will move the
 * incoming connection to point to the outgoing connection's target.
 * It will then call the DeleteShapeHandler.
 */
DeleteProcessShapeHandler.prototype.preExecute = function(context) {
    // move the incoming to the proceeding shape
    moveConnection(this._modeling, context.shape);

    // call the default implementation to delete the shape
    if (DeleteShapeHandler.prototype.preExecute) {
        DeleteShapeHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Modifies the incoming connection of the given shape to point to the
 * target of the shape's outgoing connection.
 *
 * @param aModeling the modeling command service.
 * @param aShape the shape whose connections are to be modified.
 */
function moveConnection(aModeling, aShape) {
    // test for sub-class of FlowNode
    var isFlowNode = instanceOf(getBusinessObject(aShape), 'bp:FlowNode');

    // if the shape has one of both incoming and outgoing connections
    if ((isFlowNode) &&
        (aShape.incoming) && (aShape.incoming.length == 1) &&
        (aShape.outgoing) && (aShape.outgoing.length == 1)) {
        var outgoing = aShape.outgoing[0];
        var incoming = aShape.incoming[0];

        //Reconnect only if it doesn't lead to a self loop.
        if (outgoing.target !== incoming.source) {
            // perform move - and emit "connection.reconnectEnd" command
            // this will adjust the business object references of the connection
            aModeling.reconnectEnd(incoming, outgoing.target, outgoing.waypoints[outgoing.waypoints.length - 1]);

            // position the line-ends of the adjusted connection
            aModeling.layoutConnection(incoming);
        }
    }
}

export default DeleteProcessShapeHandler;