import { some } from 'min-dash';
import { isString } from 'min-dash';
/**
 * @typedef {import('../../../model/Types').Shape} Shape
 *
 */



// here order of LANE_PARENTS matters as first match is considered by getLanesRoot function below.
var LANE_PARENTS = [
    'bp:SubProcess',
    // 'bp:Process', // TODO :- Can be removed as in TCLA Lanes are added to SubProcess & not directly to Process.
];

export var LANE_INDENTATION = 30;  // IN DT PFC has 30px top padding for name of the PFC.








/**
 * Return the parent shape of the given lane.
 *
 * @param {Shape} shape
 *
 * @return {Shape}
 */
export function getLanesRoot(shape) {
    return getParent(shape, LANE_PARENTS) || shape;
}






// TODO :- All below common functions can be moved to 'process-diagram-js\src\util\ModelUtil' After merge from trunk.

/**
 * Return the parent of the element with any of the given types.
 *
 * @param {Element} element
 * @param {string|string[]} anyType
 *
 * @return {Element|null}
 */
export function getParent(element, anyType) {

    if (isString(anyType)) {
        anyType = [ anyType ];
    }

    while ((element = element)) {
        if (isAny(element, anyType) && getBusinessObject(element).getSubProcessType() === 'ParallelLaneContainer') {
            return element;
        }
    }

    return null;
}


/**
 * Is an element of the given BPMN type?
 *
 * @param  {Element|ModdleElement} element
 * @param  {string} type
 *
 * @return {boolean}
 */
export function is(element, type) {
    var bo = getBusinessObject(element);

    return bo && (typeof bo.$instanceOf === 'function') && bo.$instanceOf(type);
}


/**
 * Return true if element has any of the given types.
 *
 * @param {Element|ModdleElement} element
 * @param {string[]} types
 *
 * @return {boolean}
 */
export function isAny(element, types) {
    return some(types, function(t) {
        return is(element, t);
    });
}

/**
 * Return the business object for a given element.
 *
 * @param {Element|ModdleElement} element
 *
 * @return {ModdleElement}
 */
export function getBusinessObject(element) {
    return (element && element.businessObject) || element;
}

/**
 * Returns the minimum dimensions for a lane, i.e., the min-width and min-height that it can be resized to
 *
 * @returns {{width: number, height: number}}
 */
export function getMinDimensionsForLane() {
    return {
        width: 240,
        height: 180
    };
}

/**
 * Returns the default padding to be maintained in a lane
 *
 * @returns {top: number, left: number, bottom: number, right: number}
 */
export function getDefaultPaddingForLane() {
    return { top: 30, bottom: 30, left: 50, right: 50 };
}

/**
 * Returns the default padding to be maintained in a lane container
 *
 * @returns {top: number, left: number, bottom: number, right: number}
 */
export function getDefaultPaddingForLaneContainer() {
    return { top: 30, bottom: 0, left: 0, right: 0 };
}

/**
 * Determines if there is a difference in the passed bounds of the shape, i.e., have the bounds updated
 *
 * @param shape
 * @param newBounds
 * @returns {boolean}
 */
export function boundsChanged(shape, newBounds) {
    return shape.x !== newBounds.x ||
        shape.y !== newBounds.y ||
        shape.width !== newBounds.width ||
        shape.height !== newBounds.height;
}