'use strict';

import SpaceToolHandler from 'diagram-js/lib/features/modeling/cmd/SpaceToolHandler';
import MoveHelper from 'diagram-js/lib/features/modeling/cmd/helper/MoveHelper';
import inherits from 'inherits';
import forEach from 'lodash/forEach';
import {resizeBounds} from "diagram-js/lib/features/space-tool/SpaceUtil";

function DtSpaceToolHandler(modeling, processDiagramRules) {
    /* Super CONSTRUCTOR */
    SpaceToolHandler.call(this, modeling);
    this._processDiagramRules = processDiagramRules;

    this._helper = new MoveHelper(modeling);
}


DtSpaceToolHandler.$inject = ['modeling', 'processDiagramRules'];

inherits(DtSpaceToolHandler, SpaceToolHandler);



/**
 * Overrides SpaceToolHandler of diagram js.
 *
 * @param context
 */
DtSpaceToolHandler.prototype.preExecute = function (context) {
    var processDiagramRules = this._processDiagramRules;
    var elements = context.movingShapes;
    var movingShapes = [];

    forEach(elements, function (element) {
        if (!processDiagramRules.isContainedInInitialTaskSubProcess(element)) {
            movingShapes.push(element);
        }
    });

    /**
     * Chaitanya CBPM-22665 :- Adoption of Diagram.js 7.3.0
     *
     * Added Helper method getClosure , to generate list of movableAllElements
     * considering the children's of movingShapes caused due to below commit.
     *
     * "fix(space-tool): add/remove space without side effects" over github.
     *
     * https://github.com/bpmn-io/diagram-js/commit/4a02597dd613e026b564cc88300a934df5f833c1
     */
    var moveClosure = this._helper.getClosure(movingShapes);
    var movableAllElements = [];
    Object.keys(moveClosure.allShapes).forEach(function(item){
        movableAllElements.push(moveClosure.allShapes[item])
    });


    // find labels that are not part of
    // moveClosure.enclosedElements yet and add them inside movableAllElements
    Object.keys(moveClosure.enclosedElements).forEach(function(element) {
        forEach(moveClosure.enclosedElements[element].labels, function(label) {
            if (!moveClosure.enclosedElements[label.id]) {
                movableAllElements.push(label)
            }
        });
    });

    context.movingShapes = movableAllElements.length > 0 ?  movableAllElements : movingShapes;

    /* call the default implementation of preExecute */
    if (SpaceToolHandler.prototype.preExecute) {

        SpaceToolHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Overrides SpaceToolHandler of diagram js.
 *
 * @param context
 */
DtSpaceToolHandler.prototype.postExecute = function (context) {

    if (SpaceToolHandler.prototype.postExecute) {

        SpaceToolHandler.prototype.postExecute.call(this, context);
    }
};

/**
 * Overrides the resizeShapes method of SpaceToolHandler of diagram js.
 *
 * @param context
 */
DtSpaceToolHandler.prototype.resizeShapes = function(shapes, delta, direction) {
    var self = this;

    forEach(shapes, function(shape) {
        var newBounds = resizeBounds(shape, direction, delta);

        // CBPM-26070 When a SpaceToolHandler initializes resize of multiple shapes,
        // pass the reference of entire stack(all shapes to be resized)
        self._modeling.resizeShape(shape, newBounds, null, {
            attachSupport: false,
            autoResize: false,
            layout: false,
            resizeStack: shapes
        });
    });
};

export default DtSpaceToolHandler;
