'use strict';

import ReconnectConnectionHandler from 'diagram-js/lib/features/modeling/cmd/ReconnectConnectionHandler';
import inherits from 'inherits';

import {getBusinessObject} from '../ModelUtil';
/**
 * * A handler which handles connection reconnect sequence. This also takes care of setting the correct (ie. next available in the sequence )
 * 'FlowMarker' attribute of the connection
 */
function ReconnectSequenceFlowHandler(modeling) {
    // Super CONSTRUCTOR
    ReconnectConnectionHandler.call(this);
    this._modeling = modeling;
}

ReconnectSequenceFlowHandler.$inject = ['modeling'];

inherits(ReconnectSequenceFlowHandler, ReconnectConnectionHandler);



ReconnectSequenceFlowHandler.prototype.execute = function(context) {
    var connection = context.connection;

    // call the default implementation
    if (ReconnectConnectionHandler.prototype.execute) {
        return  ReconnectConnectionHandler.prototype.execute.call(this, context);
    }
    return connection;
};

/**
 *  Update flow marker value.
 * @param context
 */
ReconnectSequenceFlowHandler.prototype.postExecute = function(context) {
    var flowMarkerUpdateCmd = getFlowMarkerUpdateCommand(context.connection, context.flowMarker, this._modeling);
    this._modeling.runProcessModelCommand([flowMarkerUpdateCmd]);
};

ReconnectSequenceFlowHandler.prototype.revert = function(context) {
    var connection = context.connection;

    // call the default implementation to delete the shape
    if (ReconnectConnectionHandler.prototype.revert) {
        connection = ReconnectConnectionHandler.prototype.revert.call(this, context);
    }

    return connection;

};

/**
 * Returns command to update the flow marker.
 * @param connection
 * @param flowMarker
 * @param modeling
 * @returns {{type, mainAffectedElement, diagramScope, element, attribute, value, oldValue, execute, undo}}
 */
function getFlowMarkerUpdateCommand(connection, flowMarker, modeling) {
    var connectionBo = getBusinessObject(connection);
    return modeling.setCommand(connectionBo, connection, connectionBo, 'flowMarker', flowMarker);

}

export default ReconnectSequenceFlowHandler;