'use strict';

import inherits from 'inherits';
import ContextPad from 'diagram-js/lib/features/context-pad/ContextPad';
import forEach from 'lodash/forEach';
import isFunction from 'lodash/isFunction';
import isArray from 'lodash/isArray';

import domDelegate from 'min-dom/lib/delegate';
import domEvent from 'min-dom/lib/event';
import domAttr from 'min-dom/lib/attr';
import domQuery from 'min-dom/lib/query';
import domClasses from 'min-dom/lib/classes';
import domify from 'min-dom/lib/domify';

var entrySelector = '.entry';
/**
 *  Inherits the context pad to provide additional functions required to show the context pad on the different sides of the Shape.
 *
 *   By default, context pad is getting rendered on the right side of the shape. In 'diagram-js/lib/features/context-pad/ContextPad'
 *   there are no ways to specify the location of the context pad. Now using updated 'DtContextPad', ContextPadProviders can specify
 *   on which side of the shape context pad should be shown. ContextPadProvider need to add 'getContextPadSide' method and return the
 *   case-sensitive string as 'left','right', 'bottom' to specify the sides. By default (in case of no method provided), side will be taken as 'right'.
 *   Currently DT only supports left, right and bottom side.
 */
function DtContextPad(eventBus, overlays) {
    // Super CONSTRUCTOR
    ContextPad.call(this, {}, eventBus, overlays);
    this._eventBus = eventBus;
    this._combinedEntries = {};
    this._overlayIds = [];
    this._contextPadInfo = [];
    this._currentElement;
}

DtContextPad.$inject = [ 'eventBus', 'overlays' ];

inherits(DtContextPad, ContextPad);


/**
 * Overridden the 'trigger' of 'diagram-js/lib/features/context-pad/ContextPad'
 * Trigger an action available on the opened context pad.
 * All the implementation of the method is same as 'diagram-js/lib/features/context-pad/ContextPad'
 * but just initialization of 'element' and 'entries' are different.
 *
 * @param  {String} action
 * @param  {Event} event
 * @param  {Boolean} [autoActivate=false]
 */
DtContextPad.prototype.trigger = function(action, event, autoActivate) {

    var element = this._currentElement,
        entries = this._combinedEntries,
        entry,
        handler,
        originalEvent,
        button = event.delegateTarget || event.target;

    if (!button) {
        return event.preventDefault();
    }

    entry = entries[domAttr(button, 'data-action')];
    handler = entry.action;

    originalEvent = event.originalEvent || event;

    // simple action (via callback function)
    if (isFunction(handler)) {
        if (action === 'click') {
            return handler(originalEvent, element, autoActivate);
        }
    } else {
        if (handler[action]) {
            return handler[action](originalEvent, element, autoActivate);
        }
    }

    // silence other actions
    event.preventDefault();
};

/**
 * Overridden the '_updateAndOpen' of 'diagram-js/lib/features/context-pad/ContextPad'
 *
 * This method creates the 'pad' DOM element by reading contextPad providers.
 *
 *@param {djs.element.Base} element
 *
 */
DtContextPad.prototype._updateAndOpen = function (element) {

    var self = this;
    var padEntries = this._getPadEntries(element);

    padEntries.forEach(function (padEntry) {
        var entries = padEntry.entries;
        var pad = padEntry.pad;
        var html = pad.html;
        forEach(entries, function (entry, id) {
            var grouping = entry.group || 'default',
                control = domify(entry.html || '<div class="entry" draggable="true"></div>'),
                container;

            domAttr(control, 'data-action', id);

            container = domQuery('[data-group=' + grouping + ']', html);
            if (!container) {
                container = domify('<div class="group" data-group="' + grouping + '"></div>');
                html.appendChild(container);
            }

            container.appendChild(control);

            if (entry.className) {
                addClasses(control, entry.className);
            }

            if (entry.title) {
                domAttr(control, 'title', entry.title);
            }

            if (entry.imageUrl) {
                control.appendChild(domify('<img src="' + entry.imageUrl + '">'));
            }
        });
        domClasses(html).add('open');


        var current = {
            element: element,
            pad: pad,
            entries: entries,
            location : padEntry.location
        };
        self._contextPadInfo.push(current);
        self._eventBus.fire('contextPad.open', {current: current});
    });

    this._currentElement = element;
};

/**
 * Returns the context pad entries for a given element
 * Return result will contain object of the form
 * {pad, entries, side}
 * @param {djs.element.Base} element
 *
 * @return  list of entries
 */
DtContextPad.prototype._getPadEntries = function(element) {
    var padEntries = [];
    var self = this;
    var allEntries = {};
    // loop through all providers and their entries.
    // group entries by id so that overriding an entry is possible
    forEach(this._getProviders(), function(provider) {
        var entries = {};
        var side = 'right';
        if(isFunction(provider.getContextPadSide)) {
            side = provider.getContextPadSide(element);
        }
        if(!allEntries[side]){
            allEntries[side] = {};
        }

        var e = provider.getContextPadEntries(element);

        forEach(e, function(entry, id) {
            allEntries[side][id] = entry;
            self._combinedEntries[id] = entry;
        });

    });

    forEach(allEntries, function (entries, side) {
        var pad = self.getPad(element, side, Object.keys(entries).length);
        var padEntry = {pad : pad, entries : entries, side : side};
        padEntries.push(padEntry);
    });

    return padEntries;
};

/**
 * Overridden the 'getPad' of 'diagram-js/lib/features/context-pad/ContextPad'.
 * @param element
 * @param side
 * @param entriesCount the total number of entries in the context pad
 * @returns {*}
 */
DtContextPad.prototype.getPad = function(element, side, entriesCount) {
    if (this.isOpen(element)) {
        var info = this._contextPadInfo.find(function (contextPadInfo) {
            if(contextPadInfo.element === element){
                return !side ? true : side === contextPadInfo.side
            }
        });

        if(info){
            return info.pad;
        }
    }

    var self = this;

    var overlays = this._overlays;
    var overlayClass = !!side ? 'djs-context-pad-' + side : '';

    var html = domify('<div class="djs-context-pad ' + overlayClass + '"></div>');
    domDelegate.bind(html, entrySelector, 'click', function(event) {
        self.trigger('click', event);
    });

    domDelegate.bind(html, entrySelector, 'dragstart', function(event) {
        self.trigger('dragstart', event);
    });

    // stop propagation of mouse events
    domEvent.bind(html, 'mousedown', function(event) {
        event.stopPropagation();
    });

    var position = {};
    if(side === 'left'){
        position= { left : -30, top: -6}
    } else if (side === 'bottom') {
        // CBPM-22492 Show bottom context pad in the right bottom corner
        // As the number of entries very depending on task, the width of pad itself can change
        // Determine using entriesCount*25, i.e, entriesCount * width of gadget
        position = { right: (entriesCount * 25) - 9, bottom :  -9 }
    }else{
        position =  { right: -9, top: -6}
    }
    var overlayId = overlays.add(element, 'context-pad', {
        position: position,
        html: html
    });

    self._overlayIds.push(overlayId);
    var pad = overlays.get(overlayId);

    this._eventBus.fire('contextPad.create', { element: element, pad: pad });

    return pad;
};

/**
 * Overridden the 'close' of 'diagram-js/lib/features/context-pad/ContextPad'.
 * Close the context pad
 */
DtContextPad.prototype.close = function() {
    var self = this;
    if (!this.isOpen()) {
        return;
    }

    this._overlayIds.forEach(function (overlayId) {
        self._overlays.remove(overlayId);
    });

    this._contextPadInfo.forEach(function (contextPadInfo) {
        self._eventBus.fire('contextPad.close', { current: contextPadInfo });
    });
    this._contextPadInfo = [];
    this._currentElement = null;
};

/**
 * Check if pad is open. If element is given, will check
 * if pad is opened with given element.
 *
 * @param {Element} element
 * @return {Boolean}
 */
DtContextPad.prototype.isOpen = function(element) {
    return !!this._currentElement && (!element ? true : this._currentElement === element);
};


////////// helpers /////////////////////////////

function addClasses(element, classNames) {

    var classes = domClasses(element);

    var actualClassNames = isArray(classNames) ? classNames : classNames.split(/\s+/g);
    actualClassNames.forEach(function(cls) {
        classes.add(cls);
    });
}

export default DtContextPad;