'use strict';

import assign from 'lodash/assign';
import {getDiElementContainingPlaneElement, instanceOf} from './ModelUtil';
import {getBusinessObject} from './ModelUtil';
import inherits from 'inherits';
import {remove} from 'diagram-js/lib/util/Collections';

import * as Model from 'diagram-js/lib/model';


import CommandInterceptor from 'diagram-js/lib/command/CommandInterceptor';
import * as Collections from 'diagram-js/lib/util/Collections';


/**
 * Listens to the command stack events and synchronizes moddle model when diagram is updated.
 */
function ModelSynchronizer(eventBus, elementFactory, connectionDocking, processModdle) {
    CommandInterceptor.call(this, eventBus);
    var _self = this;

    // crop connection ends during create/update
    function cropConnection(e) {
        var context = e.context,
            connection;

        if (!context.cropped) {
            connection = context.connection;
            connection.waypoints = connectionDocking.getCroppedWaypoints(connection);
            context.cropped = true;
        }
    }

    this.executed([
        'connection.layout',
        'connection.create',
        'connection.reconnectEnd',
        'connection.reconnectStart'
    ], cropConnection);

    this.reverted(['connection.layout'], function (e) {
        delete e.context.cropped;
    });
    //////////////////////////////////////////////

    this.register(['executed', 'reverted'], ['shape.create', 'shape.move', 'shape.resize'], boundsChanged);
    this.register(['executed'], ['shape.create', 'shape.delete', 'connection.create', 'connection.delete'], setParent);
    this.register(['reverted'], ['shape.create', 'shape.delete', 'connection.create', 'connection.delete'],
        setParentReverted);

    // CBPM-26066 As part of moving to/from a parallel flow lane,
    // we need to explicitly update the parent(semantic reference) of the shape and connection
    this.register(['executed'], ['shape.move', 'connection.move'], setNewParent);

    //Handlers to deal with bp:ExclusiveGateway conditions and default.

    /*
    * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
    *
    * 1. Registered event 'connection.reconnect' for reconnectStartExecuted, reconnectStartReverted, connectionChanged Handlers
    *
    * */
    this.register(['executed'], ['connection.reconnectStart',  'connection.reconnect'], reconnectStartExecuted);
    this.register(['reverted'], ['connection.reconnectStart',  'connection.reconnect'], reconnectStartReverted);

    this.register(['executed', 'reverted'],
        ['connection.create', 'connection.move', 'connection.delete',
         'connection.reconnectEnd', 'connection.reconnectStart', 'connection.reconnect'],
        connectionChanged);


    this.register(['reverted', 'executed'], ['connection.layout', 'connection.updateWaypoints'],
        connectionWaypointsChanged);


    function connectionChanged(event) {
        var connection = event.context.connection;
        var connectionBo = getBusinessObject(connection);
        var newSourceBo = getBusinessObject(connection.source);
        var newTargetBo = getBusinessObject(connection.target);
        var isSequenceFlow = instanceOf(connectionBo, 'bp:SequenceFlow');

        if (connectionBo.sourceRef !== newSourceBo) {
            if (isSequenceFlow) {
                remove(connectionBo.sourceRef && connectionBo.sourceRef.get('outgoing'), connectionBo);

                if (newSourceBo && newSourceBo.get('outgoing')) {
                    newSourceBo.get('outgoing').push(connectionBo);
                }
            }

            connectionBo.sourceRef = newSourceBo;
        }

        if (connectionBo.targetRef !== newTargetBo) {
            if (isSequenceFlow) {
                remove(connectionBo.targetRef && connectionBo.targetRef.get('incoming'), connectionBo);

                if (newTargetBo && newTargetBo.get('incoming')) {
                    newTargetBo.get('incoming').push(connectionBo);
                }
            }

            connectionBo.targetRef = newTargetBo;
        }

        //Update waypoints
        if (connection && connectionBo) {
            connectionBo.diElement.waypoint = elementFactory.createDiWaypoints(connection.waypoints);
        }
    }

    function connectionWaypointsChanged(event) {
        var connection = event.context.connection;
        if (connection) {
            var connectionBo = getBusinessObject(connection);
            if (connectionBo) {
                connectionBo.diElement.waypoint = elementFactory.createDiWaypoints(connection.waypoints);
            }
        }
    }

    /**
     * Handling re-connection of connection start. Additional model changed need to be performed do deal with
     * ExclusiveGateway conditions and default.
     *
     * @param event
     */
    function reconnectStartExecuted(event) {
        var context = event.context;
        var connection = context.connection;
        if (connection) {
            var connectionBo = getBusinessObject(connection);
            var newSourceBo = getBusinessObject(connection.source);
            var oldSourceBo = connectionBo.sourceRef;
            if (instanceOf(connectionBo, 'bp:SequenceFlow') && oldSourceBo !== newSourceBo &&
                instanceOf(oldSourceBo, 'bp:ExclusiveGateway')) {
                // Save conditionExpression for the undo and clear it (if condition is set).
                if (connectionBo.conditionExpression) {
                    context.conditionExpression = connectionBo.conditionExpression;
                    delete connectionBo.conditionExpression;
                }
                // If the default connection changes it's source then save default in the context and clear default on
                // the gateway.
                if (oldSourceBo.default === connectionBo) {
                    context.isDefault = true;
                    delete oldSourceBo.default;
                }
            }
        }
    }

    /**
     * Handling revert of re-connection of connection start. Additional model changed need to be performed do deal with
     * ExclusiveGateway conditions and default.
     *
     * @param event
     */
    function reconnectStartReverted(event) {
        var context = event.context;
        var connection = context.connection;
        if (connection) {
            var connectionBo = getBusinessObject(connection);
            var newSourceBo = getBusinessObject(connection.source);
            var oldSourceBo = connectionBo.sourceRef;
            if (instanceOf(connectionBo, 'bp:SequenceFlow') && oldSourceBo !== newSourceBo &&
                instanceOf(newSourceBo, 'bp:ExclusiveGateway')) {
                // Restore saved condition expression (if it's in the undo context).
                if (context.conditionExpression) {
                    connectionBo.conditionExpression = context.conditionExpression;
                }
                // Restore default.
                if (context.isDefault) {
                    newSourceBo.default = connectionBo;
                }
            }
        }
    }

    /**
     * Check if the event context contains a specific type of model object ('shape' | 'connection')
     *
     * @param type {'shape'|'connection'} type of element.
     * @param {Event} event with context.
     * @returns {*|boolean} if event is for a specific type of event.
     */
    function isModelEventFor(type, event) {
        if (event.context && event.context[type]) {
            var element = event.context[type],
                businessObject = (element && element.businessObject) || element;
            return instanceOf(businessObject, 'bp:BaseElement');
        }
        return false;
    }

    function boundsChanged(event) {
        if (!isModelEventFor('shape', event)) {
            return;
        }
        var shape = event.context.shape;
        var diElement = shape.businessObject.diElement;
        var bounds = (shape instanceof Model.Label) ? getDiLabel(diElement).bounds : diElement.bounds;
        assign(bounds, {
            x: shape.x,
            y: shape.y,
            width: shape.width,
            height: shape.height
        });
    }


    function setParent(event) {
        var element = event.context.shape || event.context.connection,
            newParent = element.parent,
            oldParent = event.context.parent;
        changeParent(element, newParent);
    }

    function setNewParent(event) {
        var element = event.context.shape || event.context.connection,
            newParent = event.context.newParent;

        changeParent(element, newParent);
    }

    function setParentReverted(event) {
        var element, newParent, oldParent, elementBo;
        element = event.context.shape || event.context.connection;
        if (event.context.shape) {
            newParent = event.context.oldParent;
            oldParent = event.context.parent;
        }

        /*
         * CBPM-4350: Connections don't hold old parent for revert events in event.context.oldParent like shapes.
         */
        else if (event.context.connection) {
            /*CBPM-5508: Problem with undo of connection create.*/
            if (event.type === 'commandStack.connection.create.reverted') {
                newParent = event.context.oldParent;
                oldParent = event.context.parent;
            } else {
                newParent = event.context.parent;
                oldParent = event.context.oldParent;
            }
        } else {
            newParent = event.context.oldParent;
            oldParent = event.context.parent;
        }
        changeParent(element, newParent, oldParent);
    }
    
    function changeParent(element, newParent) {
        if (element instanceof Model.Label) {
            return;
        }
        var businessObj = element.businessObject;
        var newParentBusinessObj = newParent && newParent.businessObject;
        var currentParentBO = businessObj.$parent;
        if (businessObj.$parent !== newParentBusinessObj) {
            if (instanceOf(businessObj, ['bp:FlowNode', 'bp:SequenceFlow'])) {
                //Remove from parent
                if (instanceOf(currentParentBO, ['bp:FlowElementsContainer'])) {
                    //remove from semantic model
                    var removed = Collections.remove(currentParentBO.flowElements, businessObj);
                    if (removed != -1) {
                        businessObj.$parent = null;

                        //remove from diagram model.
                        var newParentBusinessObjectsDiElement = getDiElementContainingPlaneElement(currentParentBO);
                        Collections.remove(newParentBusinessObjectsDiElement.planeElement, businessObj.diElement);
                        businessObj.diElement.$parent = null;
                    }
                }
                //Add to the new parent.
                if (instanceOf(newParentBusinessObj, ['bp:FlowElementsContainer'])) {
                    //Add to semantic model
                    if(newParentBusinessObj.flowElements) {
                        newParentBusinessObj.flowElements.push(businessObj);
                    }else{
                        newParentBusinessObj.set('flowElements', [businessObj]);
                    }
                    businessObj.$parent = newParentBusinessObj;

                    //Add to diagram model
                    var newParentBusinessObjectsDiElement = getDiElementContainingPlaneElement(newParentBusinessObj);
                    newParentBusinessObjectsDiElement.planeElement.push(businessObj.diElement);
                    businessObj.diElement.$parent = newParentBusinessObj.diElement;
                }

            } else if (instanceOf(businessObj, ['bp:Artifact'])) {
                //Remove from parent
                if (instanceOf(currentParentBO, ['bp:Process'])) {
                    //remove from semantic model
                    var removed = Collections.remove(currentParentBO.get('artifacts'), businessObj);
                    if (removed != -1) {
                        businessObj.$parent = null;

                        //remove from diagram model.
                        Collections.remove(currentParentBO.diElement.planeElement, businessObj.diElement);
                        businessObj.diElement.$parent = null;
                    }


                }
                if (instanceOf(newParentBusinessObj, ['bp:Process'])) {
                    //Add to the new parent.
                    newParentBusinessObj.get('artifacts').push(businessObj);
                    businessObj.$parent = newParentBusinessObj;
                    newParentBusinessObj.diElement.planeElement.push(businessObj.diElement);
                    businessObj.diElement.$parent = newParentBusinessObj.diElement;
                }

            }
        }
    }

    function getBusinessObject(djsObject) {
        return djsObject && djsObject.businessObject || djsObject;
    }

    function getDiLabel(diElement) {
        if (!diElement.label) {
            diElement.label = elementFactory.createDiLabel();
        }
        return diElement.label;
    }

}

ModelSynchronizer.$inject = ['eventBus', 'elementFactory', 'connectionDocking', 'processModdle'];

inherits(ModelSynchronizer, CommandInterceptor);


ModelSynchronizer.prototype.register = function (cmdStackEvents, eventList, priority, handlerFn, unwrap, that) {
    cmdStackEvents.forEach(function (cmdStackEvent) {
        this[cmdStackEvent](eventList, priority, handlerFn, unwrap, that);
    }, this);
};

export default ModelSynchronizer;

