"use strict";

import DjsElementFactory from 'diagram-js/lib/core/ElementFactory';
import inherits from 'inherits';
import assign from 'lodash/assign';
import map from 'lodash/map';
import * as LabelUtil from './LabelUtil';

/**
 * Element factory is used to create diagram-js model elements (see: diagram-js/model).
 *
 * @constructor
 * @extends DjsElementFactory
 *
 */
function ElementFactory(processModdle, dtDiagram) {
    DjsElementFactory.call(this);
    this._processModdle = processModdle;
    this.dtDiagram = dtDiagram;
}
ElementFactory.$inject = ['processModdle', 'dtDiagram'];

inherits(ElementFactory, DjsElementFactory);


ElementFactory.prototype.djsCreate = DjsElementFactory.prototype.create;

/**
 * Creates diagram-js Model element with number of additional attributes.
 *
 * @param {string} elementType diagram-js model element type.
 *          One of ['connection', 'shape', 'label', 'root'] @see diagram-js/model.type
 * @param {object} attrs Additional attributes.
 * @param {string} [attr.type] type of semantic object.
 * @param {string} [attr.businessObject] the existing semantic object for which the diagram-js model needs to be
 *     created.
 * @param {string} [attr.businessObject.diElement] the existing diagram semantic object for which the model needs to be
 *     created.
 *
 * @returns {*} djs model element with additional attrs applied.
 */
ElementFactory.prototype.create = function (elementType, attrs) {

    // no special magic for labels,
    // we assume their businessObjects have already been created
    // and wired via attrs
    if (elementType === 'label') {
        return this.djsCreate(elementType, assign({type: 'label'}, LabelUtil.DEFAULT_LABEL_SIZE, attrs));
    }
    var size = {};

    attrs = attrs || {};

    var semanticObject = attrs.businessObject;
    if (!semanticObject) {

        if (!attrs.type) {
            throw new Error('Semantic model type not specified.');
        }

        semanticObject = this.createSemanticObject(attrs.type, attrs);
    }

    //Linking semanticObject with di model object.
    if (!semanticObject.diElement) {
        size = this.getDefaultElementSize(semanticObject);
        this._processModdle.bindSemanticDiRef(semanticObject);
        semanticObject.diElement = this.createDiElement(elementType, semanticObject);
    }
    attrs = assign({
        businessObject: semanticObject,
        id: semanticObject.id
    }, size, attrs);

    return this.djsCreate(elementType, attrs);
};

ElementFactory.prototype.createSemanticObject = function (type, attrs) {
    /* Only tasks will have automatically assigned names (initially the same as internal names).
     The names of all other elements are empty strings. */

    var flowElements = this._getAllFlowElements(this.dtDiagram.model.rootElements[0]);

    var semanticObj = this._processModdle.createWithId(type);
    var taskName;
    var taskLabel;

    // Nikita CBPM-26115
    // If a parentFlowContainer is associated with an element, fetch from it the array of 'childInternalNames'
    // These internalNames should also be considered along with the existing internal names in flowElements (process)
    if (attrs.parentFlowContainer && attrs.parentFlowContainer.childInternalNames) {
        flowElements = flowElements.concat(attrs.parentFlowContainer.childInternalNames);
    }
    if (semanticObj.$instanceOf('bp:StartEvent')) {
        assign(semanticObj, {internalName: this.getNextInternalName("StartEvent", flowElements)});
    }
    if (semanticObj.$instanceOf('bp:EndEvent')) {
        assign(semanticObj, {internalName: this.getNextInternalName("EndEvent", flowElements)});
    }
    if (semanticObj.$instanceOf('bp:SequenceFlow')) {
        if (attrs) {
            assign(semanticObj, {flowMarker: attrs.flowMarker});
        } else {
            assign(semanticObj, {});
        }
    }
    if (semanticObj.$instanceOf('bp:Task')) {
        taskName = this.getNextInternalName("Task", flowElements, attrs.shapeAttrs);
        taskLabel = taskName.replace('_', ' ');
        assign(semanticObj, {name: taskLabel, internalName: taskName});
    }
    if (semanticObj.$instanceOf('bp:Gateway')) {
        taskName = this.getNextInternalName("Gateway", flowElements);
        assign(semanticObj, {internalName: taskName});
    }
    if (semanticObj.$instanceOf('bp:TextAnnotation')) {
        var initalTextLabel = 'Action notes...';
        assign(semanticObj, {text: initalTextLabel, textFormat: 'text/plain'});
    }
    if (semanticObj.$instanceOf('bp:ScriptTask')) {
        assign(semanticObj, {taskType: attrs.taskType});
    }
    if (semanticObj.$instanceOf('bp:TciServiceTask')) {
        assign(semanticObj, {excludeEmptyOptionalInput: attrs.excludeEmptyOptionalInput});
    }
    if (semanticObj.$instanceOf('bp:SubProcess')) {
        if (attrs.subProcessType === 'ParallelLaneContainer') {
            taskName = this.getNextInternalName("ParallelLaneContainer", flowElements);
            taskLabel = 'Parallel Flow Container';
            if (taskName.indexOf('_') !== -1) {
                taskLabel += ' ' + taskName.substring(taskName.indexOf('_') + 1);
            }

            // The code expects 'flowElements' to have been initialized
            // Explicitly set flowElements to blank to avoid errors
            assign(semanticObj, {name: taskLabel, internalName: taskName, subProcessType: attrs.subProcessType, flowElements: []});
        } else if (attrs.subProcessType === 'ParallelLane') {

            taskName = this.getNextInternalName("ParallelLane", flowElements);
            taskLabel = 'Parallel Flow';
            if (taskName.indexOf('_') !== -1) {
                taskLabel += ' ' + taskName.substring(taskName.indexOf('_') + 1);
            }

            // The code expects 'flowElements' to have been initialized
            // Explicitly set flowElements to blank to avoid errors
            assign(semanticObj, {name: taskLabel, internalName: taskName, subProcessType: attrs.subProcessType, flowElements: []});
        } else {

            taskLabel = 'Initial tasks';
            taskName = this.getNextInternalName("SubProcess", flowElements);
            assign(semanticObj, {name: taskLabel, internalName: taskName, subProcessType: attrs.subProcessType});
        }
    }

    if (attrs.parentFlowContainer) {
        if (!attrs.parentFlowContainer.childInternalNames) {
            attrs.parentFlowContainer.childInternalNames = [];
        }
        // CBPM-26115 Add the newly generated internal name of the element to the parentFlowContainer
        attrs.parentFlowContainer.childInternalNames.push({internalName: taskName});
    }
    return semanticObj;
};

ElementFactory.prototype.getDefaultElementSize = function (semantic) {

    if (semantic.$instanceOf('bp:Task')) {
        return {width: 140, height: 120};
    }

    if (semantic.$instanceOf('bp:SubProcess')) {
        if (semantic.subProcessType === 'ParallelLaneContainer') {
            return {width: 520, height: 390};
        } else if (semantic.subProcessType === 'ParallelLane') {
            return {width: 520, height: 180};
        }
        return {width: 260, height: 170};
    }

    if (semantic.$instanceOf('bp:Gateway')) {
        return {width: 64, height: 64};
    }

    if (semantic.$instanceOf('bp:Event')) {
        return {width: 60, height: 60};
    }

    // TODO :- To verify/confirm whether this should be default height/width of text annotations.

    if (semantic.$instanceOf('bp:TextAnnotation')) {
        return {width: 300, height: 80};
    }

    return {width: 110, height: 80};
};

/**
 * Creates a default DI model element for specified djs.model type and semantic model object.
 *
 * @param {string} elementType Djs model element type. One of ['connection', 'shape', 'label', 'root'] @see
 *     djs.model.type
 * @param semanticObject Semantic process model object.
 * @returns {moddle.DI element} moddle di element for a specified semantic model.
 */
ElementFactory.prototype.createDiElement = function (elementType, semanticObject, attrs) {
    var di;
    attrs = attrs || {};
    if (elementType === 'root') {
        di = this._processModdle.createWithId('bpdi:BPPlane', {
            bpElement: semanticObject
        });
    } else if (elementType === 'shape') {
        di = this._processModdle.createWithId('bpdi:BPShape', assign({
            bpElement: semanticObject,
            bounds: this.createDiBounds()
        }, attrs));
    } else if (elementType === 'connection') {
        di = this._processModdle.createWithId('bpdi:BPEdge', assign({
            bpElement: semanticObject
        }, attrs));
    } else {
        throw new Error('Unknown diagram model type. [' + elementType + ']');
    }
    return di;
};

ElementFactory.prototype.createDiLabel = function (bounds) {
    return this._processModdle.createWithId('bpdi:BPLabel', {
        bounds: this.createDiBounds(bounds)
    });
};

ElementFactory.prototype.createDiBounds = function (bounds) {
    return this._processModdle.createWithId('dc:Bounds', bounds);
};

ElementFactory.prototype.createDiWaypoints = function (waypoints) {
    /* Sid CBPM-24475 lodash/map in 4.17.21 no supports 'thisArg' parameter, so need to setup local variable to hold 'this' */
    var self = this;

    return map(waypoints, function (point) {
        return self._processModdle.create('dc:Point', {x: point.x, y: point.y});
    });
};


/**
 * Returns a new unique internal name in a form of: encodeURIComponent(<prefix>)_<number>.
 *
 * @param {string} prefix The prefix of the interanal name.
 * @param {object} [internalNamesCache] Optional cache of internalName -> true can be passed to optimize
 *          if more internal names needs to be created at one time. (Initially empty object ({}) needs to be passed.)
 * @param namedElementCollection the collection of objects that this must be unique over.
 * @param shapeAttrs {object} Used to keep the track of latest task counter while creating a multiple tasks in single go.
 *
 *
 * @returns {string} The new unique internal name.
 */
ElementFactory.prototype.getNextInternalName = function (prefix, namedElementCollection, shapeAttrs) {
    /* Start at 2 so that we get "Task", "Task_2" NOT "Task", "Task_1", "Task_2" which is a bit unexpected */
    var i = (shapeAttrs && shapeAttrs.taskCounter)  ? shapeAttrs.taskCounter  : 2;

    var encodedPrefix = encodeURIComponent(prefix);
    var name = encodedPrefix;

    while (this._flowElementInternalNameExists(name, namedElementCollection)) {
        name = encodedPrefix + '_' + i;
        i++;
        if(shapeAttrs && shapeAttrs.taskCounter){
            shapeAttrs.taskCounter = shapeAttrs.taskCounter + 1;
        }
    }

    return name;
};

/**
 * @param namedElementCollection the collection of objects that this must be unique over.
 *
 * @returns {boolean} true if the given internalName is already used
 */
ElementFactory.prototype._flowElementInternalNameExists = function (internalName, namedElementCollection) {

    if (namedElementCollection && namedElementCollection.length) {
        for (var i = 0; i < namedElementCollection.length; i++) {
            if (namedElementCollection[i].internalName === internalName) {
                return true;
            }
        }
    }
    return false;
};

/**
 *  Recursively return all the containing flow elements.
 * @param container instance of 'FlowElementsContainer' of which containing flow elements need to be returned.
 * @returns {Array}
 */
ElementFactory.prototype._getAllFlowElements = function (container) {
    var result = [];
    var _self = this;
    if (container) {
        result = result.concat(container.flowElements);
        container.flowElements.forEach(function (flowElement) {
            if (flowElement.$instanceOf && flowElement.$instanceOf('bp:FlowElementsContainer')) {
                result = result.concat(_self._getAllFlowElements(flowElement));
            }
        });
    }
    return result;
};

/**
 * Sid CBPM-20853 Need access to plain old bpModdle for some upgrade stuff.
 */
ElementFactory.prototype.getBpModdle = function() {
    return this._processModdle;
}

export default ElementFactory;