'use strict';


import assign from 'lodash/assign';

/**
 * Context pad provider. This provide context pad support for Bottom side pad on the Shape.
 * Adds edit action action gadgets - edit, delete, add comment
 */
function EditContextPadProvider(dtContextPad, modeling, processDiagramRules, editorActions) {

    dtContextPad.registerProvider(this);
    this._modeling = modeling;
    this._processDiagramRules = processDiagramRules;
    this._editorActions = editorActions;
}

EditContextPadProvider.$inject = [
    'dtContextPad',
    'modeling',
    'processDiagramRules',
    'editorActions'
];



EditContextPadProvider.prototype.getContextPadEntries = function (element) {

    var modeling = this._modeling,
        editorActions = this._editorActions;
    var processDiagramRules = this._processDiagramRules;

    var actions = {};

    /*
    * CBPM-15568 :- Chaitanya , to avoid showing process-editor-toolbox on when the element is hidden
    */
    if (element.type === 'label' || element.hidden) {
        return actions;
    }

    var businessObject = element.businessObject;

    function deleteElement(event, element) {
        if(element && processDiagramRules.isContainedInInitialTaskSubProcess(element.businessObject)){
            var parent = element.parent;
            modeling.removeTaskFromSubProcess(parent, [element]);
        }else {
            modeling.removeElements([element]);
        }
    }

    function openProperties(e) {
        editorActions.trigger('openProperties');
    }

    function openComments(e) {
        editorActions.trigger('openComments');
    }

    function addLane(event, element){
        modeling.addLane(element, 'bottom');
    }

    // Delete
    if (processDiagramRules.canDelete([businessObject])) {
        assign(actions, {
            'delete': {
                className: 'dt-icon-delete dt-hand-pointer',
                title: 'Delete',
                action: {
                    click: deleteElement
                }
            }
        });
    }

    // Properties - Don't show edit properties icon and comments icon if the selected object is a process */
    if (processDiagramRules.canShowEdit(businessObject)) {
        // Show notes panel
        assign(actions, {
            'comments': {
                group: 'comments',
                className: 'dt-bpm-icon-ic_comments dt-hand-pointer',
                title: 'Add Comment',
                action: {
                    click: openComments
                }
            }
        });

        assign(actions, {
            'properties': {
                group: 'properties',
                className: 'dt-bpm-icon-ic_settings dt-hand-pointer',
                title: 'Show Properties',
                action: {
                    click: openProperties
                }
            }
        });
    }

    if (processDiagramRules.canShowAddLane(businessObject)) {
        assign(actions, {
            'addLane': {
                group: 'addLane',
                className: 'dt-bpm-icon-add_lane dt-hand-pointer',
                title: 'Add a flow',
                action: {
                    click: addLane
                }
            }
        });
    }

    return this.getOrderedEntries(actions, element);
};

/**
 * Specifies that current provider is for the 'bottom' side context pad
 * except for a 'Parallel Lane' where it is on the right
 *
 * @param element
 * @returns {string}
 */
EditContextPadProvider.prototype.getContextPadSide = function (element) {
    // Nikita CBPM-26115 Show the 'edit' context pad for a 'Parallel Lane' on the right side of the element
    if(element && this._processDiagramRules.isParallelLane(element)){
        return 'right';
    }
    return 'bottom';
};

/**
 * CBPM-26115 Specifies the order of context pad entries for an element
 *
 * @param entries
 * @param element
 * @returns {unknown}
 */
EditContextPadProvider.prototype.getOrderedEntries = function (entries, element) {

    if (this._processDiagramRules.isParallelLane(element)) {
        // CBPM-26115 The entries for a parallel lane should appear in a reverse order
        // As the context pad appears to the 'right' a 'reverse' order makes more sense

        //Reverse the order of context pad entries
        var reversedKeys = Object.keys(entries).reverse();

        //Put the reversed entries back into the object
        var reversedEntries = reversedKeys.reduce(function (acc, key) {
            acc[key]= entries[key];
            return acc;
        }, {});

        //Return newly ordered object
        return reversedEntries;
    }

    // For all other elements return the default order
    return entries;
};

export default EditContextPadProvider;