'use strict';

/**
 * Adds ProcessEditor related actions to the 'editorActions' service. EditorActions service provides access to modeling
 * actions by decoupling the one who requests the action to be triggered and the trigger itself.
 *
 * The registered action includes:
 *  - 'openProperties' - emits 'processEditorActions.openProperties' event on the event bus.
 *  - 'closeProperties' - emits 'processEditorActions.closeProperties' event on the event bus.
 */
function ProcessEditorActions(editorActions, eventBus, selection) {
    this._eventBus = eventBus;

    var self = this;

    var actions = {
        openProperties: function () {
            self._fire('openProperties', {selection: selection.get()});
        },
        closeProperties: function () {
            self._fire('closeProperties', {selection: selection.get()});
        },
        openComments: function () {
            self._fire('openComments', {selection: selection.get()});
        }
    };
    editorActions.register(actions);
}

ProcessEditorActions.prototype._fire = function(event, eventObject) {
    this._eventBus.fire('processEditorActions.' + event, eventObject);
};

ProcessEditorActions.$inject = [
    'editorActions', 'eventBus', 'selection'
];

export default ProcessEditorActions;
