'use strict';

import inherits from 'inherits';
import RuleProvider from 'diagram-js/lib/features/rules/RuleProvider';
import {instanceOf} from '../modeling/ModelUtil';
import {isOfType} from '../modeling/ModelUtil';
import isEmpty from 'lodash/isEmpty';
import isArray from 'lodash/isArray';
import sortBy from 'lodash/sortBy';
var HIGH_PRIORITY = 1500;

/**
 * Process diagram rules.
 */
function ProcessDiagramRules(eventBus, dtDiagram, rules) {
    this.readOnly = dtDiagram.isReadOnly();
    RuleProvider.call(this, eventBus);

    /*
    * Chaitanya:-
    * Creating a event Handler for "connectionSgement.move.start" of higher priority
    * so that its gets called first & prevent the the movement of shapes if they are contained inside the
    * subProcess.
    *
    * Note:- This can be considered as special case as the event "connectionSgement.move.start" inside the ConnectionSegmentMove.js
    * does not considers the whether the action can be performed using rules or not. i.e. rules.allowed() not used.
    *
    * */
    eventBus.on('connectionSegment.move.start', HIGH_PRIORITY, function (e) {
        var context = e.context,
            type = e.type;

        var allowed = context.allowed = rules.allowed(type, context);
        if (!allowed) {
            return false;
        }
    });
}

inherits(ProcessDiagramRules, RuleProvider);

ProcessDiagramRules.$inject = ['eventBus', 'dtDiagram', 'rules'];




/**
 * Initialize rules for commands.
 */
ProcessDiagramRules.prototype.init = function () {
    var self = this;
    this.addRule('connection.create', function (context) {
        return !self.readOnly && self.canConnect(context.source, context.target);
    });

    this.addRule('elements.delete', function (context) {
        return !self.readOnly && self.canDelete(context.elements);
    });

    this.addRule('connection.reconnectStart', function (context) {

        var connection = context.connection,
            source = context.hover || context.source,
            target = connection.target;

        return !self.readOnly && self.canConnect(source, target, connection) && self.canMoveConnection(connection);
    });

    /*
    * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
    * Added connection.reconnect Rule Explicitly
    * */
    this.addRule('connection.reconnect', function (context) {

        var connection = context.connection,
            source = context.source,
            target = context.target;

        return self.canConnect(source, target, connection);
    });

    this.addRule('connection.reconnectEnd', function (context) {

        var connection = context.connection,
            source = connection.source,
            target = context.hover || context.target;

        return !self.readOnly && self.canConnect(source, target, connection) && self.canMoveConnection(connection);
    });

    this.addRule('connection.updateWaypoints', function (context) {

        var connection = context.connection;
        /*
        * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
        * Updated the return due to diagram upgrade changes.
        * */
        return {
            type: context.connection.type
        };
    });

    this.addRule('connectionSegment.move.start', function (context) {

        var connection = context.connection;

        return self.canMoveConnection(connection);
    });

    this.addRule('shape.resize', function (context) {

        var shape = context.shape,
            newBounds = context.newBounds;

        return !self.readOnly && self.canResize(shape, newBounds);
    });

    this.addRule('elements.move', function (context) {
        var target = context.target,
            shapes = context.shapes,
            position = context.position;
        return !self.readOnly && self.canMove(shapes, target, position);
    });

    this.addRule('shape.create', function (context) {
        var target = context.target,
            source = context.source,
            shape = context.shape,
            position = context.position;
        return !self.readOnly && self.canCreate(shape, target, source, position);
    });

    this.addRule('shape.append', function (context) {
        var target = context.target,
            source = context.source,
            shape = context.shape,
            position = context.position;
        return !self.readOnly && self.canCreate(shape, target, source, position);
    });
};

/**
 * Returns if elements can be moved.
 * @param elements elements to be tested.
 * @param target target container.
 * @returns {*} true if elements can be moved.
 */
ProcessDiagramRules.prototype.canMove = function canMove(elements, target) {
    if (this.readOnly) {
        return false;
    }
    var self = this;

    var inSubProcess = elements.find(function (element) {
        return isContainedInInitialTaskSubProcess(element);
    });

    if (inSubProcess) {
        return false;
    }
    if (!target) {
        return true;
    }
    var isFlowElementsContainer = elements.find(function (element) {
        return isParallelLaneContainer(element) || isInitialTaskSubProcess(element);
    });

    var pinnedParallelLane = elements.find(function (element) {
        return isParallelLane(element);
    });

    // If one of the selected element is parallel lane then do not allow multi-selection
    if(pinnedParallelLane && elements.length !== 1){
        return false;
    }

    var moveWithinSameParent = elements.every(function (element) {
        return element.parent === target;
    });
    if (!moveWithinSameParent) {
        // Nikita CBPM-26006 Prevent moving a 'Parallel Flow Container' or 'Initial Tasks' sub-process inside another container
        // Also prevent moving of elements to them
        if (isFlowElementsContainer || isParallelLaneContainer(target) || isInitialTaskSubProcess(target)) {
            return false;
        }

        // Sushant CBPM-26082 Prevent drag drop of a 'Parallel Lane' outside a same 'Parallel Lane Container'
        if (pinnedParallelLane) {
           if(isParallelLane(target)){
                return (pinnedParallelLane.parent === target.parent);
            } else {
               return false;
           }
        }
        /*
        Nikita CBPM-26006 Allow moving any set of objects that have no connections outside the current selection context

        This can be verified by checking that the set of all incoming connections in the current selection context
        is equal to the set of all outgoing connections in the selection context
         */
        var incomingFlows = getConnections('incoming', elements);
        var outgoingFlows = getConnections('outgoing', elements);

        return arraysEqual(incomingFlows, outgoingFlows);
    }

    return elements.every(function (element) {
        return self.canDrop(element, target);
    });
};

/**
 * Returns if elements can be deleted.
 * @param elements elements to be tested.
 * @param calledDirectly states that call to function is made directly or called from code.
 * @returns {*} true if elements can be deleted.
 */
ProcessDiagramRules.prototype.canDelete = function canDelete(elements, calledDirectly) {
    if (this.readOnly) {
        return false;
    }
    var self = this;
    return !elements.some(function (element) {
        //Only labels together with their target objects can be removed.
        if (isLabel(element)) {
            return elements.indexOf(element.labelTarget) === -1;
        }
        return isLockedElement(element) || isOfType(element, 'bp:Process') ||
            (!calledDirectly && (isContainedInInitialTaskSubProcess(element) &&
                (isLastFormTask(element) || isNotFirstTask(element) || isOfType(element, 'bp:SequenceFlow'))));
    });
};

/**
 *  Return true if passed 'element' is the last form task, otherwise 'false'.
 * @param element
 * @returns {*|boolean}
 */
 function isLastFormTask(element){
    var bo = element.businessObject || element;
    return instanceOf(bo, 'bp:FormTask') && isEmpty(bo.outgoing);
}

/**
 *  Returns 'true' if passed task is not a First task
 * @param element
 * @returns {boolean}
 */
function isNotFirstTask(element){
    var bo = element.businessObject || element;
    return !isEmpty(bo.incoming);
}

/**
 * Returns if edit properties icon can be shown on the given element
 *
 * @param element
 * @returns {boolean} - true(default) if the edit icon can be shown; false otherwise.
 */
ProcessDiagramRules.prototype.canShowEdit = function (element) {
    return !isOfType(element, ['bp:Process']);
};

/**
 * Returns true if 'add a lane' properties icon can be shown on the given element
 *
 * @param element
 * @returns {boolean} - true if the add lane icon can be shown; false otherwise.
 */
ProcessDiagramRules.prototype.canShowAddLane = function (element) {
    return isParallelLaneContainer(element);
};


/**
 * Returns if add to subprocess icon can be shown on the element
 *
 * @param element
 * @returns {boolean} - false(default) if the add icon should not  be shown; true otherwise.
 */
ProcessDiagramRules.prototype.isContainedInInitialTaskSubProcess = function (element) {
    return isContainedInInitialTaskSubProcess(element);
};

/**
 * Returns true if passed element is contained inside the Parallel flow lane.
 *
 * @param element
 * @returns {boolean} - false(default) if contained in parallel flow lane; true otherwise.
 */
ProcessDiagramRules.prototype.isContainedInParallelFlowLane = function (element) {
    return isContainedInParallelFlowLane(element);
};

/**
 * Returns if element can be dropped onto the target.
 * @param element elements to be tested.
 * @returns {*} true if element can be dropped onto the target.
 */
ProcessDiagramRules.prototype.canDrop = function canDrop(element, target, position) {
    if (this.readOnly) {
        return false;
    }

    if (isLabel(element) && !isConnection(target)) {
        return true;
    }

    if(isContainedInInitialTaskSubProcess(element)){
        return false;
    }

    /*
    * Chaitanya : CBPM-21332 Prevent drag dropping of new/old task into the subprocess.
    * The task can be added/removed into subProcess only through use of commands
    * and not through drag/dropping of tasks using mouse.
    * */
    // Nikita CBPM-26115 Prevent drag drop into a 'Parallel Lane Container'
    if(isInitialTaskSubProcess(target) || isParallelLaneContainer(target)){
        return false;
    }

    // Nikita CBPM-26006 Prevent drag drop of a 'Parallel Lane Container' into a 'Parallel Lane'
    if (isParallelLane(target)) {
        return !isParallelLaneContainer(element);
    }

    var elementBo = element.businessObject || element;
    var targetBo = target.businessObject || target;
    if (instanceOf(elementBo, ['bp:FlowElement', 'bp:Artifact'])) {
        if (instanceOf(targetBo, ['bp:FlowElementsContainer', 'bp:Process'])) {
            return true;
        }

        // allow unconnected activities and gateways to drop on connectors
        if (instanceOf(elementBo, ['bp:Activity', 'bp:Gateway'])) {
            // if it's not already connected AND dropped on connection
            // AND connection is not start event connection
            if ((!isConnected(element)) && (isConnection(target)) && (!isStartEventToFirstTaskFlow(target))) {
                return true;
            }
        }
    }

    return false;
};

/**
 * Returns if connection can be moved or not
 * @param connectiom elements to be tested.
 * @returns {*} true if connection can be moved;.
 */
ProcessDiagramRules.prototype.canMoveConnection = function canMoveConnection(connection) {
    return !isContainedInInitialTaskSubProcess(connection);
};

/**
 * Returns if a shape can be created.
 * @param shape shape to be created.
 * @param target container to create a shape in.
 * @param source
 * @param position position in the container.
 * @returns {*} true if element can be created.
 */
ProcessDiagramRules.prototype.canCreate = function canCreate(shape, target, source, position) {
    if (this.readOnly) {
        return false;
    }
    if (!target) {
        return false;
    }

    if (isLabel(target)) {
        return null;
    }

    if (source === target) {
        return false;
    }

    if (source && source.parent) {
        // Nikita CBPM-26066 If a shape is appended to/from an element in a Parallel Flow Lane, verify the target is the same flow lane
        if (isParallelLane(target) || isParallelLane(source.parent)) {
            return target === source.parent;
        }
    }

    return this.canDrop(shape, target, position);
};

/**
 * Returns if a shapes can be connected.
 * @param source source shape.
 * @param target target shape.
 * @param connection a connection.
 * @returns {*} true if element can be connected.
 */
ProcessDiagramRules.prototype.canConnect = function canConnect(source, target, connection) {
    if (this.readOnly) {
        return false;
    }
    if (!source || !target) {
        return false;
    }
    if (source === target) {
        return false;
    }
    if (this.isSequenceFlowSource(source) &&
        this.isSequenceFlowTarget(target)) {
        // Nikita CBPM-26066 Allow connect only within the same parent
        if (source.parent && target.parent) {
            return source.parent === target.parent ? {type: 'bp:SequenceFlow'} : false;
        }
        return {type: 'bp:SequenceFlow'};
    }
    return false;
};

/**
 *
 * Function to determine whether given shape can be resized or not.
 *
 * As a part of CBPM-20740
 * If the shape is of textAnnotation , we are enabling the resize of the shape.
 *
 * @param shape
 * @param newBounds
 * @returns {boolean}
 */
// TODO :- Condition may be updated after auto-resize functionality CBPM-26070.
ProcessDiagramRules.prototype.canResize = function canResize(shape, newBounds) {
    if (shape.businessObject && (isTextAnnotation(shape.businessObject)|| isParallelLaneContainer(shape.businessObject) || isParallelLane(shape.businessObject))) {
        return true;
    }
    return false;
};
/**
 * Returns if an element is a valid sequence flow source.
 * @param element element to test.
 * @returns {*} true if element can be a source of a sequence flow.
 */
ProcessDiagramRules.prototype.isSequenceFlowSource = function (element) {
    if (this.readOnly) {
        return false;
    }
    var bo = element.businessObject || element;
    /*
    * CBPM:15568 Auto Case Start :- Modified the isSequenceFlowSource , as now the start event can also be
    * the sequenceFlowSource in case of the auto case start event.
    * */
    // Nikita CBPM-26115 'Parallel Flow(Lane)' is not a sequence flow source
    return (instanceOf(bo, 'bp:FlowNode') && !isParallelLane(element)
        && !isEndEvent(element)) && !isContainedInInitialTaskSubProcess(element) &&
        (!isStartEvent(element) || isAutoStart(element));
};
/**
 * Returns if an element is a valid sequence flow target.
 * @param element element to test.
 * @returns {*} true if element can be a target of a sequence flow.
 */
ProcessDiagramRules.prototype.isSequenceFlowTarget = function (element) {
    if (this.readOnly) {
        return false;
    }
    var bo = element.businessObject || element;
    /*
    * CBPM-24543 Sequence Flow inside subTasks :- Modified the isSequenceFlowSource to
    * avoid the connection where the Task inside the subTasks acts as target/destination.
    * */
    // Nikita CBPM-26115 'Parallel Flow(Lane)' is not a sequence flow target
    return instanceOf(bo, 'bp:FlowNode') && !isParallelLane(element)
        && !isStartEvent(element) && !isContainedInInitialTaskSubProcess(element)
        && !isFirstTask(element);
};

ProcessDiagramRules.prototype.isStartEvent = isStartEvent;
ProcessDiagramRules.prototype.isEndEvent = isEndEvent;
ProcessDiagramRules.prototype.isFirstTask = isFirstTask;
ProcessDiagramRules.prototype.isStartEventToFirstTaskFlow = isStartEventToFirstTaskFlow;
ProcessDiagramRules.prototype.isLockedElement = isLockedElement;
ProcessDiagramRules.prototype.isDefaultFlow = isDefaultFlow;
ProcessDiagramRules.prototype.isMarkedFlow = isMarkedFlow;
ProcessDiagramRules.prototype.isAutoStart = isAutoStart;
ProcessDiagramRules.prototype.isAutoStartWithDeadLine = isAutoStartWithDeadLine;
ProcessDiagramRules.prototype.isStartEventOutgoingFlow = isStartEventOutgoingFlow;
ProcessDiagramRules.prototype.getDefaultExitState = getDefaultExitState;
ProcessDiagramRules.prototype.isLastTaskInSubProcess = isLastTaskInSubProcess;
ProcessDiagramRules.prototype.getEmbeddedSubProcess = getEmbeddedSubProcess;
ProcessDiagramRules.prototype.isInitialTaskSubProcess = isInitialTaskSubProcess;
ProcessDiagramRules.prototype.isUserTask = isUserTask;
ProcessDiagramRules.prototype.isParallelLane = isParallelLane;
ProcessDiagramRules.prototype.isParallelLaneContainer = isParallelLaneContainer;
ProcessDiagramRules.prototype.isLockedForDeleteParallelLane = isLockedForDeleteParallelLane;

function isStartEvent(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    return instanceOf(bo, 'bp:StartEvent');
}

function isEndEvent(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    return instanceOf(bo, 'bp:EndEvent');
}

/**
 * Return the default exit state for a task
 * Default state is 'Any' if - User task or the last form task in a Sub Process, 'None' otherwise
 * @param element
 */
function getDefaultExitState(element){
    if (isUserTask(element) || (isLastTaskInSubProcess(element))) {
        return "Any";
    } else {
        return "None";
    }
};

/**
 * Return true if the specified object is the last task in the sub process, false otherwise.
 *
 * @param element
 */
function isLastTaskInSubProcess(element){
    if(element) {
        return (getEmbeddedSubProcess(element) && isLastFormTask(element));
    }
    return false;
};

/**
 * Return the embedded sub-process for a task.
 * @returns {obj}
 */
function getEmbeddedSubProcess(element) {
    if (element) {
        var bo = (element.parent && element.parent.businessObject) || element.$parent;
        return isInitialTaskSubProcess(bo) ? bo : null;
    }
    return null;
};

/**
 * Return true if the specified object is a sub process of type 'InitialTasks', false otherwise.
 *
 *
 * @param element
 *
 * @returns true if the specified object is a sub process, false otherwise.
 */
function isInitialTaskSubProcess(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (null != bo) {
        return instanceOf(bo, 'bp:SubProcess') && bo.get('subProcessType') === 'InitialTasks';
    } else {
        return false;
    }
};

/**
 * Return true if the specified object is a TextAnnotation, false otherwise.
 *
 * @param element
 * @returns {true if the specified object is a TextAnnotation, false otherwise.}
 */
function isTextAnnotation(element) {
    return instanceOf(element, 'bp:TextAnnotation');
}

/**
 * Return true if the specified object is an user task, false otherwise.
 *
 * @param element
 *
 * @returns true if the specified object is an user task, false otherwise.
 */
function isUserTask(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (null != bo) {
        return instanceOf(bo, 'bp:UserTask');
    } else {
        return false;
    }
};

/**
 * Returns if the element is a first process FormTask.
 *
 * @param element diagram element for a task or moddle object representing task.
 * @returns {*}
 */
function isFirstTask(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:FormTask')) {
        var incoming = bo.get('incoming');
        if (incoming && incoming.length === 1 && incoming[0] && incoming[0].$instanceOf('bp:SequenceFlow')) {
            return isStartEvent(incoming[0].sourceRef);
        }
    } else  if (instanceOf(bo, 'bp:SubProcess')) {
        return bo.get('subProcessType') === 'InitialTasks';
    }
    return false;
}

function isDefaultFlow(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:SequenceFlow')) {
        var source = bo.sourceRef;
        return instanceOf(source, 'bp:ExclusiveGateway') && bo === source.default;
    }
    return false;
}

/**
 * If it is an element for which a flow marker should be displayed.
 */
function isMarkedFlow(element) {
    /* Marker is displayed for a non default sequence flow coming out from an exclusive gateway. */
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:SequenceFlow')) {
        var source = bo.sourceRef;
        return instanceOf(source, 'bp:ExclusiveGateway') && bo !== source.default && bo.flowMarker;
    }
    return false;
}

/**
 * Return true if the element is a flow between start event and a first FormTask.
 *
 * @param element
 * @returns {*}
 */
function isStartEventToFirstTaskFlow(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:SequenceFlow')) {
        return isStartEvent(bo.sourceRef) && isFirstTask(bo.targetRef);
    }
    return false;
}

function isLockedElement(element) {
    return isStartEvent(element) || isFirstTask(element) || isStartEventToFirstTaskFlow(element) || isLockedForDeleteParallelLane(element);
}


function isLabel(element) {
    return !!element.labelTarget;
}

function isConnection(element) {
    return !!element.waypoints;
}

/**
 * Tests whether the given element has any connections; incoming or outgoing.
 *
 * @param element the element to be tested.
 * @return {boolean} true if the given element has either incoming or outgoing connections.
 */
function isConnected(element) {
    if (!element) {
        return false;
    }
    return (element.incoming && element.incoming.length > 0) ||
        (element.outgoing && element.outgoing.length > 0)
}

/**
 * Returns an array of connections.
 * The param 'direction' decides whether to return incoming or outgoing connections
 *
 * @param direction
 * @param elements
 * @returns {*}
 */

function getConnections(direction, elements) {
    var allConnections = elements.reduce(function (acc, element) {
        var connections = element.businessObject.get(direction);
        if (!isEmpty(connections)) {
            acc = acc.concat(connections);
        }
        return acc;
    }, []);

    return allConnections;
}

/**
 * Checks for array equality
 *
 * @param arr1
 * @param arr2
 * @returns {boolean|*}
 */
function arraysEqual(arr1, arr2) {
    if (!isArray(arr1) || ! isArray(arr2) || arr1.length !== arr2.length) {
        return false;
    }
    const sortedArr1 = sortBy(arr1, ["id"]);
    const sortedArr2 = sortBy(arr2, ["id"]);

    return sortedArr1.every(function(val, index) {
        return val === sortedArr2[index];
    });
}
/**
 * Tests if a diagram element belongs to an autoStart process.
 *
 * @param element the diagram element to be tested.
 * @returns {boolean} :- true if element belongs to an autoStart process.
 */
function isAutoStart(element) {
    var process = element && element.parent && element.parent.businessObject;
    return process && process.configuration && process.configuration.autoStart;
}

/**
 * Tests if a diagram element belongs to an autoStart with dead line process.
 *
 * @param element the diagram element to be tested.
 * @returns {boolean} :- true if element belongs to an autoStart with dead line process.
 */
function isAutoStartWithDeadLine(element) {
    var process = element && element.parent && element.parent.businessObject;
    return process && process.configuration && process.configuration.autoStartConfig &&
        process.configuration.autoStartConfig.trigger === "Delayed";
}

/**
 * Tests if element is a sequence flow outging from the start event.
 *
 * @param element the diagram connection or a moddle sequence flow.
 * @returns {boolean} :- true if it is an Start Event
 */
function isStartEventOutgoingFlow(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (instanceOf(bo, 'bp:SequenceFlow')) {
        return isStartEvent(bo.sourceRef);
    }
    return false;
}

/**
 *  Returns 'true' if passed element is contained inside the Initial Tasks SubProcess otherwise return false.
 * @param element
 * @returns {boolean}
 */
function isContainedInInitialTaskSubProcess (element) {
    if(element) {
        var parentBo = (element.parent && element.parent.businessObject) || element.$parent;
        return !!(parentBo && instanceOf(parentBo, 'bp:SubProcess') && parentBo.get('subProcessType') === 'InitialTasks');
    }
    return false;
}

/**
 *  Returns 'true' if passed element is contained inside the Parallel flow lane otherwise return false.
 * @param element
 * @returns {boolean}
 */
function isContainedInParallelFlowLane (element) {
    if(element) {
        var parentBo = (element.parent && element.parent.businessObject) || element.$parent;
        return !!(isParallelLane(parentBo));
    }
    return false;
}

/**
 * Return true if the specified object is a sub process of type 'ParallelLaneContainer', false otherwise.
 *
 * @param element
 * @returns {*|boolean}
 */
function isParallelLaneContainer(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (null != bo) {
        return instanceOf(bo, 'bp:SubProcess') && bo.get('subProcessType') === 'ParallelLaneContainer';
    } else {
        return false;
    }
}

/**
 * Return true if the specified object is a sub process of type 'ParallelLane', false otherwise.
 *
 * @param element
 * @returns {*|boolean}
 */
function isParallelLane(element) {
    if (!element) return false;
    var bo = element.businessObject || element;
    if (null != bo) {
        return instanceOf(bo, 'bp:SubProcess') && bo.get('subProcessType') === 'ParallelLane';
    } else {
        return false;
    }
}

/**
 *  Returns 'true' if passed element is a parallel lane but is 'locked' for delete,
 *  i.e., if it is contained inside a parallel flow container that has only 2 parallel flow lanes, it cannot be deleted
 *
 * @param element
 * @returns {boolean}
 */
function isLockedForDeleteParallelLane(element) {
    if (!element) return false;
    if (isParallelLane(element)) {
        var parentBo = (element.parent && element.parent.businessObject) || element.$parent;
        if (isParallelLaneContainer(parentBo)) {
            return parentBo.flowElements && parentBo.flowElements.length < 3;
        }
    }
    return false;
}

export default ProcessDiagramRules;
