'use strict';

import MoveShapeHandler from 'diagram-js/lib/features/modeling/cmd/MoveShapeHandler';
import inherits from 'inherits';

import {getDiElementContainingPlaneElement, instanceOf} from '../ModelUtil';
import {getBusinessObject} from '../ModelUtil';
import * as Collections from "diagram-js/lib/util/Collections";

/**
 * A handler that implements reversible move of activity tasks and gateways.
 * Delegates to the standard MoveShapeHandler for all other shapes.
 */
function MoveProcessShapeHandler(modeling) {
    // Super CONSTRUCTOR
    MoveShapeHandler.call(this, modeling);

    this._modeling = modeling;
}

MoveProcessShapeHandler.$inject = [ 'modeling' ];

inherits(MoveProcessShapeHandler, MoveShapeHandler);


/**
 * Overrides MoveShapeHandler. If the given shape is an Activity or Gateway,
 * and has been dropped on a connector, record the connection and set the
 * drop parent as the shape's original parent. This ensures that the shape
 * is not added as a child of the connection.
 * It will then call the MoveShapeHandler.
 *
 * @param context the context in which the move is performed. Carries all
 */
MoveProcessShapeHandler.prototype.preExecute = function(context) {
    // if the shape is an activity or gateway AND the target is a connection
    if ((instanceOf(getBusinessObject(context.shape), ['bp:Activity', 'bp:Gateway'])) &&
        (instanceOf(getBusinessObject(context.newParent), 'bp:SequenceFlow'))) {
        // store the connection reference
        context.connection = context.newParent;

        // set the shape's original parent as the new parent
        context.newParent = context.shape.parent;
    }

    // call the default implementation of preExecute
    if (MoveShapeHandler.prototype.preExecute) {
        MoveShapeHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Overrides MoveShapeHandler. If the given shape is an Activity
 * or Gateway, and has been dropped on a connector, it will intersect
 * the connector; adding the connector as an incoming flow and creating
 * a new connector as an outgoing flow to the original connector's
 * target.
 * Calls MoveShapeHandler first.
 *
 * @param context the context in which the move is performed. Carries all
 * the data about the move.
 * @param context.connection if the drop was on a connection, this is that
 * connection.
 */
MoveProcessShapeHandler.prototype.postExecute = function(context) {
    // call the default implementation of postExecute
    if (MoveShapeHandler.prototype.postExecute) {
        MoveShapeHandler.prototype.postExecute.call(this, context);
    }

    // if this was a drop on a connection
    if (context.connection) {
        // intersect the connection with the shape
        this._modeling.intersectConnection(context.connection, context.shape);
    }
};
export default MoveProcessShapeHandler;