'use strict';
import filter from 'lodash/filter';

import DjsSnapping from 'diagram-js/lib/features/snapping/Snapping';
import inherits from 'inherits';

/**
 * Override of diagram-js/lib/features/snapping/Snapping class. The reason for override was the fact that new version
 * of djs also includes connections as list of siblings and hence snapping throws errors trying to get mid points of
 * connections.
 *
 * @constructor
 * @extends diagram-js/lib/features/snapping/Snapping
 *
 * @param canvas
 */
function ProcessSnapping(canvas) {
    /*
    * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
    * Modified the call to super contructor to pass only canvas object.
    *
    * Earlier eventBus was also passed as a parameter to the super constructor
    * */
    DjsSnapping.call(this, canvas);
}


ProcessSnapping.$inject = ['canvas'];

inherits(ProcessSnapping, DjsSnapping);

/**
 * Overrides Snapping#getSiblings(...). Returns a list of siblings to snap to.
 *
 * @param element - the source of snapping.
 * @param target - the target container.
 * @return {*|Array} - an array of sibling elements.
 */
ProcessSnapping.prototype.getSiblings = function (element, target) {

    // snap to all non connection siblings
    return target && filter(target.children, function (e) {
        return !e.hidden && !e.labelTarget && !e.waypoints && e.host !== element && e !== element;
    });
};

export default ProcessSnapping;
