import inherits from 'inherits';


import AutoResizeProvider from "diagram-js/lib/features/auto-resize/AutoResizeProvider";
import {getBusinessObject, isOfType} from "../modeling/ModelUtil";

/**
 * Process Diagram specific provider for automatic resizing.
 *
 * @param eventBus
 * @param modeling
 * @constructor
 */
function ProcessDiagramAutoResizeProvider(eventBus, modeling) {
  AutoResizeProvider.call(this, eventBus);
  this._modeling = modeling;
}

ProcessDiagramAutoResizeProvider.$inject = ['eventBus', 'modeling'];

inherits(ProcessDiagramAutoResizeProvider, AutoResizeProvider);


/**
 * Check if the given target can be expanded
 *
 * @param  {djs.model.Shape} target
 *
 * @return {boolean}
 */
ProcessDiagramAutoResizeProvider.prototype.canResize = function(elements, target) {

  // CBPM-26070 ParallelLaneContainer and ParallelLane can be auto-resized
  if (isOfType(target, 'bp:SubProcess')) {
    return getBusinessObject(target).getSubProcessType() !== 'InitialTasks';
  }

};


export default ProcessDiagramAutoResizeProvider;