'use strict';

import AppendShapeHandler from 'diagram-js/lib/features/modeling/cmd/AppendShapeHandler';
import inherits from 'inherits';

import {isOfType} from '../ModelUtil';

/*Jan: This class is no longer needed in the new version of diagram.js, but it's left to update the connection layout if
* the */

/**
 * A handler that extends diagram js AppendShapeHandler to append (create) shapes from quick icons provided on the
 * shapes. Handles creation of new shapes by delegating to AppendShapeHandler based on where the new shape is dropped.
 *
 * @param modeling
 * @constructor
 */
function AppendProcessShapeHandler(modeling) {

    /* Super CONSTRUCTOR */
    AppendShapeHandler.call(this, modeling);

    this._modeling = modeling;
}

AppendProcessShapeHandler.$inject = ['modeling'];

inherits(AppendProcessShapeHandler, AppendShapeHandler);


/**
 * Overrides AppendShapeHandler of diagram js.
 *
 * @param context
 */
AppendProcessShapeHandler.prototype.preExecute = function (context) {

    /* call the default implementation of preExecute */
    if (AppendShapeHandler.prototype.preExecute) {

        AppendShapeHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Overrides AppendShapeHandler of diagram js.
 *
 * @param context
 */
AppendProcessShapeHandler.prototype.postExecute = function (context) {

    /* This is a drop on the editor - so create a shape and a connection.
        Append shape post execute calls create shape (and create connection) internally. */
    if (AppendShapeHandler.prototype.postExecute) {

        AppendShapeHandler.prototype.postExecute.call(this, context);
    }
};
export default AppendProcessShapeHandler;
