import isFunction from 'lodash/isFunction';
import isArray from 'lodash/isArray';
import isObject from 'lodash/isObject';
import isNumber from 'lodash/isNumber';
import some from 'lodash/some';

/**
 * Safe $instanceOf on a moddle element.
 *
 * @param {object} mObject Moddle object.
 * @param {string| Array<string>} type(s) Type of object to check. (Needs to be qualified, for example: 'bp:Task')
 * @returns {*|boolean}
 */
export function instanceOf(mObject, type) {
    if (isObject(mObject) && isFunction(mObject.$instanceOf)) {
        if (isArray(type)) {
            return some(type, function (t) {
                return mObject.$instanceOf(t);
            });
        }
        return mObject.$instanceOf(type);
    }
    return false;
};

/**
 * Returns business object for a diagram elemnt.
 *
 * @param element diagram-js element.
 * @returns {*}
 */
export function getBusinessObject(element) {
    if (isObject(element) && element.businessObject) {
        return element.businessObject;
    }
    return element;
};

/**
 * Function that recursively search through the businessObject ,
 * to get an diElement containing the parent element.
 *
 * @param businessObject
 * @returns {@DiElement} | A DI element having the plane Element if it doesn't have it return the null.
 */
export function getDiElementContainingPlaneElement(businessObject) {
    if (businessObject.diElement.planeElement) {
        return businessObject.diElement;
    }
    if (businessObject.$parent) {
        return getDiElementContainingPlaneElement(businessObject.$parent);
    }
}

/**
 * Returns if a moddle object or underlying businessObject of a diagram-js element is of specified type (or is one of
 * specified types).
 *
 * @param element diagram-js element or a moddle object
 * @param {string| Array<string>} type or array of types. Type of object to check. (Needs to be qualified, for example:
 *     'bp:Task')
 * @returns {boolean}
 */
export function isOfType(element, type) {
    return instanceOf(getBusinessObject(element), type);
};

/**
 * Returns a collection of those model elements that are positioned to the right
 * of the given element's left edge. If no elements are found, the result will
 * be an empty array.
 *
 * @param element the element on which to locate the results.
 * @return {Array} the collection of elements to the right of the given element.
 */
export function elementsRightOf(element) {
    if ((! element) || (! element.parent) || (! element.parent.children)) {
        return [];
    }

    var x = element.x;
    return element.parent.children.filter(function(aShape) {
        // ignore self, labels and connectors
        if ((element === aShape) || (!aShape.type) || (aShape.type === 'label') || (isArray(aShape.waypoints))) {
            return false;
        }

        return (x <= aShape.x + aShape.width);
    });
};

/**
 * Returns a collection of those model elements that are positioned to below
 * of the given element's top edge. If no elements are found, the result will
 * be an empty array.
 *
 * @param element the element on which to locate the results.
 * @return {Array} the collection of elements to below the given element.
 */
export function elementsBelow(element) {
    if ((! element) || (! element.parent) || (! element.parent.children)) {
        return [];
    }

    var y = element.y;
    return element.parent.children.filter(function(aShape) {
        // ignore self, labels and connectors
        if ((element === aShape) || (!aShape.type) || (aShape.type === 'label') || (isArray(aShape.waypoints))) {
            return false;
        }

        return (y <= aShape.y + aShape.height);
    });
};

/**
 * Tests if the given line is vertical or horizontal, or neither. The algorithm
 * subtracts the x-axis values of the line ends from each other and if the result
 * is within a given tolerance, the line is determined to be vertical.
 *
 * @param aLine the whose orientation is to be determined.
 * @param aTolerance the tolerance, in degrees, that the line can be either side
 * of horizontal or vertical. If not specified, the default will be 20 degrees.
 * @return {int} 1 = vertical, -1 = horizontal, 0 = neither. undefined means the
 * given line has no way-points.
 */
export function orientation(aLine, aTolerance) {
    if ((! aLine) || (! isArray(aLine.waypoints)) || (aLine.waypoints.length < 2)) {
        return undefined;
    }

    var start = aLine.waypoints[0];
    var end = aLine.waypoints[aLine.waypoints.length - 1];

    var deltaX = end.x - start.x;
    var deltaY = end.y - start.y;

    // calculate the angle ( -180 - 0 - 180 )
    var angleDeg = Math.atan2(deltaY, deltaX) * 180 / Math.PI;

    // anything north of the line will be negative
    // make it positive for ease of comparison
    angleDeg = Math.abs(angleDeg);

    // default tolerance to 20 degrees
    aTolerance = aTolerance || 20;

    // if the line is either side of vertical (with tolerance)
    if ((angleDeg <= 90 + aTolerance) && (angleDeg >= 90 - aTolerance)) {
        return 1; // it's vertical
    }

    // if the line is either side of horizontal (with tolerance)
    if ((angleDeg <= aTolerance) || (angleDeg >= 180 - aTolerance)) {
        return -1; // it's horizontal
    }

    // indeterminate - neither horizontal or vertical
    return 0;
};


/**
 * Returns children of a given shape excluding the shape passed in param 'excludedElement'
 *
 * @param shape
 * @param excludedElement
 * @returns {[]}
 */
export function getChildren(shape, excludedElement) {
    var collectedShapes = [];

    shape.children.filter(function(child) {
        if (excludedElement !== child) {
            collectedShapes.push(child);
        }
    });

    return collectedShapes;
}