'use strict';

import forEach from 'lodash/forEach';
import partition from 'lodash/partition';
import isEmpty from 'lodash/isEmpty';
import inherits from 'inherits';
import DeleteElementsHandler from 'diagram-js/lib/features/modeling/cmd/DeleteElementsHandler';

/**
 *  Handler for deleting the process elements which also includes the elements contain inside the Initial Task SubProcess.
 *
 * @param modeling
 * @param elementRegistry
 * @param processDiagramRules
 * @constructor
 */
function DeleteProcessElementsHandler(modeling, elementRegistry, processDiagramRules) {
    // Super CONSTRUCTOR
    DeleteElementsHandler.call(this, modeling, elementRegistry);

    this._modeling = modeling;
    this._processDiagramRules = processDiagramRules;
}

inherits(DeleteProcessElementsHandler, DeleteElementsHandler);

DeleteProcessElementsHandler.$inject = ['modeling', 'elementRegistry', 'processDiagramRules'];


DeleteProcessElementsHandler.prototype.postExecute = function (context) {

    var processDiagramRules = this._processDiagramRules,
        modeling = this._modeling;


    var result = partition(context.elements, function (element) {
        return element && processDiagramRules.isContainedInInitialTaskSubProcess(element.businessObject);
    });

    // result[0] contains element contained in the SubProcess, result[1] contains elements outside SubProcess
    result[0].forEach(function (subProcessElement) {
        modeling.removeTaskFromSubProcess(subProcessElement.parent, [subProcessElement]);
    });

    if (!isEmpty(result[1])) {
        DeleteProcessElementsHandler.super_.prototype.postExecute.call(this, {elements: result[1]});
    }
};
export default DeleteProcessElementsHandler;