'use strict';

import {getBBox} from "diagram-js/lib/util/Elements";
import {sortBy} from "lodash";


/**
 * A handler for moving the parallel flow lanes within the parallel flow container
 *
 * @class
 * @constructor
 */
function MoveParallelFlowLaneHandler(modeling) {
    this._modeling = modeling;
}

MoveParallelFlowLaneHandler.$inject = ['modeling'];


MoveParallelFlowLaneHandler.prototype.preExecute = function (context) {

    var modeling = this._modeling;

    var srcIndex = parseInt(context.srcIndex),
        destIndex = parseInt(context.destIndex);

    var shapeBeingMoved = context.shape;
    var parent = shapeBeingMoved.parent;
    var children = parent.children;

    // No operation if source and destination indexes are same
    if(srcIndex === destIndex){
        return;
    }

    /* When srcIndex < destIndex that means item is being moved down,
        so
           --- move the shape to destIndex
           --- move all the sibling shapes from (srcIndex + 1) to destIndex up by height of the srcIndex shape
           --- sort all the children shapes according to 'y' position.
    */
    if (srcIndex < destIndex){
        // find shapes to move which will be affected by selected shape move (i.e shapesToMoveUp).
        var shapesToMoveUp = children.slice(srcIndex+1, destIndex+1) || [];

        // Get bounding box for the shapes to know the total height for selected shape to move
        var boundingBox = getBBox(shapesToMoveUp, true);

        // Move the selected shape
        var delta = {x:0, y: boundingBox.height }
        modeling.moveShape(shapeBeingMoved, delta, parent);

        // As selected shape is now moved, move all affected shapes upwards to fill the gap
        shapesToMoveUp.forEach(function (shape){
            var cDelta = {x:0, y: - shapeBeingMoved.height}
            modeling.moveShape(shape, cDelta, parent);
        });

        // Sort children by 'y' position
        var sortedChildren = sortBy(children, 'y') || [];

        // clear the original children shape array
        parent.children.length = 0;
        // added 'y' position sorted shapes to children
        sortedChildren.forEach(function (shape){
            parent.children.push(shape);
        });

        // Update the process model
        updateProcessModel(parent.businessObject, srcIndex, destIndex);
    }

    /* When srcIndex > destIndex that means item is being moved up,
        so
           --- move the item to destIndex
           --- move all the sibling shapes from destIndex to srcIndex down by height of the srcIndex shape
    */

    else if (srcIndex > destIndex){
        // find shapes to move which will be affected by pinned shape move (i.e shapesToMoveUp).
        var shapesToMoveDown = children.slice(destIndex, srcIndex) || [];

        // Get bounding box for the shapes to know the total height for pinned shape to move
        var boundingBox = getBBox(shapesToMoveDown);

        // Move the selected shape
        var delta = {x:0, y: - boundingBox.height }
        modeling.moveShape(shapeBeingMoved, delta, parent);

        // As selected shape is now moved, move all affected shapes upwards to fill the gap
        shapesToMoveDown.forEach(function (shape){
            var cDelta = {x:0, y: shapeBeingMoved.height}
            modeling.moveShape(shape, cDelta, parent);
        });

        // Sort children by 'y' position
        var sortedChildren = sortBy(children, 'y') || [];

        // clear the original children shape array
        parent.children.length = 0;

        // added 'y' position sorted shapes to children
        sortedChildren.forEach(function (shape){
            parent.children.push(shape);
        });

        // Update the process model
        updateProcessModel(parent.businessObject, srcIndex, destIndex);
    }
};

/**
 * Update the process model to move the flowElement present at source index to destination index.
 * @param parallelFlowContainer Container which holds flowElements array
 * @param srcIndex index of flowElement to be moved.
 * @param destIndex index where to move the element
 */
function updateProcessModel(parallelFlowContainer, srcIndex, destIndex){
    var flowElements = parallelFlowContainer.flowElements;
    var value = flowElements[srcIndex];
    if(typeof value !== 'undefined') {
        flowElements.splice(srcIndex, 1);
        flowElements.splice(destIndex, 0, value);
    }
}

/**
 * Overridden revert method to handle the undo operation.
 * @param context
 */
MoveParallelFlowLaneHandler.prototype.revert = function (context) {

    var srcIndex = parseInt(context.srcIndex),
        destIndex = parseInt(context.destIndex),
        shapeBeingMoved = context.shape,
        parent = shapeBeingMoved.parent;

    // revert the flowElement location by swapping the source and destination index.
    updateProcessModel(parent.businessObject, destIndex, srcIndex);
}

export default MoveParallelFlowLaneHandler;