'use strict';

import forEach from 'lodash/forEach';
import {getMid} from 'diagram-js/lib/layout/LayoutUtil';


/**
 * A handler that implements reversible changes needed to set the process to auto start.
 * Internally the first form task shape will be removed and its outgoing connections reattached to the start event.
 *
 *
 * @class
 * @constructor
 */
function SetProcessAutoStartHandler(modeling, rules) {
    this._modeling = modeling;
    this._rules = rules;
}

SetProcessAutoStartHandler.$inject = ['modeling', 'rules'];


/**
 * Removes formShape and reconnect it's outgoing connections to startEventShape.
 *
 * @param {Object} context
 * @param {Object} context.startEventShape the process start event shape
 * @param {Object} context.formTaskShape the process initial form shape
 * @param {Object} context.modelCommands the additional commands that needs to be executed to set up prosess in auto
 *        start state.
 */
SetProcessAutoStartHandler.prototype.postExecute = function (context) {
    var modeling = this._modeling;
    var formTaskShape = context.formTaskShape;
    var startEventShape = context.startEventShape;
    var modelCommands = context.modelCommands;

    var formShapeMid = getMid(formTaskShape);
    var startEventShapeMid = getMid(startEventShape);
    var outgoing = formTaskShape.outgoing.slice();


    forEach(outgoing, function (connection) {
        var waypoints = connection.waypoints;
        modeling.reconnectStart(connection, startEventShape, waypoints);
    });

    //Move startEventShape to where formShape was.
    var delta = this.getDelta(startEventShape, formTaskShape);
    modeling.moveShape(startEventShape, delta, startEventShape.parent);

    modeling.removeShape(formTaskShape);

    forEach(startEventShape.outgoing, function (c) {
        modeling.layoutConnection(c, {connectionStart: formShapeMid});
    });

    if (modelCommands && modelCommands.length >= 0) {
        modeling.runProcessModelCommand(modelCommands)
    }
};


SetProcessAutoStartHandler.prototype.execute = function (context) {
};

SetProcessAutoStartHandler.prototype.revert = function (context) {
};

/**
 * Gets delta between source and target.
 *
 * @param sourceBounds
 * @param targetBounds
 * @returns {{x: number, y: number}}
 */
SetProcessAutoStartHandler.prototype.getDelta = function (sourceBounds, targetBounds) {
    var midSource = getMid(sourceBounds);
    var midTarget = getMid(targetBounds);
    return {
        x: midTarget.x - midSource.x,
        y: midTarget.y - midSource.y
    };
};

export default SetProcessAutoStartHandler;
