'use strict';

import CreateShapeHandler from 'diagram-js/lib/features/modeling/cmd/CreateShapeHandler';
import inherits from 'inherits';

import {instanceOf} from '../ModelUtil';
import {getBusinessObject} from '../ModelUtil';

/**
 * A handler that implements reversible creation of activity tasks and gateways.
 * Delegates to the standard CreateShapeHandler for all other shapes.
 */
function CreateProcessShapeHandler(canvas, modeling) {
    // Super CONSTRUCTOR
    CreateShapeHandler.call(this, canvas);

    this._modeling = modeling;
}

CreateProcessShapeHandler.$inject = [ 'canvas', 'modeling' ];

inherits(CreateProcessShapeHandler, CreateShapeHandler);


/**
 * Overrides CreateShapeHandler. If the given shape is an Activity or Gateway,
 * and has been dropped on a connector, record the connection and set the
 * drop parent as the connection's parent (the model root). This ensures that
 * the shape is not added as a child of the connection.
 * It will then call the CreateShapeHandler.
 *
 * @param context the context in which the create is performed. Carries all
 * the data about the creation.
 */
CreateProcessShapeHandler.prototype.preExecute = function(context) {
    // if the shape is an activity or gateway AND the target is a connection
    if ((instanceOf(getBusinessObject(context.shape), ['bp:Activity', 'bp:Gateway'])) &&
        (instanceOf(getBusinessObject(context.parent), 'bp:SequenceFlow'))) {
        // store the connection reference
        context.connection = context.parent;

        // set the connection's parent as the parent of the new shape
        context.parent = context.parent.parent;
    }

    // call the default implementation of preExecute
    if (CreateShapeHandler.prototype.preExecute) {
        CreateShapeHandler.prototype.preExecute.call(this, context);
    }
};

/**
 * Overrides CreateShapeHandler. If the given shape is an Activity
 * or Gateway, and has been dropped on a connector, it will intersect
 * the connector; adding the connector as an incoming flow and creating
 * a new connector as an outgoing flow to the original connector's
 * target.
 * Calls CreateShapeHandler first.
 *
 * @param context the context in which the create is performed. Carries all
 * the data about the move.
 * @param context.connection if the drop was on a connection, this is that
 * connection.
 */
CreateProcessShapeHandler.prototype.postExecute = function(context) {
    // call the default implementation of postExecute
    if (CreateShapeHandler.prototype.postExecute) {
        CreateShapeHandler.prototype.postExecute.call(this, context);
    }

    // if this was a drop on a connection
    if (context.connection) {
        // intersect the connection with the new shape
        this._modeling.intersectConnection(context.connection, context.shape);
    }
};
export default CreateProcessShapeHandler;
