'use strict';


import assign from 'lodash/assign';

/**
 * Context pad provider. This provides context pad support for RHS side pad on the Shape.
 * Adds 'append' and 'connect' action gadgets
 */
function AppendContextPadProvider(dtContextPad, modeling, elementFactory,
                                connect, create, processDiagramRules) {

    dtContextPad.registerProvider(this);
    this._modeling = modeling;
    this._elementFactory = elementFactory;
    this._connect = connect;
    this._create = create;
    this._processDiagramRules = processDiagramRules;
}

AppendContextPadProvider.$inject = [
    'dtContextPad',
    'modeling',
    'elementFactory',
    'connect',
    'create',
    'processDiagramRules'
];



AppendContextPadProvider.prototype.getContextPadEntries = function (element) {

    var elementFactory = this._elementFactory,
        connect = this._connect,
        create = this._create;
    var processDiagramRules = this._processDiagramRules;
    var modeling = this._modeling;

    var actions = {};

    /*
    * CBPM-15568 :- Chaitanya , to avoid showing process-editor-toolbox on when the element is hidden
    */
    if (element.type === 'label' || element.hidden) {
        return actions;
    }

    function startConnect(event, element, autoActivate) {
        /*
         * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
         * Changed the format of passing parameters to start Function.
         * */
        connect.start(event, element);
    }

    function appendTask(event, element) {
        var shape = elementFactory.createShape(assign({type: 'bp:EmptyTask'}));
        /*
         * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
         * Changed the format of passing parameters to start Function.
         * */
        create.start(event, shape, {
            source: element
        });
    }

    function appendParallelFlowContainer(event, element) {
        var shapes = modeling.createInitialParallelFlowContainerShapes(element) || [];

        var parallelLaneContainer = shapes[0];
        create.start(event, shapes, {
            hints: {
                autoSelect: [parallelLaneContainer],
                connectionSource: element,
                connectionTarget: parallelLaneContainer,
                isAppend : true
            }
        });
    }

    function appendDecisionPoint(event, element) {
        var shape = elementFactory.createShape(assign({type: 'bp:ExclusiveGateway'}));
        /*
         * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
         * Changed the format of passing parameters to start Function.
         * */
        create.start(event, shape, {
            source: element
        });
    }

    function appendEndEvent(event, element) {
        var shape = elementFactory.createShape(assign({type: 'bp:EndEvent'}));
        /*
         * Chaitanya CBPM: 20494 Upgrading Diagram to Latest Version
         * Changed the format of passing parameters to start Function.
         * */
        create.start(event, shape, {
            source: element
        });
    }

    if (processDiagramRules.isSequenceFlowSource(element)) {
        /* Add gadgets */
        assign(actions, {
            'task': {
                group: 'taskAppend',
                className: 'dt-bpm-icon-ic_task dt-hand-pointer',
                title: 'Append task',
                action: {
                    click: appendTask,
                    dragstart: appendTask
                }
            }
        });

        // Add gadget only if selected element is not inside the Parallel flow lane.
        if(!processDiagramRules.isContainedInParallelFlowLane(element)) {
            assign(actions, {
                'parallelFlowContainer': {
                    group: 'parallelFlowAppend',
                    className: 'dt-bpm-icon-ic_parallel_flows dt-hand-pointer',
                    title: 'Append parallel flow container',
                    action: {
                        click: appendParallelFlowContainer,
                        dragstart: appendParallelFlowContainer
                    }
                }
            });
        }

        assign(actions, {
            'gateway': {
                group: 'decisionPointAppend',
                className: 'dt-bpm-icon-ic_decision_point dt-hand-pointer',
                title: 'Append decision point',
                action: {
                    click: appendDecisionPoint,
                    dragstart: appendDecisionPoint
                }
            }
        });
        assign(actions, {
            'endevent': {
                group: 'endEventAppend',
                className: 'dt-bpm-icon-ic_endpoint dt-hand-pointer',
                title: 'Append end event',
                action: {
                    click: appendEndEvent,
                    dragstart: appendEndEvent
                }
            }
        });

        // Connect
        assign(actions, {
            'connect': {
                group: 'connect',
                className: 'dt-icon-connect dt-hand-pointer',
                title: 'Connect with other activities',
                action: {
                    click: startConnect,
                    dragstart: startConnect
                }
            }
        });
    }

    return actions;
};

export default AppendContextPadProvider;