import commandModule from '../command';
import tooltipsModule from 'diagram-js/lib/features/tooltips';
import labelSupportModule from 'diagram-js/lib/features/label-support';
import attachSupportModule from 'diagram-js/lib/features/attach-support';
import selectionModule from 'diagram-js/lib/features/selection';
import changeSupportModule from 'diagram-js/lib/features/change-support';
import spaceToolModule from '../space-tool';

import Modeling from './Modeling';
import ElementFactory from './ElementFactory';
import ProcessLayouter from './layout/ProcessLayouter';
import DiagramLoader from './DiagramLoader';
import ModelUpgrader from './ModelUpgrader';
import ModelSynchronizer from './ModelSynchronizer';
import CroppingConnectionDocking from 'diagram-js/lib/layout/CroppingConnectionDocking';
import LabelSupport from './LabelSupport';


export default {
    __depends__: [
        commandModule,
        tooltipsModule,
        labelSupportModule,
        attachSupportModule,
        selectionModule,
        changeSupportModule,
        spaceToolModule
    ],
    __init__: ['modeling', 'diagramLoader', 'modelUpgrader', 'modelSynchronizer', 'processLabelSupport'],
    modeling: ['type', Modeling],
    elementFactory: ['type', ElementFactory],
    layouter: ['type', ProcessLayouter],
    diagramLoader: ['type', DiagramLoader],
    modelUpgrader: ['type', ModelUpgrader],
    modelSynchronizer: ['type', ModelSynchronizer],
    connectionDocking: ['type', CroppingConnectionDocking],
    processLabelSupport: ['type', LabelSupport]
};
