/**
 * Gets descendant properties of an object as specified in a 'desc' string.
 *
 * @param {object} obj - context object.
 * @param {string} desc - the string of comma separated nested object propertis.
 *
 * @returns {*} The value of the property.
 */
function getDescendantProp(obj, desc) {
    var arr = desc.split('.');
    while (arr.length) {
        obj = obj[arr.shift()];
    }
    return obj;
}

var selectPropRegEx = /\{(.*?)\}/g; //Regexp to selects properties in {}.

/**
 * Formats string replacing object properties included in {}.
 * @param str string to format.
 * @param obj object with properties.
 */
export default function format(str, obj) {
    return str.replace(selectPropRegEx, function (_, k) {
        return getDescendantProp(obj, k);
    });
}
