'use strict';

import {instanceOf} from '../modeling/ModelUtil';
import  {getBBox} from 'diagram-js/lib/util/Elements';
import * as Geometry from 'diagram-js/lib/util/Geometry';

/**
 * DT implementation of diagram js overlays to provide general overlay icons on diagram elements
 *
 * @param eventBus
 * @param overlays
 * @constructor
 */
function AnnotationOverlays(eventBus, overlays) {

    this._eventBus = eventBus;
    this._overlays = overlays;
}

AnnotationOverlays.$inject = ['eventBus', 'overlays'];

/**
 * JSON map from annotation ID -> callback function so as to execute the correct
 * callback whenever a particular overlay has been cicked.
 * @type {*[]}
 */
AnnotationOverlays.prototype.annotationIdToCallbackMap = [];

/**
 * Adds the overlay (particular 'annotation') on the given element with given annotation info
 *
 * @param element - diagram element on which the overlay icon is shown
 * @param annotationInfo - info object that has the icon source and tooltip text to be shown
 */
AnnotationOverlays.prototype.addAnnotation = function(element, annotationInfoList) {

    var existingOverlays = this.getAnnotationOverlay(element);
    if (existingOverlays.length > 0) {
        // Don't add if there's already an overlay
        return;
    }

    for (var i=0; i < annotationInfoList.length; i++) {

        var annotationInfo = annotationInfoList[i];

        var tooltipText = annotationInfo.msg;

        var overlayDivId = element.id + "-annotation" + i;

        this.annotationIdToCallbackMap.push({
            id: overlayDivId,
            callbackFn: annotationInfo.overlayClickCallback
        });

        // Keep track of the latest annotation->callback map as 'this' is bound to change
        var annotationIdToCallbackObj = this.annotationIdToCallbackMap;

        var overlayHtml = "<div class='overlay-todo-tooltip' id='" + overlayDivId + "' on-click='annotationInfo.overlayClickCallback(element)'><span class='overlay-todo-tooltiptext'>" + tooltipText +
            "</span><input id='" + element.id + "' type='image' class='validation-overlay-icon' src='" +
            annotationInfo.iconSrc + "' /></div>";

        /* define the location for overlay icon for all rectangular shapes (for tasks) */
        var position = {
            top: 7,
            left: 115 - 22*i
        };

        var bo = element.businessObject || element;

        if (instanceOf(bo, 'bp:SubProcess')) {
            if(bo.subProcessType === 'ParallelLane' || bo.subProcessType === 'ParallelLaneContainer'){
                var leftPadding = 6;
                position.left = leftPadding + 22*i;
                position.top = 12;
            }
            else {
                position.left = 248 - 22*i;
            }

        } else if (instanceOf(bo, 'bp:Gateway')) {
            /* define the location for overlay icon for decision points */
            position = {
                top: 8,
                left: 22 + 19*i
            };
        } else if (instanceOf(bo, 'bp:Event')) {
            /* define the location for overlay icon for events */
            position = {
                top: 1,
                left: 21 + 19*i
            };
        } else if (instanceOf(bo, 'bp:SequenceFlow')) {

            /* Get the bounding box for the connection */
            var bbox = getBBox(element);

            /* Get the start and end segment */
            var segmentStart = element.waypoints[0];
            var segmentEnd = element.waypoints[1];

            /* Get the middle point between the start and end segments */
            var mid = Geometry.getMidPoint(segmentStart, segmentEnd);

            /* Default values */
            var left = 20 - 19*i;
            var top = 5;

            /* put the icon half way thru the first segment of the flow */
            if (mid.x - bbox.x !== 0) {

                left = mid.x - bbox.x + 19 - 19*i;
            }
            if (mid.y - bbox.y !== 0) {

                top = mid.y - bbox.y;
            }

            position = {
                left: left,
                top: top
            };
        }

        var overlayId = this._overlays.add(element, 'annotation', {
            position: position,
            html: overlayHtml
        });

        /**
         * Wrapper method to trigger the callback for current overlay.
         * @param elementId
         */
        function callbackForThisOverlay(elementId, event, element) {
            if (annotationIdToCallbackObj && annotationIdToCallbackObj.length > 0) {
                for (var j = 0; j < annotationIdToCallbackObj.length; j++) {
                    if (annotationIdToCallbackObj[j] &&
                        annotationIdToCallbackObj[j].id == elementId &&
                        ((typeof annotationIdToCallbackObj[j].callbackFn === 'function') || angular.isFunction(annotationIdToCallbackObj[j].callbackFn))) {

                        annotationIdToCallbackObj[j].callbackFn(event, element);

                    }
                }
            }
        }


        if(element.renderRoot) {
            element.renderRoot.querySelector("#" + element.id + "-annotation" + i).onclick = function (event) {
                callbackForThisOverlay(this.id, event, element);
            }
        }
        else {
            /* invoke the callback function on click event */
            document.getElementById(element.id + "-annotation" + i).onclick = function () {
                callbackForThisOverlay(this.id, element);
            };
        }

        
    }
};

/**
 * Return the overlays for the given diagram element. Checks for the particular 'annotation' overlay.
 *
 * @param element - on which overlays might exist(s)
 * @returns {*} - the overlays array if it exists, empty list otherwise
 */
AnnotationOverlays.prototype.getAnnotationOverlay = function (element) {

    var overlays = this._overlays;
    var annotations = overlays.get({element: element, type: 'annotation'});
    return annotations;
};

/**
 * Remove the overlay for the given diagram element. Checks for the particular 'annotation' overlay.
 *
 * @param element - on which overlay is to be removed
 */
AnnotationOverlays.prototype.removeAnnotation = function(element) {

    var overlays = this._overlays;
    var annotations = overlays.get({element: element, type: 'annotation'});

    if (annotations && annotations.length) {
        annotations.forEach(function (t) {
            overlays.remove(t.id);
        });
    }
};

export default AnnotationOverlays;